import net.runelite.api.events.NpcSpawned;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ClientShutdown;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.Text;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Codex Archive Splits",
	description = "Splits, personal bests, purples and supply checks for the Fractured Archive raid",
	tags = {"raid", "raids", "fractured archive", "archive", "splits", "timer", "pb", "purple", "codex"}
)
public class CodexArchivePlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(CodexArchivePlugin.class);
	private static final String ARCHIVE_KEY = "archive";
	/** Where a damaged save is set aside, as it was, before the archive read from it is saved over it. */
	private static final String DAMAGED_KEY = "archiveDamaged";
	/** How long after a clear uniques landing in the pack are still its loot, five minutes, or until the bank opens. */
	private static final int LOOT_TICKS = 500;
	/** How long the plaque keeps showing a clear while the player is still inside, half a minute. */
	private static final int CLEARED_TICKS = 50;
	private static final int SAVE_TICKS = 50;

	/** The lobby's own NPCs: seeing one means the next instance is the archive. */
	private static final String[] LOBBY_NPCS = {"record keeper", "general montoya"};
	/** The same NPCs by id: the Record Keeper, the lobby's banker and General Montoya. */
	private static final int[] LOBBY_NPC_IDS = {16692, 16704, 16705};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private Gson gson;

	@Inject
	private CodexArchiveConfig config;

	@Inject
	private ScheduledExecutorService executor;

	private final RunTracker tracker = new RunTracker();
	private final Presence presence = new Presence();
	private final LootWatch loot = new LootWatch();
	private final SplitsPlaque splitsPlaque = new SplitsPlaque();
	private final PackPlaque packPlaque = new PackPlaque();
	private Map<Supply, Integer> pack = new EnumMap<>(Supply.class);

	private ArchivePanel panel;
	private NavigationButton navButton;

	private String profile;
	private Archive archive;
	private boolean unsaved;
	/** The copy the panel last got; copied again only when the archive changes, not on every tick of a run. */
	private Archive shown;
	private boolean changed;
	private boolean dirty;
	private int tick;
	private int runEnded = Integer.MIN_VALUE / 2;
	/** The run just recorded when it was a clear, for the plaque while the player is still inside. */
	private Run lastClear;
	private boolean wipeAnnounced;
	/** The furthest row whose split has gone to the chat box this run. */
	private int announcedRow;

	@Provides
	CodexArchiveConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CodexArchiveConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new ArchivePanel();
		navButton = NavigationButton.builder()
			.tooltip("Codex Archive Splits")
			.icon(Sigil.icon(16))
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		applyConfig();
		overlayManager.add(splitsPlaque);
		overlayManager.add(packPlaque);
		panel.onDelete(this::deleteRun, this::deleteDrop);
		panel.onNotes((at, role) -> annotate(a -> a.setRole(at, role)), (at, note) -> annotate(a -> a.setNote(at, note)));
		panel.onExport(this::export);
		panel.onSaveCard(this::saveCard);
		panel.onGoal((bucket, ticks) -> annotate(a ->
		{
			a.setGoal(bucket, ticks);
			return true;
		}));
		clientThread.invokeLater(() ->
		{
			loadProfile();
			readPack();
			WorldView view = client.getTopLevelWorldView();
			if (view != null)
			{
				int lobby = 0;
				for (NPC npc : view.npcs())
				{
					lobby += isLobbyNpc(npc) ? 1 : 0;
				}
				presence.lobbyNpcsInView(lobby, tick);
			}
			publish();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(splitsPlaque);
		overlayManager.remove(packPlaque);
		clientToolbar.removeNavigation(navButton);
		clientThread.invokeLater(() ->
		{
			if (tracker.isActive())
			{
				// The plugin is going off mid-run; what was timed so far is kept rather than lost.
				endRun();
			}
			loot.close();
			presence.reset();
			save();
			archive = null;
			shown = null;
			profile = null;
		});
		panel = null;
	}

	private void applyConfig()
	{
		splitsPlaque.setEnabled(config.showPlaque());
		packPlaque.setEnabled(config.packPlaque());
		ArchivePanel view = panel;
		boolean nameOnCard = config.nameOnCard();
		if (view != null)
		{
			SwingUtilities.invokeLater(() -> view.setNameOnCard(nameOnCard));
		}
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		// ConfigManager writes its changes to disk in this same event, before a save queued on the
		// client thread runs, so a save made here has to be sent on by hand or it is never written.
		CompletableFuture<Void> done = new CompletableFuture<>();
		clientThread.invokeLater(() ->
		{
			try
			{
				// Closing the client mid-run logs out of it, as the logout screen would: what was timed is kept.
				boolean wrote = false;
				if (tracker.isActive())
				{
					endRun();
					wrote = true;
				}
				wrote |= save();
				if (wrote)
				{
					configManager.sendConfig();
				}
			}
			finally
			{
				done.complete(null);
			}
		});
		event.waitFor(done);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CodexArchiveConfig.GROUP.equals(event.getGroup()))
		{
			applyConfig();
			dirty = true;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOADING)
		{
			presence.sceneLoaded(tick);
		}
		else if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			if (tracker.isActive())
			{
				endRun();
			}
			presence.reset();
			loot.close();
			lastClear = null;
			save();
			dirty = true;
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		if (tracker.isActive())
		{
			// The account is changing under a run, as on logging out before the login screen shows:
			// the run belongs to the account it was timed on, so it is put away there first.
			endRun();
		}
		save();
		loadProfile();
		publish();
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		if (isLobbyNpc(npc))
		{
			presence.lobbyNpc(true, tick);
			dirty = true;
			return;
		}
		Encounter beaten = Encounter.fallMarker(npc.getId());
		if (beaten != null && tracker.isActive())
		{
			// The Guardian's husk or Xarth's corpse arriving is surer than any death animation.
			tracker.fell(beaten, tick, false);
			dirty = true;
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		NPC npc = event.getNpc();
		if (isLobbyNpc(npc))
		{
			presence.lobbyNpc(false, tick);
			dirty = true;
		}
		else if (tracker.isActive() && (npc.isDead() || npc.getHealthRatio() == 0))
		{
			// Some bosses leave without the client reporting a death; a body leaving at no health is a fall.
			bossFell(npc);
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Actor actor = event.getActor();
		if (!(actor instanceof NPC) || !presence.isInInstance())
		{
			return;
		}
		NPC npc = (NPC) actor;
		if (npc.isDead())
		{
			// A hit landing on a body is not a fight going on.
			return;
		}
		Encounter encounter = Encounter.of(npc.getId(), npc.getName());
		if (!tracker.isActive() && encounter == Encounter.GUARDIAN)
		{
			// The lobby was missed, but the Guardian is unmistakable: the run began on entering.
			beginRun(presence.likelyStart(tick));
		}
		if (!tracker.isActive())
		{
			return;
		}
		String name = npc.getName() == null ? null : Text.removeTags(npc.getName());
		if (encounter != null)
		{
			tracker.engage(encounter, tick, name, npc.getCombatLevel());
			dirty = true;
		}
		else
		{
			// Kept so a boss that goes unrecognised can show what the run did see.
			tracker.foe(name, npc.getCombatLevel());
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		Actor actor = event.getActor();
		if (!tracker.isActive())
		{
			return;
		}
		if (actor == client.getLocalPlayer())
		{
			tracker.died();
			dirty = true;
			return;
		}
		if (actor instanceof NPC)
		{
			bossFell((NPC) actor);
		}
	}

	/** A boss NPC went down; the split closes once nothing else of its encounter stands. */
	private void bossFell(NPC npc)
	{
		Encounter encounter = Encounter.of(npc.getId(), npc.getName());
		if (encounter == null || !Encounter.isFinalForm(npc.getId()))
		{
			// Ocellus's first two phases only give way to the next.
			return;
		}
		boolean anyAlive = false;
		WorldView view = client.getTopLevelWorldView();
		if (view != null)
		{
			for (NPC other : view.npcs())
			{
				if (other != npc && !other.isDead() && other.getHealthRatio() != 0
					&& Encounter.of(other.getId(), other.getName()) == encounter)
				{
					anyAlive = true;
					break;
				}
			}
		}
		tracker.fell(encounter, tick, anyAlive);
		dirty = true;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		String text = event.getMessage();
		int count = Messages.completionCount(text);
		if (count >= 0)
		{
			if (tracker.isActive())
			{
				// The game's own word that the archive is cleared: the run is complete, whatever was seen of the last boss.
				tracker.kc(count);
				tracker.complete(tick);
				endRun();
			}
			if (archive != null)
			{
				archive.kc(count, System.currentTimeMillis());
				unsaved = true;
				changed = true;
			}
			dirty = true;
		}
		if (tracker.isActive() && Messages.isWipe(text))
		{
			wipeAnnounced = true;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id == InventoryID.INV)
		{
			readPack();
		}
		if (id == InventoryID.INV || id == InventoryID.WORN)
		{
			watchLoot();
		}
		else if (id == InventoryID.BANK && !tracker.isActive())
		{
			// Anything from here on could have come out of the bank.
			loot.close();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		tick++;
		WorldView view = client.getTopLevelWorldView();
		boolean instance = view != null && view.isInstance();
		Presence.Action action = presence.tick(tick, instance, tracker.isActive(), tracker.elapsed(tick));
		if (action == Presence.Action.END)
		{
			endRun();
		}
		else if (action == Presence.Action.BEGIN)
		{
			beginRun(presence.beginTick());
		}

		if (tracker.isActive())
		{
			if (tracker.nextRow() == 0 && view != null)
			{
				tracker.seeTeam(count(view));
				tracker.seeCrew(crew(view));
			}
			tracker.tick(tick);
			int row = tracker.nextRow();
			if (row > announcedRow)
			{
				announceSplit(row - 1);
				announcedRow = row;
			}
			else if (row < announcedRow)
			{
				// A boss came back after its split closed; its true time goes to the chat box when it falls again.
				announcedRow = row;
			}
			dirty = true;
		}
		if (lastClear != null && (tick - runEnded > CLEARED_TICKS || !instance))
		{
			lastClear = null;
			dirty = true;
		}
		if (unsaved && tick % SAVE_TICKS == 0)
		{
			save();
		}
		if (dirty)
		{
			publish();
		}
	}

	private static int count(WorldView view)
	{
		int n = 0;
		for (Player ignored : view.players())
		{
			n++;
		}
		return n;
	}

	/** The other raiders in view, by their names as the game shows them. */
	private List<String> crew(WorldView view)
	{
		List<String> names = new ArrayList<>();
		Player me = client.getLocalPlayer();
		for (Player p : view.players())
		{
			if (p != null && p != me && p.getName() != null)
			{
				names.add(Text.sanitize(p.getName()));
			}
		}
		return names;
	}

	private static boolean isLobbyNpc(NPC npc)
	{
		for (int id : LOBBY_NPC_IDS)
		{
			if (npc.getId() == id)
			{
				return true;
			}
		}
		String name = npc.getName();
		if (name == null)
		{
			return false;
		}
		String lower = name.toLowerCase();
		for (String n : LOBBY_NPCS)
		{
			if (lower.equals(n))
			{
				return true;
			}
		}
		return false;
	}

	private void beginRun(int at)
	{
		WorldView view = client.getTopLevelWorldView();
		tracker.begin(System.currentTimeMillis(), at, view == null ? 1 : count(view), pack);
		if (view != null)
		{
			tracker.seeCrew(crew(view));
		}
		loot.open(heldUniques());
		announcedRow = 0;
		wipeAnnounced = false;
		lastClear = null;
		dirty = true;
	}

	private void endRun()
	{
		List<String> purples = tracker.purples();
		Run run = tracker.finish(tick, wipeAnnounced);
		runEnded = tick;
		wipeAnnounced = false;
		if (run == null)
		{
			return;
		}
		if (run.isCompleted())
		{
			loot.closeAt(tick + LOOT_TICKS);
		}
		else
		{
			loot.close();
		}
		long now = System.currentTimeMillis();
		if (archive != null)
		{
			if (run.isCompleted() || !run.getSplits().isEmpty())
			{
				archive.record(run, purples, now);
				if (run.isCompleted())
				{
					lastClear = run;
					announceRun(run);
				}
			}
			else
			{
				// Too little of a run to keep, but a purple is a purple.
				purples.forEach(u -> archive.purple(u, now));
			}
			unsaved = true;
			changed = true;
		}
		save();
		dirty = true;
	}

	/** Counts the supplies in the pack. */
	private void readPack()
	{
		Map<Supply, Integer> units = new EnumMap<>(Supply.class);
		ItemContainer container = client.getItemContainer(InventoryID.INV);
		if (container != null)
		{
			for (Item item : container.getItems())
			{
				if (item.getId() < 0 || item.getQuantity() <= 0)
				{
					continue;
				}
				String name = itemManager.getItemComposition(item.getId()).getName();
				Supply supply = Supply.of(name);
				if (supply != null)
				{
					units.merge(supply, supply.units(name) * item.getQuantity(), Integer::sum);
				}
			}
		}
		pack = units;
		tracker.pack(units);
		dirty = true;
	}

	/** The uniques held now, in the pack and worn, by the panel's name for them. */
	private Map<String, Integer> heldUniques()
	{
		Map<String, Integer> held = new HashMap<>();
		for (int id : new int[]{InventoryID.INV, InventoryID.WORN})
		{
			ItemContainer container = client.getItemContainer(id);
			if (container == null)
			{
				continue;
			}
			for (Item item : container.getItems())
			{
				if (item.getId() < 0 || item.getQuantity() <= 0)
				{
					continue;
				}
				String unique = Spoils.unique(item.getId(), itemManager.getItemComposition(item.getId()).getName());
				if (unique != null)
				{
					held.merge(unique, item.getQuantity(), Integer::sum);
				}
			}
		}
		return held;
	}

	/** A unique arriving during a run, or just after a clear, is a purple. */
	private void watchLoot()
	{
		if (archive == null || !loot.isOpen(tick))
		{
			return;
		}
		for (String unique : loot.arrivals(heldUniques(), tick))
		{
			if (tracker.isActive())
			{
				tracker.purple(unique);
			}
			else
			{
				archive.purple(unique, System.currentTimeMillis());
				unsaved = true;
				changed = true;
			}
			dirty = true;
		}
	}

	private void deleteRun(long startedAt)
	{
		clientThread.invokeLater(() ->
		{
			if (archive != null && archive.removeRun(startedAt))
			{
				unsaved = true;
				changed = true;
				save();
				publish();
			}
		});
	}

	/** A role or note the player wrote on a run in the panel. */
	private void annotate(java.util.function.Predicate<Archive> change)
	{
		clientThread.invokeLater(() ->
		{
			if (archive != null && change.test(archive))
			{
				unsaved = true;
				changed = true;
				save();
				publish();
			}
		});
	}

	/** Asks where to save the run history with RuneLite's own file chooser, then writes it there; runs on the Swing thread. */
	private void export()
	{
		ArchivePanel view = panel;
		Archive copy = view == null ? null : view.archive();
		if (copy == null)
		{
			return;
		}
		List<Filepath> chosen = new Filepath.Chooser()
			.setIsSave()
			.setAcceptsFiles()
			.setDialogTitle("Save Fractured Archive runs")
			.addExtensionFilter("Spreadsheet (CSV)", "csv")
			.setDefaultExtension("csv")
			.setFileName("Fractured Archive runs.csv")
			.showDialog(view);
		if (chosen == null || chosen.isEmpty())
		{
			return;
		}
		Filepath target = chosen.get(0);
		String csv = Export.csv(copy.getRuns(), ZoneId.systemDefault());
		executor.execute(() ->
		{
			try
			{
				target.write(csv);
			}
			catch (IOException e)
			{
				log.warn("Could not save the run history", e);
			}
		});
	}

	/** Asks where to save a run or session card with RuneLite's own file chooser, then writes it there; runs on the Swing thread. */
	private void saveCard(BufferedImage card, String name)
	{
		ArchivePanel view = panel;
		if (view == null)
		{
			return;
		}
		List<Filepath> chosen = new Filepath.Chooser()
			.setIsSave()
			.setAcceptsFiles()
			.setDialogTitle("Save card")
			.addExtensionFilter("PNG image", "png")
			.setDefaultExtension("png")
			.setFileName(name + ".png")
			.showDialog(view);
		if (chosen == null || chosen.isEmpty())
		{
			return;
		}
		Filepath target = chosen.get(0);
		executor.execute(() ->
		{
			String note;
			try (OutputStream out = target.openOutputStream())
			{
				ImageIO.write(card, "png", out);
				note = "Card saved as " + target.getFileName() + ".";
			}
			catch (IOException e)
			{
				log.warn("Could not save the card", e);
				note = "The card could not be saved: " + e.getMessage();
			}
			String shown = note;
			SwingUtilities.invokeLater(() -> view.cardNote(shown));
		});
	}

	private void deleteDrop(long at, String unique)
	{
		clientThread.invokeLater(() ->
		{
			if (archive != null && archive.removeDrop(at, unique))
			{
				unsaved = true;
				changed = true;
				save();
				publish();
			}
		});
	}

	private void announceSplit(int row)
	{
		Run live = tracker.view(tick);
		Split split = live == null ? null : live.split(row);
		if (!config.chatSplits() || split == null || !split.isDone() || archive == null)
		{
			return;
		}
		Comparison.Mode mode = config.compareTo();
		Comparison against = Comparison.of(archive, Records.bucket(live.getTeamSize()), mode, live);
		Integer delta = against.delta(live, row);
		mode = against.getMode();
		ChatMessageBuilder line = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT).append(split.getEncounter().getShortName())
			.append(ChatColorType.NORMAL).append(" down at " + Format.ticks(split.getEndTick()));
		if (delta != null)
		{
			line.append(", ").append(ChatColorType.HIGHLIGHT).append(Format.versus(delta, mode.getNoun())).append(ChatColorType.NORMAL);
		}
		line.append(". Room " + Format.ticks(split.roomTicks(0)) + ", fight " + Format.ticks(split.fightTicks(0)) + ".");
		chat(line);
	}

	private void announceRun(Run run)
	{
		if (!config.chatSplits() || archive == null)
		{
			return;
		}
		Run best = null;
		int bucket = Records.bucket(run.getTeamSize());
		for (Run r : archive.getRuns())
		{
			if (r != run && r.isCompleted() && Records.bucket(r.getTeamSize()) == bucket && (best == null || r.getTicks() < best.getTicks()))
			{
				best = r;
			}
		}
		ChatMessageBuilder line = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT).append("Archive cleared in " + Format.ticks(run.getTicks()))
			.append(ChatColorType.NORMAL).append(" (" + Records.BUCKETS[bucket].toLowerCase() + ")");
		if (best == null)
		{
			line.append(", your first " + Records.BUCKETS[bucket].toLowerCase() + " clear.");
		}
		else if (run.getTicks() < best.getTicks())
		{
			line.append(ChatColorType.HIGHLIGHT).append(", a new personal best by " + Format.span(best.getTicks() - run.getTicks()) + ".");
		}
		else
		{
			line.append(", " + Format.versus(run.getTicks() - best.getTicks()) + ".");
		}
		int goal = archive.goal(bucket);
		if (goal > 0 && run.getTicks() <= goal && Goal.of(archive.getRuns(), bucket, goal).getBeaten() == 1)
		{
			// The history already holds this run, so it is the only one under the goal.
			line.append(ChatColorType.HIGHLIGHT).append(" Your goal of " + Format.clock(goal) + " is beaten for the first time.");
		}
		chat(line);
	}

	private void chat(ChatMessageBuilder line)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT).append("Codex Archive: ")
				.append(ChatColorType.NORMAL).build() + line.build())
			.build());
	}

	private void loadProfile()
	{
		profile = configManager.getRSProfileKey();
		archive = null;
		if (profile == null)
		{
			return;
		}
		String saved = configManager.getRSProfileConfiguration(CodexArchiveConfig.GROUP, ARCHIVE_KEY);
		Archive.Loaded read = Archive.read(gson, saved);
		if (read.damaged)
		{
			// The save as it was is kept aside before anything is written over it.
			log.warn("The saved archive was damaged; kept what still reads and set the save as it was aside");
			configManager.setConfiguration(CodexArchiveConfig.GROUP, profile, DAMAGED_KEY, saved);
		}
		archive = read.archive != null ? read.archive : new Archive();
		unsaved = false;
		shown = null;
		dirty = true;
	}

	/** Writes to the profile if anything changed, and says whether it did. */
	private boolean save()
	{
		if (profile == null || archive == null || !unsaved)
		{
			return false;
		}
		unsaved = false;
		configManager.setConfiguration(CodexArchiveConfig.GROUP, profile, ARCHIVE_KEY, gson.toJson(archive));
		return true;
	}

	private Map<Supply, Integer> targets()
	{
		Map<Supply, Integer> t = new EnumMap<>(Supply.class);
		t.put(Supply.FOOD, config.food());
		t.put(Supply.BREWS, config.brews());
		t.put(Supply.RESTORES, config.restores());
		t.put(Supply.BOOSTS, config.boosts());
		return t;
	}

	private void publish()
	{
		dirty = false;
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		Player player = client.getLocalPlayer();
		if (archive == null)
		{
			shown = null;
		}
		else if (shown == null || changed)
		{
			shown = archive.copy();
		}
		changed = false;
		Archive copy = shown;
		Run live = tracker.view(tick);
		boolean inLobby = loggedIn && presence.isInLobby() && !tracker.isActive();
		View view = new View(loggedIn && player != null ? player.getName() : null, loggedIn, copy, live, inLobby,
			pack, targets(), System.currentTimeMillis(), live == null ? lastClear : null, config.compareTo());
		splitsPlaque.show(view);
		packPlaque.show(view);
		ArchivePanel target = panel;
		if (target != null)
		{
			SwingUtilities.invokeLater(() -> target.update(view));
		}
	}
}

package com.codex.archive.core;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import java.io.IOException;
import java.io.StringReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;

/**
 * Everything kept for one account: the run history, the purples and the completion count. Saved
 * as one blob per RuneScape profile.
 */
public class Archive
{
	/**
	 * Runs kept in the history. The oldest go first, except any run holding a record, so a
	 * personal best is never lost to age. Clears and wipes are counted apart, so they never drop.
	 */
	public static final int MAX_RUNS = 500;
	/** The latest runs that keep what each boss was told from; older runs keep only their times. */
	public static final int DOUBT_RUNS = 30;
	/** How long after a run its loot still counts as that run's, ten minutes. */
	private static final long LOOT_WINDOW_MS = 10 * 60_000L;

	private List<Run> runs = new ArrayList<>();
	private List<Drop> drops = new ArrayList<>();
	/** The last completion count the game announced. */
	private int kc;
	/** Completions since the last purple. */
	private int dry;
	/** Clears and wipes by party-size group, for the whole history, kept runs or not. */
	private int[] clears;
	private int[] wipes;
	/** The goal time for each party-size group, in ticks; 0 where none is set. */
	private int[] goals;

	public List<Run> getRuns()
	{
		return Collections.unmodifiableList(runs);
	}

	public List<Drop> getDrops()
	{
		return Collections.unmodifiableList(drops);
	}

	public int getKc()
	{
		return kc;
	}

	public int getDry()
	{
		return dry;
	}

	/** Clears in a party-size group, over the whole history. */
	public int clears(int bucket)
	{
		return bucket >= 0 && clears != null && bucket < clears.length ? clears[bucket] : 0;
	}

	/** Wipes in a party-size group, over the whole history. */
	public int wipes(int bucket)
	{
		return bucket >= 0 && wipes != null && bucket < wipes.length ? wipes[bucket] : 0;
	}

	/** The goal time set for a party-size group, in ticks, or 0 when there is none. */
	public int goal(int bucket)
	{
		return goals != null && bucket >= 0 && bucket < goals.length ? Math.max(0, goals[bucket]) : 0;
	}

	/** Sets the goal time for a party-size group, or clears it with 0. */
	public void setGoal(int bucket, int ticks)
	{
		if (bucket < 0 || bucket >= Records.BUCKETS.length)
		{
			return;
		}
		if (goals == null || goals.length != Records.BUCKETS.length)
		{
			int[] grown = new int[Records.BUCKETS.length];
			if (goals != null)
			{
				System.arraycopy(goals, 0, grown, 0, Math.min(goals.length, grown.length));
			}
			goals = grown;
		}
		goals[bucket] = Math.max(0, ticks);
	}

	/** The longest it has taken to see a purple, the current streak included. */
	public int longestDry()
	{
		int longest = dry;
		for (Drop d : drops)
		{
			longest = Math.max(longest, d.getDry());
		}
		return longest;
	}

	/** The newest run, or null. */
	public Run last()
	{
		return runs.isEmpty() ? null : runs.get(runs.size() - 1);
	}

	public void record(Run run)
	{
		record(run, null, 0);
	}

	/**
	 * Adds a finished run to the history.
	 *
	 * @param purples the uniques that landed during the run, logged once the run has counted towards the dry streak
	 * @param now when the run was recorded, for the purple log
	 */
	public void record(Run run, List<String> purples, long now)
	{
		if (run == null)
		{
			return;
		}
		ensureCounts();
		runs.add(run);
		count(run, 1);
		trim();
		if (run.isCompleted())
		{
			dry++;
			if (run.getKc() > kc)
			{
				kc = run.getKc();
			}
			else if (run.getKc() == 0 && kc > 0)
			{
				kc++;
			}
		}
		if (purples != null)
		{
			for (String unique : purples)
			{
				if (unique != null)
				{
					drops.add(new Drop(unique, now, kc, dry));
					dry = 0;
				}
			}
		}
	}

	/** The game said the completion count; it is the truth, whatever was counted before. */
	public void kc(int count, long now)
	{
		Run last = last();
		if (last != null && last.isCompleted() && last.getKc() == 0 && now - last.getStartedAt() < LOOT_WINDOW_MS * 6)
		{
			last.setKc(count);
		}
		kc = count;
	}

	/** A purple came; it belongs to the newest run when that ended moments ago. */
	public void purple(String unique, long now)
	{
		Run last = last();
		if (last != null && last.getPurple() == null && now - last.getStartedAt() < LOOT_WINDOW_MS * 6)
		{
			last.setPurple(unique);
		}
		drops.add(new Drop(unique, now, kc, dry));
		dry = 0;
	}

	/**
	 * Takes a run out of the history, for one the plugin timed wrongly. A completion since the last
	 * purple also comes off the dry streak.
	 *
	 * @return whether a run started at that moment was found
	 */
	public boolean removeRun(long startedAt)
	{
		ensureCounts();
		for (int i = runs.size() - 1; i >= 0; i--)
		{
			Run r = runs.get(i);
			if (r.getStartedAt() == startedAt)
			{
				runs.remove(i);
				count(r, -1);
				long lastDrop = drops.isEmpty() ? Long.MIN_VALUE : drops.get(drops.size() - 1).getAt();
				if (r.isCompleted() && r.getStartedAt() > lastDrop && dry > 0)
				{
					dry--;
				}
				return true;
			}
		}
		return false;
	}

	/**
	 * Takes a purple out of the log, for one the plugin mistook. The clears it took go back onto
	 * the streak it ended: the next purple's, or the current dry streak when it was the newest.
	 *
	 * @return whether the purple was found
	 */
	public boolean removeDrop(long at, String unique)
	{
		for (int i = drops.size() - 1; i >= 0; i--)
		{
			Drop d = drops.get(i);
			if (d.getAt() == at && d.getUnique().equals(unique))
			{
				drops.remove(i);
				if (i < drops.size())
				{
					drops.get(i).addDry(d.getDry());
				}
				else
				{
					dry += d.getDry();
				}
				for (Run r : runs)
				{
					if (unique.equals(r.getPurple()) && Math.abs(r.getStartedAt() - at) < LOOT_WINDOW_MS * 6)
					{
						r.setPurple(null);
					}
				}
				return true;
			}
		}
		return false;
	}

	/** Notes a role on a run, or clears it with null. */
	public boolean setRole(long startedAt, String role)
	{
		Run r = find(startedAt);
		if (r != null)
		{
			r.setRole(role);
		}
		return r != null;
	}

	/** Writes the player's own note on a run, or clears it with null or blank. */
	public boolean setNote(long startedAt, String note)
	{
		Run r = find(startedAt);
		if (r != null)
		{
			r.setNote(note);
		}
		return r != null;
	}

	private Run find(long startedAt)
	{
		for (int i = runs.size() - 1; i >= 0; i--)
		{
			if (runs.get(i).getStartedAt() == startedAt)
			{
				return runs.get(i);
			}
		}
		return null;
	}

	private void count(Run run, int by)
	{
		int b = Records.bucket(run.getTeamSize());
		if (run.isCompleted())
		{
			clears[b] = Math.max(0, clears[b] + by);
		}
		else if (run.getOutcome() == Outcome.WIPED)
		{
			wipes[b] = Math.max(0, wipes[b] + by);
		}
	}

	/** Counts clears and wipes from the runs kept, for a save from before they were counted apart. */
	private void recount()
	{
		clears = new int[Records.BUCKETS.length];
		wipes = new int[Records.BUCKETS.length];
		for (Run r : runs)
		{
			count(r, 1);
		}
	}

	private void ensureCounts()
	{
		if (clears == null || wipes == null || clears.length != Records.BUCKETS.length || wipes.length != Records.BUCKETS.length)
		{
			recount();
		}
	}

	/** Lets the oldest runs go past the limit, keeping every run that holds a record. */
	private void trim()
	{
		// What each guess rested on matters while a run is fresh; older runs keep only their times.
		for (int i = 0; i < runs.size() - DOUBT_RUNS; i++)
		{
			runs.get(i).forgetDoubts();
		}
		if (runs.size() <= MAX_RUNS)
		{
			return;
		}
		Set<Run> keep = Records.holders(runs);
		for (int i = 0; i < runs.size() && runs.size() > MAX_RUNS; )
		{
			if (keep.contains(runs.get(i)))
			{
				i++;
			}
			else
			{
				runs.remove(i);
			}
		}
	}

	/** A saved archive as read back: what could be kept, and whether anything had to be left out. */
	public static final class Loaded
	{
		/** The archive, or null when nothing in the save could be read at all. */
		public final Archive archive;
		/** True when the save was not read whole: a run, a purple or a figure in it was damaged. */
		public final boolean damaged;

		Loaded(Archive archive, boolean damaged)
		{
			this.archive = archive;
			this.damaged = damaged;
		}
	}

	/**
	 * Reads a saved archive. A save that reads whole is repaired and kept; one that does not (a
	 * run of the wrong shape, a figure too big for its field, a save cut short) keeps every run,
	 * purple and figure that still reads, so one damaged run never costs the rest.
	 */
	public static Loaded read(Gson gson, String saved)
	{
		if (saved == null || saved.trim().isEmpty())
		{
			return new Loaded(new Archive(), false);
		}
		try
		{
			Archive whole = gson.fromJson(saved, Archive.class);
			if (whole != null)
			{
				// It read, but a field, a boss or a purple a later version keeps would be dropped by the next save.
				whole.repair();
				return new Loaded(whole, Unread.any(gson, saved, whole));
			}
		}
		catch (RuntimeException e)
		{
			// Read it piece by piece below.
		}
		return new Loaded(salvage(gson, saved), true);
	}

	/** Every piece of a damaged save that still reads, or null when none does. */
	private static Archive salvage(Gson gson, String saved)
	{
		Archive a = new Archive();
		boolean any = false;
		JsonReader in = new JsonReader(new StringReader(saved));
		in.setLenient(true);
		try
		{
			if (in.peek() != JsonToken.BEGIN_OBJECT)
			{
				return null;
			}
			in.beginObject();
			while (in.hasNext())
			{
				String name = in.nextName();
				boolean list = "runs".equals(name) || "drops".equals(name);
				if (list && in.peek() == JsonToken.BEGIN_ARRAY)
				{
					in.beginArray();
					while (in.hasNext())
					{
						JsonElement item = gson.fromJson(in, JsonElement.class);
						if ("runs".equals(name))
						{
							Run r = piece(gson, item, Run.class);
							any |= r != null && a.runs.add(r);
						}
						else
						{
							Drop d = piece(gson, item, Drop.class);
							any |= d != null && a.drops.add(d);
						}
					}
					in.endArray();
					continue;
				}
				JsonElement value = gson.fromJson(in, JsonElement.class);
				any |= a.figure(gson, name, value);
			}
		}
		catch (IOException | RuntimeException e)
		{
			// A save cut short keeps everything before the cut.
		}
		return any ? a.repair() : null;
	}

	/** One saved run or purple, or null when it does not read. */
	private static <T> T piece(Gson gson, JsonElement item, Class<T> type)
	{
		try
		{
			return item == null || !item.isJsonObject() ? null : gson.fromJson(item, type);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** Sets one of the archive's own figures from a damaged save, when it reads; true when it did. */
	private boolean figure(Gson gson, String name, JsonElement value)
	{
		try
		{
			switch (name)
			{
				case "kc":
					kc = gson.fromJson(value, int.class);
					return true;
				case "dry":
					dry = gson.fromJson(value, int.class);
					return true;
				case "clears":
					clears = gson.fromJson(value, int[].class);
					return true;
				case "wipes":
					wipes = gson.fromJson(value, int[].class);
					return true;
				case "goals":
					goals = gson.fromJson(value, int[].class);
					return true;
				default:
					// A figure a later version keeps, unknown here.
					return false;
			}
		}
		catch (RuntimeException e)
		{
			return false;
		}
	}

	/**
	 * A copy to hand the panel, sharing nothing it could change: quicker on the client thread than
	 * writing the archive out and reading it back, as the copy after each run once was.
	 */
	public Archive copy()
	{
		Archive a = new Archive();
		for (Run r : runs)
		{
			a.runs.add(r.copy());
		}
		// Removing a purple gives its clears to the next one, so each is copied too.
		for (Drop d : drops)
		{
			a.drops.add(new Drop(d.getUnique(), d.getAt(), d.getKc(), d.getDry()));
		}
		a.kc = kc;
		a.dry = dry;
		a.clears = clears == null ? null : clears.clone();
		a.wipes = wipes == null ? null : wipes.clone();
		a.goals = goals == null ? null : goals.clone();
		return a;
	}

	public Archive repair()
	{
		if (runs == null)
		{
			runs = new ArrayList<>();
		}
		runs.removeIf(r -> r == null);
		runs.forEach(Run::repair);
		if (drops == null)
		{
			drops = new ArrayList<>();
		}
		drops.removeIf(d -> d == null || d.getUnique() == null);
		kc = Math.max(0, kc);
		dry = Math.max(0, dry);
		ensureCounts();
		for (int b = 0; b < clears.length; b++)
		{
			clears[b] = Math.max(0, clears[b]);
			wipes[b] = Math.max(0, wipes[b]);
		}
		trim();
		return this;
	}
}

package com.codex.archive.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * What a run is measured against: when each boss should be down by. Your best run is the
 * classic mark; your best rooms strung together is the run of a perfect day; your typical run
 * (the median of each room over recent clears) says whether today is a good day or a bad one.
 * A goal time is the run you are working towards: its total set by the player, shared out among
 * the rooms in the proportions of your best rooms, so each boss has a mark on the way.
 */
public final class Comparison
{
	/** Completed runs the typical run is taken from. */
	public static final int TYPICAL_RUNS = 10;

	public enum Mode
	{
		PERSONAL_BEST("Personal best", "PB", "your best"),
		BEST_ROOMS("Best rooms", "Golds", "your best rooms"),
		TYPICAL("Typical run", "Typical", "your typical run"),
		GOAL("Goal time", "Goal", "your goal");

		private final String label;
		private final String shortLabel;
		private final String noun;

		Mode(String label, String shortLabel, String noun)
		{
			this.label = label;
			this.shortLabel = shortLabel;
			this.noun = noun;
		}

		/** A few letters for the crest: "PB". */
		public String getShortLabel()
		{
			return shortLabel;
		}

		/** For the chat box: "4.2s ahead of your best rooms". */
		public String getNoun()
		{
			return noun;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	private final Mode mode;
	/** For each row, when its boss should be down, in ticks from the start, or -1. */
	private final int[] ends;
	/** For each row, the room time aimed at, or -1. */
	private final int[] rooms;

	private Comparison(Mode mode, int[] ends, int[] rooms)
	{
		this.mode = mode;
		this.ends = ends;
		this.rooms = rooms;
	}

	/**
	 * @param runs    the history
	 * @param bucket  the party-size group
	 * @param exclude a run never compared with itself, such as the one being shown; or null
	 */
	public static Comparison of(List<Run> runs, int bucket, Mode mode, Run exclude)
	{
		return of(runs, bucket, mode, exclude, 0);
	}

	/** The marks from an archive, with the goal set for the party size. */
	public static Comparison of(Archive archive, int bucket, Mode mode, Run exclude)
	{
		return of(archive.getRuns(), bucket, mode, exclude, archive.goal(bucket));
	}

	/**
	 * @param goal the goal time for the party size in ticks, or 0 for none; without one, the goal
	 *     mode falls back on the personal best
	 */
	public static Comparison of(List<Run> runs, int bucket, Mode mode, Run exclude, int goal)
	{
		if (mode == Mode.GOAL)
		{
			return goal > 0 ? goal(runs, bucket, exclude, goal) : of(runs, bucket, Mode.PERSONAL_BEST, exclude, 0);
		}
		int[] ends = new int[Encounter.ROWS];
		int[] rooms = new int[Encounter.ROWS];
		Arrays.fill(ends, -1);
		Arrays.fill(rooms, -1);
		List<Run> pool = new ArrayList<>();
		for (Run r : runs)
		{
			if (r != exclude && (exclude == null || r.getStartedAt() != exclude.getStartedAt())
				&& Records.bucket(r.getTeamSize()) == bucket)
			{
				pool.add(r);
			}
		}
		if (mode == Mode.PERSONAL_BEST)
		{
			Run best = Records.best(pool, bucket);
			if (best != null)
			{
				for (int row = 0; row < Encounter.ROWS; row++)
				{
					Split s = best.split(row);
					if (s != null && s.isDone())
					{
						ends[row] = s.getEndTick();
						rooms[row] = s.roomTicks(0);
					}
				}
			}
			return new Comparison(mode, ends, rooms);
		}
		for (int row = 0; row < Encounter.ROWS; row++)
		{
			rooms[row] = mode == Mode.BEST_ROOMS ? Records.bestRoom(pool, bucket, row) : typicalRoom(pool, row);
		}
		int sum = 0;
		for (int row = 0; row < Encounter.ROWS; row++)
		{
			if (rooms[row] < 0)
			{
				// A row with no time breaks the chain: every boss after it has no mark either.
				break;
			}
			sum += rooms[row];
			ends[row] = sum;
		}
		return new Comparison(mode, ends, rooms);
	}

	/**
	 * A goal time shared out among the rooms: in the proportions of your best rooms when every row
	 * has one, else of your best run. The goal card uses the same shape, so the marks raced here are
	 * the rooms it says the goal allows. Rounded so the rooms add up to the
	 * goal exactly. With no runs to take a shape from, only the whole run has a mark.
	 */
	private static Comparison goal(List<Run> runs, int bucket, Run exclude, int goal)
	{
		int[] shape = null;
		for (Mode m : new Mode[]{Mode.BEST_ROOMS, Mode.PERSONAL_BEST})
		{
			Comparison c = of(runs, bucket, m, exclude, 0);
			int[] rooms = new int[Encounter.ROWS];
			boolean whole = true;
			for (int row = 0; row < Encounter.ROWS; row++)
			{
				rooms[row] = c.room(row);
				whole &= rooms[row] > 0;
			}
			if (whole)
			{
				shape = rooms;
				break;
			}
		}
		int[] ends = new int[Encounter.ROWS];
		int[] rooms = new int[Encounter.ROWS];
		Arrays.fill(ends, -1);
		Arrays.fill(rooms, -1);
		if (shape == null)
		{
			ends[Encounter.ROWS - 1] = goal;
			return new Comparison(Mode.GOAL, ends, rooms);
		}
		int[] shared = share(shape, goal);
		System.arraycopy(shared, 0, rooms, 0, rooms.length);
		int sum = 0;
		for (int row = 0; row < Encounter.ROWS; row++)
		{
			sum += rooms[row];
			ends[row] = sum;
		}
		return new Comparison(Mode.GOAL, ends, rooms);
	}

	/**
	 * A total shared out among the rows in proportion to a shape, rounded by largest remainders so
	 * the rows add up to the total exactly.
	 */
	static int[] share(int[] shape, int goal)
	{
		long total = 0;
		for (int t : shape)
		{
			total += t;
		}
		int[] rooms = new int[shape.length];
		double[] exact = new double[shape.length];
		int given = 0;
		for (int row = 0; row < shape.length; row++)
		{
			exact[row] = goal * (double) shape[row] / total;
			rooms[row] = (int) Math.floor(exact[row]);
			given += rooms[row];
		}
		while (given < goal)
		{
			int pick = 0;
			for (int row = 1; row < shape.length; row++)
			{
				if (exact[row] - rooms[row] > exact[pick] - rooms[pick])
				{
					pick = row;
				}
			}
			rooms[pick]++;
			exact[pick] = rooms[pick];
			given++;
		}
		return rooms;
	}

	/** The median room over the newest completed runs that timed this row, or -1. */
	private static int typicalRoom(List<Run> pool, int row)
	{
		List<Integer> times = new ArrayList<>();
		for (int i = pool.size() - 1; i >= 0 && times.size() < TYPICAL_RUNS; i--)
		{
			Run r = pool.get(i);
			Split s = r.split(row);
			if (r.isCompleted() && s != null && s.isDone())
			{
				times.add(s.roomTicks(0));
			}
		}
		return Stats.median(times);
	}

	public Mode getMode()
	{
		return mode;
	}

	/** When this row's boss should be down, or -1. */
	public int end(int row)
	{
		return row >= 0 && row < ends.length ? ends[row] : -1;
	}

	/** The room time aimed at for this row, or -1. */
	public int room(int row)
	{
		return row >= 0 && row < rooms.length ? rooms[row] : -1;
	}

	/** The whole run's mark: the last row's end, or -1. */
	public int total()
	{
		return ends[Encounter.ROWS - 1];
	}

	/**
	 * How far behind the mark a run was when this row's boss fell.
	 *
	 * @return ticks behind (negative when ahead), or null when either side has no time for the row
	 */
	public Integer delta(Run run, int row)
	{
		if (run == null)
		{
			return null;
		}
		Split s = run.split(row);
		int mark = end(row);
		if (s == null || !s.isDone() || mark < 0)
		{
			return null;
		}
		return s.getEndTick() - mark;
	}

	/**
	 * The best a run can still finish in: what it has taken so far, the room being fought at its
	 * best or its time so far if that is already longer, and every room after it at its best.
	 *
	 * @param bestRooms each row's best room in this party size, or -1
	 * @param now       ticks since the run began
	 * @return ticks, or -1 while any room still to come has no best
	 */
	public static int bestPossible(Run run, int[] bestRooms, int now)
	{
		if (run == null)
		{
			return -1;
		}
		int row = run.reached();
		if (row >= Encounter.ROWS || run.isCompleted())
		{
			return run.getTicks();
		}
		int base = 0;
		for (Split s : run.getSplits())
		{
			if (s.isDone())
			{
				base = Math.max(base, s.getEndTick());
			}
		}
		int total = base;
		for (int r = row; r < Encounter.ROWS; r++)
		{
			int best = bestRooms != null && r < bestRooms.length ? bestRooms[r] : -1;
			if (best < 0)
			{
				return -1;
			}
			total += r == row ? Math.max(best, now - base) : best;
		}
		return total;
	}
}

package com.codex.archive.core;

import java.util.ArrayList;
import java.util.List;

/**
 * What a run's times rest on, in plain words, for the runs where that is in doubt: a boss told by
 * its row and its size rather than its name, and the big foes a run fought that matched no boss.
 * Two of the raid's bosses have no name the plugin can know before launch, so this lets the player
 * see at a glance whether a split is the boss's or an add's, and delete the run when it is wrong.
 */
public final class Doubts
{
	private Doubts()
	{
	}

	/** One line per doubt, empty when every boss of the run was known by its name. */
	public static List<String> of(Run run)
	{
		List<String> lines = new ArrayList<>();
		if (run == null || !run.hasDoubts())
		{
			return lines;
		}
		for (int row = 0; row < Encounter.ROWS; row++)
		{
			Split s = run.split(row);
			if (s == null || s.getSeen() == null)
			{
				continue;
			}
			String level = s.getSeenLevel() > 0 ? ", level " + s.getSeenLevel() : "";
			lines.add(s.getEncounter().getShortName() + " was told by its size: " + s.getSeen() + level + ".");
		}
		List<String> unknown = run.getUnknown();
		List<Integer> untimed = run.untimedRows();
		if (!unknown.isEmpty() && !untimed.isEmpty())
		{
			StringBuilder missed = new StringBuilder();
			for (int row : untimed)
			{
				missed.append(missed.length() > 0 ? ", " : "").append(Encounter.rowLabel(row));
			}
			lines.add("Not timed: " + missed + ". Big foes no boss name matched: " + String.join(", ", unknown) + ".");
		}
		return lines;
	}
}

package com.codex.archive.core;

/** A purple, as the spoils page lists it. */
public class Drop
{
	private String unique;
	private long at;
	/** The completion count it came on, or 0 when unknown. */
	private int kc;
	/** Completions since the purple before it. */
	private int dry;

	public Drop()
	{
	}

	Drop(String unique, long at, int kc, int dry)
	{
		this.unique = unique;
		this.at = at;
		this.kc = kc;
		this.dry = dry;
	}

	public String getUnique()
	{
		return unique;
	}

	public long getAt()
	{
		return at;
	}

	public int getKc()
	{
		return kc;
	}

	public int getDry()
	{
		return dry;
	}

	void addDry(int clears)
	{
		dry = Math.max(0, dry + clears);
	}
}

package com.codex.archive.core;

import java.util.Locale;

/**
 * The Fractured Archive's eight encounters. The Guardian always opens the raid and Ocellus, the
 * hooded figure, always ends it; each of the three rows between offers a left and a right door,
 * and both doors of a row are worth the same points, so a run is always five encounters long.
 *
 * <p>Bosses are known by the game's NPC ids, so minions (Smorks, jellies, undead binders, imps)
 * and scenery (inert guardians, swords, rifts, the Guardian's husk) never open or close a split.
 * The name is a fallback for forms the game adds later. The constants of the two bosses that had
 * no name before launch keep their old names, since saved runs refer to them.
 */
public enum Encounter
{
	GUARDIAN(0, "Archive Guardian", "Guardian", new String[]{"archive guardian"}),
	BORK(1, "Bork", "Bork", new String[]{"bork"}),
	EZEKIEL(1, "Ezekiel", "Ezekiel", new String[]{"ezekiel"}),
	DREADNOTH(2, "Dreadnoth the Jellied", "Dreadnoth", new String[]{"dreadnoth"}),
	NECROMANCER(2, "Moia", "Moia", new String[]{"moia"}),
	XARTH(3, "Xarth", "Xarth", new String[]{"xarth"}),
	TRIO(3, "Dagon'hai Trio", "Trio", new String[]{"dagon'hai", "dagonhai"}),
	HOODED_FIGURE(4, "Ocellus", "Ocellus", new String[]{"ocellus"});

	/** The ids of each boss's fighting forms, in the order of the constants above. */
	private static final int[][] IDS = {
		{16659, 16660},
		{16640},
		{16652},
		{16665},
		{16667},
		{16684},
		{16643, 16644, 16645, 16646, 16647, 16648},
		{16674, 16675, 16677},
	};
	/** Ocellus fights in three phases; only the third falling ends the raid. */
	private static final int OCELLUS_LAST_PHASE = 16677;
	private static final int OCELLUS_FIRST_PHASES_FROM = 16674;
	private static final int OCELLUS_FIRST_PHASES_TO = 16675;
	/** The forms a boss leaves behind once beaten: the Guardian's husk and Xarth's corpse. */
	private static final int GUARDIAN_DEAD = 16658;
	private static final int XARTH_CORPSE = 16687;
	private static final int XARTH_CORPSE_DOUSED = 16688;
	/** The block of ids the raid's NPCs were given; inside it, only the ids above are bosses. */
	private static final int RAID_IDS_FIRST = 16630;
	private static final int RAID_IDS_LAST = 16710;

	/** Five encounters in every run. */
	public static final int ROWS = 5;

	private final int row;
	private final String title;
	private final String shortName;
	private final String[] names;

	Encounter(int row, String title, String shortName, String[] names)
	{
		this.row = row;
		this.title = title;
		this.shortName = shortName;
		this.names = names;
	}

	public int getRow()
	{
		return row;
	}

	public String getTitle()
	{
		return title;
	}

	public String getShortName()
	{
		return shortName;
	}

	/**
	 * True when the boss of this row has no name the plugin can know, so it is recognised by its
	 * row instead. Since launch every boss has one; the row guess stays for any the game renames.
	 */
	public boolean isUnnamed()
	{
		return false;
	}

	/**
	 * The encounter an NPC is the boss of, by id first and by name for forms the game adds later.
	 *
	 * @return the encounter, or null for minions, scenery and every other NPC
	 */
	public static Encounter of(int npcId, String npcName)
	{
		Encounter[] all = values();
		for (int i = 0; i < all.length; i++)
		{
			for (int id : IDS[i])
			{
				if (id == npcId)
				{
					return all[i];
				}
			}
		}
		return npcId >= RAID_IDS_FIRST && npcId <= RAID_IDS_LAST ? null : byName(npcName);
	}

	/** Whether this NPC falling can be its boss falling: Ocellus's first two phases only become the next. */
	public static boolean isFinalForm(int npcId)
	{
		return npcId < OCELLUS_FIRST_PHASES_FROM || npcId > OCELLUS_FIRST_PHASES_TO || npcId == OCELLUS_LAST_PHASE;
	}

	/**
	 * Some bosses leave a form behind once beaten; its arrival is a sure sign of the fall.
	 *
	 * @return the encounter whose fall this NPC marks, or null
	 */
	public static Encounter fallMarker(int npcId)
	{
		switch (npcId)
		{
			case GUARDIAN_DEAD:
				return GUARDIAN;
			case XARTH_CORPSE:
			case XARTH_CORPSE_DOUSED:
				return XARTH;
			default:
				return null;
		}
	}

	/** The two encounters a row can hold, or one for the first and last rows. */
	public static Encounter[] ofRow(int row)
	{
		switch (row)
		{
			case 0:
				return new Encounter[]{GUARDIAN};
			case 1:
				return new Encounter[]{BORK, EZEKIEL};
			case 2:
				return new Encounter[]{DREADNOTH, NECROMANCER};
			case 3:
				return new Encounter[]{XARTH, TRIO};
			case 4:
				return new Encounter[]{HOODED_FIGURE};
			default:
				return new Encounter[0];
		}
	}

	/** The row's name in the panel when no run has chosen a door yet. */
	public static String rowLabel(int row)
	{
		switch (row)
		{
			case 0:
				return "Guardian";
			case 1:
				return "Bork / Ezekiel";
			case 2:
				return "Dreadnoth / Moia";
			case 3:
				return "Xarth / Trio";
			default:
				return "Ocellus";
		}
	}

	/**
	 * Matches an NPC by name. Minions of an encounter (Bork's Smorks, say) are not the boss and
	 * do not match, so only the boss's own name opens and closes a split.
	 *
	 * @return the encounter, or null for any other NPC
	 */
	public static Encounter byName(String npcName)
	{
		if (npcName == null)
		{
			return null;
		}
		String name = clean(npcName);
		if (name.startsWith("the "))
		{
			name = name.substring(4);
		}
		for (Encounter e : values())
		{
			for (String n : e.names)
			{
				if (name.equals(n) || name.startsWith(n + " ") || (e == TRIO && name.startsWith(n)))
				{
					return e;
				}
			}
		}
		return null;
	}

	/** Strips the colour tags the game puts in some names, and lowercases what is left. */
	static String clean(String name)
	{
		return name.replaceAll("<[^>]*>", "").replace('\u00A0', ' ').trim().toLowerCase(Locale.ENGLISH);
	}
}

package com.codex.archive.core;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.List;
import java.util.Locale;

/**
 * The run history as a spreadsheet: one line per run, every room and fight in seconds, so it
 * opens in any spreadsheet program for graphs of your own.
 */
public final class Export
{
	private static final DateTimeFormatter WHEN = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss", Locale.ENGLISH);

	private Export()
	{
	}

	/** Comma-separated lines, a header first, oldest run first. */
	public static String csv(List<Run> runs, ZoneId zone)
	{
		StringBuilder sb = new StringBuilder();
		sb.append("started,party,outcome,time_s,kc,deaths,route");
		for (int row = 0; row < Encounter.ROWS; row++)
		{
			String r = "row" + (row + 1);
			sb.append(',').append(r).append("_boss,").append(r).append("_room_s,").append(r).append("_fight_s,")
				.append(r).append("_down_at_s");
		}
		sb.append(",purple,role,crew,note\n");
		for (Run run : runs)
		{
			sb.append(WHEN.format(Instant.ofEpochMilli(run.getStartedAt()).atZone(zone))).append(',')
				.append(Records.BUCKETS[Records.bucket(run.getTeamSize())]).append(',')
				.append(run.getOutcome() == null ? "" : run.getOutcome().name().toLowerCase(Locale.ENGLISH)).append(',')
				.append(seconds(run.getTicks())).append(',')
				.append(run.getKc() > 0 ? String.valueOf(run.getKc()) : "").append(',')
				.append(run.getDeaths()).append(',')
				.append(cell(run.route()));
			for (int row = 0; row < Encounter.ROWS; row++)
			{
				Split s = run.split(row);
				if (s == null || !s.isDone())
				{
					sb.append(",,,,");
					continue;
				}
				sb.append(',').append(cell(s.getEncounter().getTitle()))
					.append(',').append(seconds(s.roomTicks(0)))
					.append(',').append(seconds(s.fightTicks(0)))
					.append(',').append(seconds(s.getEndTick()));
			}
			sb.append(',').append(cell(run.getPurple()))
				.append(',').append(cell(run.getRole()))
				.append(',').append(cell(String.join("; ", run.getCrew())))
				.append(',').append(cell(run.getNote()))
				.append('\n');
		}
		return sb.toString();
	}

	/** Ticks as seconds to the tenth, exact since a tick is 0.6 seconds: "36.0". */
	static String seconds(int ticks)
	{
		int tenths = Math.max(0, ticks) * 6;
		return tenths / 10 + "." + tenths % 10;
	}

	/**
	 * A text cell, quoted when it holds a comma, quote or line break. A leading =, +, -, @, tab or
	 * carriage return is set off with a quote mark so a spreadsheet never runs a name or note as a formula.
	 */
	static String cell(String text)
	{
		if (text == null || text.isEmpty())
		{
			return "";
		}
		String t = text;
		if ("=+-@\t\r".indexOf(t.charAt(0)) >= 0)
		{
			t = "'" + t;
		}
		if (t.contains(",") || t.contains("\"") || t.contains("\n") || t.contains("\r"))
		{
			t = "\"" + t.replace("\"", "\"\"") + "\"";
		}
		return t;
	}
}

package com.codex.archive.core;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * Where a goal time stands against the runs so far: how far the best run is from it, how often a
 * clear has beaten it, and which rooms a typical run loses the most in against the goal's share.
 * The share follows your best rooms, so a room you have done quickly before but usually do slowly
 * stands out, since that is where the time is to be found.
 */
public final class Goal
{
	/** One row against the goal: the room the goal allows and the room a typical run takes. */
	public static final class Row
	{
		public final int row;
		public final int allowed;
		public final int typical;

		Row(int row, int allowed, int typical)
		{
			this.row = row;
			this.allowed = allowed;
			this.typical = typical;
		}

		/** Ticks a typical room takes over the goal's share; negative when it is already under. */
		public int over()
		{
			return typical - allowed;
		}
	}

	private final int goal;
	private final int best;
	private final int beaten;
	private final Run first;
	private final List<Row> rows;

	private Goal(int goal, int best, int beaten, Run first, List<Row> rows)
	{
		this.goal = goal;
		this.best = best;
		this.beaten = beaten;
		this.first = first;
		this.rows = rows;
	}

	/** @return where the goal stands, or null when none is set for the party size */
	public static Goal of(List<Run> runs, int bucket, int goal)
	{
		if (goal <= 0)
		{
			return null;
		}
		Run best = Records.best(runs, bucket);
		int beaten = 0;
		Run first = null;
		for (Run r : runs)
		{
			if (r.isCompleted() && Records.bucket(r.getTeamSize()) == bucket && r.getTicks() <= goal)
			{
				beaten++;
				if (first == null || r.getStartedAt() < first.getStartedAt())
				{
					first = r;
				}
			}
		}
		// The goal shared out like your best rooms: each row's share of what you have shown you can do.
		// A typical room furthest over its share is where the most time is to be found.
		Comparison golds = Comparison.of(runs, bucket, Comparison.Mode.BEST_ROOMS, null, 0);
		Comparison typical = Comparison.of(runs, bucket, Comparison.Mode.TYPICAL, null, 0);
		List<Row> rows = new ArrayList<>();
		int[] shape = new int[Encounter.ROWS];
		boolean whole = true;
		for (int row = 0; row < Encounter.ROWS; row++)
		{
			shape[row] = golds.room(row);
			whole &= shape[row] > 0;
		}
		if (whole)
		{
			int[] allowed = Comparison.share(shape, goal);
			for (int row = 0; row < Encounter.ROWS; row++)
			{
				if (typical.room(row) > 0)
				{
					rows.add(new Row(row, allowed[row], typical.room(row)));
				}
			}
		}
		rows.sort(Comparator.comparingInt((Row r) -> -r.over()).thenComparingInt(r -> r.row));
		return new Goal(goal, best == null ? -1 : best.getTicks(), beaten, first, rows);
	}

	public int getGoal()
	{
		return goal;
	}

	/** The best clear in ticks, or -1 with none. */
	public int getBest()
	{
		return best;
	}

	/** Clears at or under the goal. */
	public int getBeaten()
	{
		return beaten;
	}

	/** The first clear that beat it, or null. */
	public Run getFirst()
	{
		return first;
	}

	/** Every row with a typical room, the one furthest over the goal's share first. */
	public List<Row> getRows()
	{
		return rows;
	}

	/** Ticks the best run is over the goal; 0 or less once it is beaten. */
	public int gap()
	{
		return best < 0 ? -1 : best - goal;
	}

	/**
	 * Parses a time the player typed: "20:00", "19:42.6", "1:02:30", or a bare number of minutes
	 * ("20"), since the prompt asks for minutes and a raid goal is never a matter of seconds.
	 *
	 * @return ticks, rounded to the nearest, or -1 when it is not a time
	 */
	public static int parse(String text)
	{
		if (text == null)
		{
			return -1;
		}
		String t = text.trim();
		if (t.isEmpty() || !t.matches("\\d{1,3}(:\\d{1,2}){0,2}(\\.\\d+)?"))
		{
			return -1;
		}
		String[] parts = t.split(":");
		double seconds = 0;
		try
		{
			for (int i = 0; i < parts.length; i++)
			{
				double v = Double.parseDouble(parts[i]);
				if (i > 0 && v >= 60)
				{
					return -1;
				}
				seconds = seconds * 60 + v;
			}
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
		if (parts.length == 1)
		{
			seconds *= 60;
		}
		int ticks = (int) Math.round(seconds / 0.6);
		return ticks > 0 ? ticks : -1;
	}
}

package com.codex.archive.core;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * What the run history says beyond the bests: where time is usually lost, which door is quicker
 * for you, which whole route is, how steady your clears are and how your best came down, where
 * runs wipe, and who you raid with.
 */
public final class Insights
{
	/** How many recent runs the typical figures come from. */
	public static final int RECENT = 20;
	/** Runs through a door before it is worth comparing with the other. */
	public static final int DOOR_RUNS = 3;

	private Insights()
	{
	}

	/** One row of the raid: its best room, a typical room lately and how much they vary. */
	public static final class RowStat
	{
		public final int row;
		public final int best;
		public final int typical;
		/** The middle half of recent rooms spans this many ticks. */
		public final int spread;
		public final int runs;

		RowStat(int row, int best, int typical, int spread, int runs)
		{
			this.row = row;
			this.best = best;
			this.typical = typical;
			this.spread = spread;
			this.runs = runs;
		}

		/** What a typical run loses here against the best. */
		public int loss()
		{
			return Math.max(0, typical - best);
		}
	}

	/** One boss behind a door: how often you took it and how quick its room is for you. */
	public static final class DoorStat
	{
		public final Encounter encounter;
		public final int runs;
		public final int typical;
		public final int best;

		DoorStat(Encounter encounter, int runs, int typical, int best)
		{
			this.encounter = encounter;
			this.runs = runs;
			this.typical = typical;
			this.best = best;
		}
	}

	/** A teammate: runs together, clears together and the best clear together. */
	public static final class Mate
	{
		public final String name;
		public final int runs;
		public final int clears;
		public final int best;

		Mate(String name, int runs, int clears, int best)
		{
			this.name = name;
			this.runs = runs;
			this.clears = clears;
			this.best = best;
		}
	}

	/** One way through the three rows of doors, over the clears that took it. */
	public static final class RouteStat
	{
		/** The boss behind each of the three doors, in row order. */
		public final List<Encounter> doors;
		public final int clears;
		public final int best;
		/** The median clear on this route. */
		public final int typical;

		RouteStat(List<Encounter> doors, int clears, int best, int typical)
		{
			this.doors = doors;
			this.clears = clears;
			this.best = best;
			this.typical = typical;
		}

		/** "Bork, Dreadnoth, Trio". */
		public String name()
		{
			StringBuilder sb = new StringBuilder();
			for (Encounter e : doors)
			{
				sb.append(sb.length() > 0 ? ", " : "").append(e.getShortName());
			}
			return sb.toString();
		}
	}

	/** A new personal best: when, the time, and how much it took off the one before. */
	public static final class Best
	{
		public final long at;
		public final int ticks;
		/** Ticks taken off the previous best, or -1 for the first clear. */
		public final int saved;

		Best(long at, int ticks, int saved)
		{
			this.at = at;
			this.ticks = ticks;
			this.saved = saved;
		}
	}

	/** A boss runs have wiped at: how often, out of how many times it was reached. */
	public static final class Wall
	{
		public final Encounter encounter;
		public final int wipes;
		public final int tries;

		Wall(Encounter encounter, int wipes, int tries)
		{
			this.encounter = encounter;
			this.wipes = wipes;
			this.tries = tries;
		}
	}

	/**
	 * Every route cleared in a group, the fastest best first. Only clears with all three doors
	 * timed count, since a route with a gap cannot be told from another.
	 */
	public static List<RouteStat> routes(List<Run> runs, int bucket)
	{
		Map<List<Encounter>, List<Integer>> byRoute = new LinkedHashMap<>();
		for (Run r : runs)
		{
			if (!r.isCompleted() || Records.bucket(r.getTeamSize()) != bucket)
			{
				continue;
			}
			List<Encounter> doors = doors(r);
			if (doors != null)
			{
				byRoute.computeIfAbsent(doors, k -> new ArrayList<>()).add(r.getTicks());
			}
		}
		List<RouteStat> out = new ArrayList<>();
		byRoute.forEach((doors, times) ->
		{
			int best = times.stream().mapToInt(Integer::intValue).min().orElse(-1);
			out.add(new RouteStat(java.util.Collections.unmodifiableList(doors), times.size(), best, Stats.median(times)));
		});
		out.sort(Comparator.comparingInt((RouteStat r) -> r.best).thenComparingInt(r -> -r.clears));
		return out;
	}

	/** The bosses behind a run's three doors, or null when one of them was not timed. */
	public static List<Encounter> doors(Run run)
	{
		List<Encounter> doors = new ArrayList<>();
		for (int row = 1; row <= 3; row++)
		{
			Split s = run.split(row);
			if (s == null)
			{
				return null;
			}
			doors.add(s.getEncounter());
		}
		return doors;
	}

	/**
	 * The best clear on the same route as a run, other than the run itself, and how many there
	 * are: {best ticks, clears}, best -1 when the route was never cleared before.
	 */
	public static int[] routeBest(List<Run> runs, int bucket, Run run)
	{
		List<Encounter> mine = doors(run);
		int best = -1;
		int clears = 0;
		if (mine == null)
		{
			return new int[]{-1, 0};
		}
		for (Run r : runs)
		{
			if (r != run && r.isCompleted() && Records.bucket(r.getTeamSize()) == bucket && mine.equals(doors(r)))
			{
				clears++;
				best = best < 0 ? r.getTicks() : Math.min(best, r.getTicks());
			}
		}
		return new int[]{best, clears};
	}

	/** Each new personal best in a group, oldest first: the first clear, then every clear that beat all before it. */
	public static List<Best> ladder(List<Run> runs, int bucket)
	{
		List<Run> sorted = new ArrayList<>(runs);
		sorted.sort(Comparator.comparingLong(Run::getStartedAt));
		List<Best> out = new ArrayList<>();
		int best = Integer.MAX_VALUE;
		for (Run r : sorted)
		{
			if (r.isCompleted() && Records.bucket(r.getTeamSize()) == bucket && r.getTicks() > 0 && r.getTicks() < best)
			{
				out.add(new Best(r.getStartedAt(), r.getTicks(), best == Integer.MAX_VALUE ? -1 : best - r.getTicks()));
				best = r.getTicks();
			}
		}
		return out;
	}

	/**
	 * The bosses runs wipe at in a group, the most wipes first. A wipe is put on the boss of the
	 * row the run was fighting; a run that wiped before any boss of that row was seen is put on
	 * the row's only boss where there is one, and left out where there were two doors.
	 */
	public static List<Wall> walls(List<Run> runs, int bucket)
	{
		Map<Encounter, int[]> by = new LinkedHashMap<>();
		for (Run r : runs)
		{
			if (Records.bucket(r.getTeamSize()) != bucket)
			{
				continue;
			}
			// Every boss the run reached was a try at it.
			for (Split s : r.getSplits())
			{
				by.computeIfAbsent(s.getEncounter(), k -> new int[2])[1]++;
			}
			if (r.getOutcome() != Outcome.WIPED)
			{
				continue;
			}
			int row = Math.min(r.reached(), Encounter.ROWS - 1);
			Split at = r.split(row);
			Encounter e = at != null ? at.getEncounter() : Encounter.ofRow(row).length == 1 ? Encounter.ofRow(row)[0] : null;
			if (e == null)
			{
				continue;
			}
			int[] c = by.computeIfAbsent(e, k -> new int[2]);
			c[0]++;
			if (at == null)
			{
				c[1]++;
			}
		}
		List<Wall> out = new ArrayList<>();
		by.forEach((e, c) ->
		{
			if (c[0] > 0)
			{
				out.add(new Wall(e, c[0], c[1]));
			}
		});
		out.sort(Comparator.comparingInt((Wall w) -> -w.wipes).thenComparingInt(w -> w.encounter.getRow()));
		return out;
	}

	/** Every row with a time lately, the one losing most against its best first. */
	public static List<RowStat> rows(List<Run> runs, int bucket)
	{
		List<RowStat> out = new ArrayList<>();
		for (int row = 0; row < Encounter.ROWS; row++)
		{
			List<Integer> times = new ArrayList<>();
			for (int i = runs.size() - 1; i >= 0 && times.size() < RECENT; i--)
			{
				Run r = runs.get(i);
				Split s = r.split(row);
				if (Records.bucket(r.getTeamSize()) == bucket && s != null && s.isDone())
				{
					times.add(s.roomTicks(0));
				}
			}
			int best = Records.bestRoom(runs, bucket, row);
			if (times.isEmpty() || best < 0)
			{
				continue;
			}
			out.add(new RowStat(row, best, Stats.median(times),
				Stats.percentile(times, 0.75) - Stats.percentile(times, 0.25), times.size()));
		}
		out.sort(Comparator.comparingInt((RowStat r) -> -r.loss()).thenComparingInt(r -> r.row));
		return out;
	}

	/** Both doors of a row, for rows where each has been taken often enough to compare. */
	public static List<DoorStat[]> doors(List<Run> runs, int bucket)
	{
		List<DoorStat[]> out = new ArrayList<>();
		for (int row = 1; row <= 3; row++)
		{
			Encounter[] pair = Encounter.ofRow(row);
			DoorStat[] stats = new DoorStat[pair.length];
			boolean enough = true;
			for (int i = 0; i < pair.length; i++)
			{
				List<Integer> times = new ArrayList<>();
				int best = -1;
				for (Run r : runs)
				{
					Split s = r.split(row);
					if (Records.bucket(r.getTeamSize()) == bucket && s != null && s.isDone() && s.getEncounter() == pair[i])
					{
						int t = s.roomTicks(0);
						times.add(t);
						best = best < 0 ? t : Math.min(best, t);
					}
				}
				stats[i] = new DoorStat(pair[i], times.size(), Stats.median(times), best);
				enough &= times.size() >= DOOR_RUNS;
			}
			if (enough)
			{
				out.add(stats);
			}
		}
		return out;
	}

	/** The newest completed run times in a group, oldest first. */
	public static List<Integer> trend(List<Run> runs, int bucket)
	{
		List<Integer> out = new ArrayList<>();
		for (int i = runs.size() - 1; i >= 0 && out.size() < RECENT; i--)
		{
			Run r = runs.get(i);
			if (r.isCompleted() && Records.bucket(r.getTeamSize()) == bucket)
			{
				out.add(0, r.getTicks());
			}
		}
		return out;
	}

	/** How many times a clear beat every clear before it: each new personal best, the first clear included. */
	public static int personalBests(List<Run> runs, int bucket)
	{
		return ladder(runs, bucket).size();
	}

	/** Teammates in a group, the most raided with first. */
	public static List<Mate> crew(List<Run> runs, int bucket)
	{
		Map<String, int[]> byName = new LinkedHashMap<>();
		for (Run r : runs)
		{
			if (Records.bucket(r.getTeamSize()) != bucket)
			{
				continue;
			}
			for (String name : r.getCrew())
			{
				int[] m = byName.computeIfAbsent(name, k -> new int[]{0, 0, -1});
				m[0]++;
				if (r.isCompleted())
				{
					m[1]++;
					m[2] = m[2] < 0 ? r.getTicks() : Math.min(m[2], r.getTicks());
				}
			}
		}
		List<Mate> out = new ArrayList<>();
		byName.forEach((name, m) -> out.add(new Mate(name, m[0], m[1], m[2])));
		out.sort(Comparator.comparingInt((Mate m) -> -m.runs).thenComparingInt(m -> m.best < 0 ? Integer.MAX_VALUE : m.best));
		return out;
	}
}

package com.codex.archive.core;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Spots uniques arriving. It keeps the most of each unique the player has held (pack and worn
 * together) since the watch opened, and only more than that counts as a new one, so swapping a
 * weapon in and out, dropping one and picking it back up or charging it never makes a purple.
 */
public final class LootWatch
{
	private final Map<String, Integer> high = new HashMap<>();
	private boolean open;
	private int closesAt = Integer.MAX_VALUE;

	/** Opens the watch with what is held now, which is not new. */
	public void open(Map<String, Integer> held)
	{
		high.clear();
		if (held != null)
		{
			high.putAll(held);
		}
		open = true;
		closesAt = Integer.MAX_VALUE;
	}

	/** Keeps watching until a tick, then closes by itself. */
	public void closeAt(int tick)
	{
		closesAt = tick;
	}

	public void close()
	{
		open = false;
		high.clear();
	}

	public boolean isOpen(int tick)
	{
		if (open && tick > closesAt)
		{
			close();
		}
		return open;
	}

	/**
	 * @param held how many of each unique is held now
	 * @return each unique that arrived, once per copy
	 */
	public List<String> arrivals(Map<String, Integer> held, int tick)
	{
		List<String> out = new ArrayList<>();
		if (!isOpen(tick) || held == null)
		{
			return out;
		}
		for (Map.Entry<String, Integer> e : held.entrySet())
		{
			int before = high.getOrDefault(e.getKey(), 0);
			for (int i = before; i < e.getValue(); i++)
			{
				out.add(e.getKey());
			}
			if (e.getValue() > before)
			{
				high.put(e.getKey(), e.getValue());
			}
		}
		return out;
	}
}

package com.codex.archive.core;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the game's chat messages about the archive. The wording is matched loosely, so a small
 * change to it on the game's side still reads, and anything that does not match is ignored.
 */
public final class Messages
{
	private static final Pattern KC = Pattern.compile(
		"your (?:completed )?(?:[^.]*?archive[^.]*?) (?:completion |kill )?count is:? ?([\\d,]+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern WIPE = Pattern.compile(
		"(?:your party|your team|everyone) ha(?:s|ve) (?:fallen|been defeated|perished)", Pattern.CASE_INSENSITIVE);

	private Messages()
	{
	}

	/** The message without the game's colour and image tags. */
	public static String plain(String message)
	{
		return message == null ? "" : message.replaceAll("<[^>]*>", "").replace('\u00A0', ' ');
	}

	/** @return the completion count the message announces, or -1 when it announces none */
	public static int completionCount(String message)
	{
		Matcher m = KC.matcher(plain(message));
		if (!m.find())
		{
			return -1;
		}
		try
		{
			return Integer.parseInt(m.group(1).replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	/** Whether the message says the whole party fell. */
	public static boolean isWipe(String message)
	{
		return WIPE.matcher(plain(message)).find();
	}
}

package com.codex.archive.core;

/** How a run ended. */
public enum Outcome
{
	/** Ocellus fell. */
	COMPLETED,
	/** The whole party fell and was sent back to the lobby. */
	WIPED,
	/** The player left the archive before the end without the party falling. */
	LEFT
}

package com.codex.archive.core;

/**
 * Where the player is, as far as the archive goes: in its lobby, gone through its doors, or back
 * out. It works from what any client can see each tick (whether the scene is an instance, when
 * a scene loaded and whether the lobby's own NPCs are about), so it holds whether the lobby is
 * itself an instance or open world.
 */
public final class Presence
{
	/** What a tick means for the run. */
	public enum Action
	{
		NONE,
		BEGIN,
		END
	}

	/** How long after the lobby was last seen an instance still counts as the archive, about a minute. */
	public static final int LOBBY_TICKS = 100;
	/** Ticks after a scene load that still count as arriving in it. */
	static final int ARRIVAL_TICKS = 3;
	/** A run must be this old before meeting the lobby's NPCs again ends it, so their leaving at the start does not. */
	static final int RETURN_GRACE_TICKS = 20;

	private boolean inInstance;
	private int instanceSince = -1;
	private int lobbySeen = Integer.MIN_VALUE / 2;
	private int lobbyNpcs;
	private int loadedAt = Integer.MIN_VALUE / 2;

	/** One of the lobby's NPCs came into view, or left it. */
	public void lobbyNpc(boolean spawned, int tick)
	{
		lobbyNpcs = spawned ? lobbyNpcs + 1 : Math.max(0, lobbyNpcs - 1);
		lobbySeen = tick;
	}

	/** The lobby NPCs in view when the plugin starts, since it missed their arrival. */
	public void lobbyNpcsInView(int count, int tick)
	{
		lobbyNpcs = Math.max(0, count);
		if (count > 0)
		{
			lobbySeen = tick;
		}
	}

	/** The client loaded a new scene: a teleport, a door into an instance, a hop. */
	public void sceneLoaded(int tick)
	{
		loadedAt = tick;
	}

	/** Logged out or hopped: nothing seen before counts any more. */
	public void reset()
	{
		inInstance = false;
		instanceSince = -1;
		lobbyNpcs = 0;
	}

	public boolean isInInstance()
	{
		return inInstance;
	}

	/** In the lobby: its NPCs are in view. */
	public boolean isInLobby()
	{
		return lobbyNpcs > 0;
	}

	/**
	 * Called once a tick. A new scene is judged a few ticks after it loads, once the NPCs of the
	 * place left behind have gone and those of the new one have come: an instance with none of the
	 * lobby's NPCs, loaded just after the lobby was seen, is the archive.
	 *
	 * @param instance whether the scene is an instance this tick
	 * @param active whether a run is being timed
	 * @param elapsed the run's ticks so far, when one is
	 */
	public Action tick(int tick, boolean instance, boolean active, int elapsed)
	{
		if (instance && !inInstance)
		{
			instanceSince = tick;
		}
		int sinceLoad = tick - loadedAt;
		Action action = Action.NONE;
		if (active)
		{
			if (inInstance && !instance)
			{
				action = Action.END;
			}
			else if (instance && sinceLoad <= ARRIVAL_TICKS && lobbyNpcs > 0 && elapsed >= RETURN_GRACE_TICKS)
			{
				// Back among the lobby's NPCs after a load: out of the archive, even if the lobby is an instance too.
				action = Action.END;
			}
		}
		else if (instance && sinceLoad == ARRIVAL_TICKS && lobbyNpcs == 0 && tick - lobbySeen <= LOBBY_TICKS)
		{
			action = Action.BEGIN;
		}
		inInstance = instance;
		return action;
	}

	/** The tick a run judged to have begun now really began: the first tick in the new scene. */
	public int beginTick()
	{
		return loadedAt + 1;
	}

	/**
	 * When a run the plugin only noticed late, at the first boss, most likely began: when the
	 * lobby was left, or when the instance was entered, whichever came later.
	 */
	public int likelyStart(int tick)
	{
		int start = instanceSince >= 0 ? instanceSince : tick;
		if (lobbySeen > start && lobbySeen <= tick)
		{
			start = lobbySeen;
		}
		return Math.min(start, tick);
	}
}

package com.codex.archive.core;

import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Set;

/**
 * Personal bests and averages worked out from the run history. Times are only compared between
 * runs of the same party size, since a trio and a five clear the archive at different speeds.
 */
public final class Records
{
	public static final String[] BUCKETS = {"Solo", "Duo", "Trio", "4", "5", "6+"};

	private Records()
	{
	}

	/** The party-size group a run belongs to. */
	public static int bucket(int teamSize)
	{
		return Math.max(0, Math.min(BUCKETS.length - 1, teamSize - 1));
	}

	/** The fastest completed run in a party-size group, or null. */
	public static Run best(List<Run> runs, int bucket)
	{
		Run best = null;
		for (Run r : runs)
		{
			if (r.isCompleted() && bucket(r.getTeamSize()) == bucket && (best == null || r.getTicks() < best.getTicks()))
			{
				best = r;
			}
		}
		return best;
	}

	/** The fastest a row has been cleared in a party-size group, counting the walk in, or -1. */
	public static int bestRoom(List<Run> runs, int bucket, int row)
	{
		int best = -1;
		for (Run r : runs)
		{
			if (bucket(r.getTeamSize()) != bucket)
			{
				continue;
			}
			Split s = r.split(row);
			if (s != null && s.isDone())
			{
				int t = s.roomTicks(0);
				if (best < 0 || t < best)
				{
					best = t;
				}
			}
		}
		return best;
	}

	/** The fastest fight against one boss in a party-size group, from first hit to its fall, or -1. */
	public static int bestFight(List<Run> runs, int bucket, Encounter encounter)
	{
		int best = -1;
		for (Run r : runs)
		{
			if (bucket(r.getTeamSize()) != bucket)
			{
				continue;
			}
			Split s = r.split(encounter.getRow());
			if (s != null && s.isDone() && s.getEncounter() == encounter)
			{
				int t = s.fightTicks(0);
				if (best < 0 || t < best)
				{
					best = t;
				}
			}
		}
		return best;
	}

	/** Every row's best room added up: the run that is possible on a perfect day. -1 until every row has a time. */
	public static int sumOfBest(List<Run> runs, int bucket)
	{
		int sum = 0;
		for (int row = 0; row < Encounter.ROWS; row++)
		{
			int t = bestRoom(runs, bucket, row);
			if (t < 0)
			{
				return -1;
			}
			sum += t;
		}
		return sum;
	}

	/** The mean of the last few completed runs in a group, or -1. */
	public static int recentAverage(List<Run> runs, int bucket, int count)
	{
		long sum = 0;
		int n = 0;
		for (int i = runs.size() - 1; i >= 0 && n < count; i--)
		{
			Run r = runs.get(i);
			if (r.isCompleted() && bucket(r.getTeamSize()) == bucket)
			{
				sum += r.getTicks();
				n++;
			}
		}
		return n == 0 ? -1 : (int) (sum / n);
	}

	/** Every run that holds a record: a best time, a best room or a best fight, in any party size. */
	public static Set<Run> holders(List<Run> runs)
	{
		Set<Run> out = Collections.newSetFromMap(new IdentityHashMap<>());
		for (int bucket = 0; bucket < BUCKETS.length; bucket++)
		{
			Run best = best(runs, bucket);
			if (best != null)
			{
				out.add(best);
			}
			for (int row = 0; row < Encounter.ROWS; row++)
			{
				Run holder = null;
				for (Run r : runs)
				{
					Split s = r.split(row);
					if (bucket(r.getTeamSize()) == bucket && s != null && s.isDone()
						&& (holder == null || s.roomTicks(0) < holder.split(row).roomTicks(0)))
					{
						holder = r;
					}
				}
				if (holder != null)
				{
					out.add(holder);
				}
			}
			for (Encounter e : Encounter.values())
			{
				Run holder = null;
				for (Run r : runs)
				{
					Split s = r.split(e.getRow());
					if (bucket(r.getTeamSize()) == bucket && s != null && s.isDone() && s.getEncounter() == e
						&& (holder == null || s.fightTicks(0) < holder.split(e.getRow()).fightTicks(0)))
					{
						holder = r;
					}
				}
				if (holder != null)
				{
					out.add(holder);
				}
			}
		}
		return out;
	}

	public static int count(List<Run> runs, Outcome outcome)
	{
		int n = 0;
		for (Run r : runs)
		{
			if (r.getOutcome() == outcome)
			{
				n++;
			}
		}
		return n;
	}

	/** The party-size group with the most completions, so the panel opens on the one played most. */
	public static int favouriteBucket(List<Run> runs)
	{
		int[] counts = new int[BUCKETS.length];
		for (Run r : runs)
		{
			if (r.isCompleted())
			{
				counts[bucket(r.getTeamSize())]++;
			}
		}
		int best = 2;
		int most = 0;
		for (int i = 0; i < counts.length; i++)
		{
			if (counts[i] > most)
			{
				most = counts[i];
				best = i;
			}
		}
		return best;
	}

	/**
	 * How far ahead or behind a run is against a best run at the boss just fallen.
	 *
	 * @return ticks behind (negative when ahead), or null when either has no time for that row
	 */
	public static Integer delta(Run run, Run best, int row)
	{
		if (run == null || best == null)
		{
			return null;
		}
		Split a = run.split(row);
		Split b = best.split(row);
		if (a == null || b == null || !a.isDone() || !b.isDone())
		{
			return null;
		}
		return a.getEndTick() - b.getEndTick();
	}
}

package com.codex.archive.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** One trip into the archive, kept in the run history. */
public class Run
{
	/** The roles a raider can note for a run; free text goes in the note. Kept here so there is one list. */
	public static final String[] ROLES = {"Tank", "Melee", "Ranged", "Magic", "Support", "Learner"};
	/** Longest note kept, so one run cannot bloat the save. */
	public static final int NOTE_LENGTH = 80;
	/** Most teammates kept for one run. */
	public static final int CREW = 9;

	private long startedAt;
	private int teamSize;
	private Outcome outcome;
	/** Ticks from entering the archive to the final boss falling, or to leaving when it did not. */
	private int ticks;
	private List<Split> splits = new ArrayList<>();
	/** The completion count the game announced, or 0 when it said none. */
	private int kc;
	private int deaths;
	/** Supply units used, by kind: pieces of food, potion doses. */
	private Map<String, Integer> used = new LinkedHashMap<>();
	/** The unique the run gave, or null. */
	private String purple;
	/** The other raiders seen at the start, by name. */
	private List<String> crew = new ArrayList<>();
	/** The role the player noted for this run, or null. */
	private String role;
	/** The player's own note on the run, or null. */
	private String note;
	/**
	 * Big NPCs fought in the run that matched no boss, as "Name (level)", the most hit first;
	 * null when there were none. They show what the run saw when a boss was not recognised.
	 */
	private List<String> unknown;
	/** Most unrecognised NPCs kept for one run. */
	public static final int UNKNOWN = 4;

	public Run()
	{
	}

	Run(long startedAt, int teamSize)
	{
		this.startedAt = startedAt;
		this.teamSize = teamSize;
	}

	public long getStartedAt()
	{
		return startedAt;
	}

	public int getTeamSize()
	{
		return teamSize;
	}

	public Outcome getOutcome()
	{
		return outcome;
	}

	public int getTicks()
	{
		return ticks;
	}

	public List<Split> getSplits()
	{
		return Collections.unmodifiableList(splits);
	}

	public int getKc()
	{
		return kc;
	}

	public int getDeaths()
	{
		return deaths;
	}

	public Map<String, Integer> getUsed()
	{
		return Collections.unmodifiableMap(used);
	}

	public String getPurple()
	{
		return purple;
	}

	public List<String> getCrew()
	{
		return crew == null ? Collections.emptyList() : Collections.unmodifiableList(crew);
	}

	public String getRole()
	{
		return role;
	}

	public String getNote()
	{
		return note;
	}

	/** Big NPCs fought that matched no boss, "Name (level)", the most hit first. */
	public List<String> getUnknown()
	{
		return unknown == null ? Collections.emptyList() : Collections.unmodifiableList(unknown);
	}

	void setUnknown(List<String> names)
	{
		unknown = names == null || names.isEmpty() ? null : new ArrayList<>(names.subList(0, Math.min(UNKNOWN, names.size())));
	}

	/** Whether any boss of the run was guessed, or was not recognised at all. */
	public boolean hasDoubts()
	{
		for (Split s : splits)
		{
			if (s.getSeen() != null)
			{
				return true;
			}
		}
		// Unrecognised foes matter only when a boss went untimed: an add in a timed room is no doubt.
		return !getUnknown().isEmpty() && !untimedRows().isEmpty();
	}

	/**
	 * The rows up to the one the run ended in that have no split, so a boss the run reached went
	 * untimed; empty when every boss reached was timed, as in a wipe to a boss known by name.
	 */
	public List<Integer> untimedRows()
	{
		List<Integer> rows = new ArrayList<>();
		for (int row = 0; row < Math.min(Encounter.ROWS, reached() + 1); row++)
		{
			if (split(row) == null)
			{
				rows.add(row);
			}
		}
		return rows;
	}

	/** Forgets the detection notes, which only matter while the run is fresh. */
	void forgetDoubts()
	{
		unknown = null;
		for (Split s : splits)
		{
			s.forgetSeen();
		}
	}

	/** Adds a raider seen in the run, keeping the first few distinct names. */
	void addCrew(String name)
	{
		if (crew == null)
		{
			crew = new ArrayList<>();
		}
		if (name != null && !name.isEmpty() && crew.size() < CREW && !crew.contains(name))
		{
			crew.add(name);
		}
	}

	void setRole(String role)
	{
		this.role = role == null || role.trim().isEmpty() ? null : role.trim();
	}

	void setNote(String note)
	{
		String n = note == null ? "" : note.replaceAll("[\\r\\n\\t]+", " ").trim();
		this.note = n.isEmpty() ? null : n.length() > NOTE_LENGTH ? n.substring(0, NOTE_LENGTH) : n;
	}

	public boolean isCompleted()
	{
		return outcome == Outcome.COMPLETED;
	}

	/** The split for a row, or null when the run never reached it. */
	public Split split(int row)
	{
		for (Split s : splits)
		{
			if (s.getEncounter() != null && s.getEncounter().getRow() == row)
			{
				return s;
			}
		}
		return null;
	}

	/**
	 * How far the run has come: one past the furthest boss down. A row the client missed does not
	 * hold the count back, so the row after the furthest fall is always the one being fought.
	 */
	public int reached()
	{
		int n = 0;
		for (Split s : splits)
		{
			if (s.isDone() && s.getEncounter() != null)
			{
				n = Math.max(n, s.getEncounter().getRow() + 1);
			}
		}
		return n;
	}

	/** The doors this run took, as short names: "Bork, Dreadnoth, Trio". */
	public String route()
	{
		StringBuilder sb = new StringBuilder();
		for (int row = 1; row <= 3; row++)
		{
			Split s = split(row);
			if (s == null)
			{
				if (row < reached())
				{
					sb.append(sb.length() > 0 ? ", " : "").append("?");
				}
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(", ");
			}
			sb.append(s.getEncounter().getShortName());
		}
		return sb.toString();
	}

	void setTeamSize(int teamSize)
	{
		this.teamSize = teamSize;
	}

	void setKc(int kc)
	{
		this.kc = kc;
	}

	void setPurple(String purple)
	{
		this.purple = purple;
	}

	void finish(Outcome outcome, int ticks, int deaths, Map<String, Integer> used)
	{
		this.outcome = outcome;
		this.ticks = ticks;
		this.deaths = deaths;
		this.used = new LinkedHashMap<>(used);
	}

	List<Split> splitsMutable()
	{
		return splits;
	}

	/** Gson leaves fields it did not find null; this puts them right after a load. */
	Run repair()
	{
		if (splits == null)
		{
			splits = new ArrayList<>();
		}
		splits.removeIf(s -> s == null || s.getEncounter() == null);
		if (used == null)
		{
			used = new LinkedHashMap<>();
		}
		used.entrySet().removeIf(e -> e.getKey() == null || e.getValue() == null || e.getValue() < 0);
		ticks = Math.max(0, ticks);
		kc = Math.max(0, kc);
		deaths = Math.max(0, deaths);
		if (note != null && note.length() > NOTE_LENGTH)
		{
			note = note.substring(0, NOTE_LENGTH);
		}
		if (outcome == null)
		{
			outcome = Outcome.LEFT;
		}
		if (crew == null)
		{
			crew = new ArrayList<>();
		}
		crew.removeIf(n -> n == null || n.isEmpty());
		while (crew.size() > CREW)
		{
			crew.remove(crew.size() - 1);
		}
		if (unknown != null)
		{
			unknown.removeIf(n -> n == null);
		}
		return this;
	}

	Run copy()
	{
		Run r = new Run(startedAt, teamSize);
		r.outcome = outcome;
		r.ticks = ticks;
		for (Split s : splits)
		{
			r.splits.add(s.copy());
		}
		r.kc = kc;
		r.deaths = deaths;
		r.used = new LinkedHashMap<>(used);
		r.purple = purple;
		r.crew = new ArrayList<>(getCrew());
		r.role = role;
		r.note = note;
		r.unknown = unknown == null ? null : new ArrayList<>(unknown);
		return r;
	}
}

package com.codex.archive.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Times a run as it happens. The plugin feeds it what the client sees, in game ticks: the party
 * entering, the first hit on each boss, bosses falling, deaths and what is left in the pack. It
 * keeps every tick relative to the moment the party entered, which is what the splits show.
 *
 * <p>Several bosses change form part way through a fight, and a form "dying" is not the boss
 * falling, so a fall only closes the split once nothing of that encounter has been hit or seen
 * alive for a few ticks. Should the boss come back after that (a long phase change), the split
 * opens again, so a phase never leaves a short false time behind.
 */
public class RunTracker
{
	/** Ticks a fallen boss must stay fallen before its split closes, about four seconds. */
	public static final int CONFIRM_TICKS = 6;
	/** The final boss waits longer, since closing it ends the run: six seconds. */
	public static final int FINAL_CONFIRM_TICKS = 10;
	/** How long after a split closed its boss being hit again reopens it, thirty seconds. */
	public static final int REOPEN_TICKS = 50;
	/** The lowest combat level the plugin treats as the boss of an unnamed row. */
	public static final int UNNAMED_BOSS_LEVEL = 150;

	private Run run;
	private int base;
	private int lastEnd;
	private Split open;
	/** The split closed most recently, which a boss coming back can reopen. */
	private Split lastClosed;
	private int lastClosedAt = Integer.MIN_VALUE;
	/** Whether the split closed most recently was a guess at an unnamed boss. */
	private boolean lastClosedGuessed;
	/** The newest tick seen, relative to the run's start. */
	private int now;
	/** Whether the open split was opened by a guess at an unnamed boss, which a named boss of the row may correct. */
	private boolean guessed;
	private int pendingTick = -1;
	private int finalTick = -1;
	/** The game announced the completion, so nothing reopens any more. */
	private boolean announced;
	private int deaths;
	private final List<String> purples = new ArrayList<>();
	private final Map<Supply, Integer> last = new EnumMap<>(Supply.class);
	private final Map<Supply, Integer> used = new EnumMap<>(Supply.class);
	/** Hits on big NPCs that matched no boss, by "Name (level)", in the order first hit. */
	private final Map<String, Integer> foes = new LinkedHashMap<>();
	/** Most different unrecognised NPCs counted in one run, so a room full of adds cannot grow it without end. */
	private static final int FOES = 12;

	/** Starts a run. Any run already going is dropped, as the client can only be in one. */
	public void begin(long now, int tick, int teamSize, Map<Supply, Integer> pack)
	{
		run = new Run(now, Math.max(1, teamSize));
		base = tick;
		this.now = 0;
		lastEnd = 0;
		open = null;
		lastClosed = null;
		lastClosedAt = Integer.MIN_VALUE;
		lastClosedGuessed = false;
		guessed = false;
		pendingTick = -1;
		finalTick = -1;
		announced = false;
		deaths = 0;
		purples.clear();
		last.clear();
		used.clear();
		foes.clear();
		if (pack != null)
		{
			last.putAll(pack);
		}
	}

	public boolean isActive()
	{
		return run != null;
	}

	/** The row the next boss will be in: one past the furthest boss already down. */
	public int nextRow()
	{
		if (run == null)
		{
			return 0;
		}
		int done = 0;
		for (Split s : run.splitsMutable())
		{
			if (s.isDone())
			{
				done = Math.max(done, s.getEncounter().getRow() + 1);
			}
		}
		return done;
	}

	public boolean isFinished()
	{
		return finalTick >= 0;
	}

	/** Whether the game itself said the run was complete, which is final. */
	public boolean isAnnounced()
	{
		return announced;
	}

	/** Raises the party size when more raiders are seen than at the start. */
	public void seeTeam(int size)
	{
		if (run != null && size > run.getTeamSize() && open == null && nextRow() == 0)
		{
			run.setTeamSize(size);
		}
	}

	/** Notes the other raiders seen before the first boss falls, by name. */
	public void seeCrew(Iterable<String> names)
	{
		if (run == null || nextRow() > 0 || names == null)
		{
			return;
		}
		for (String name : names)
		{
			run.addCrew(name);
		}
	}

	/**
	 * Names the encounter an NPC belongs to. Two bosses have no name in the game's data yet, so a
	 * big NPC that matches nothing, met in the row one of them guards, is taken to be that boss.
	 *
	 * @return the encounter, or null when the NPC is not a boss of this run
	 */
	public Encounter resolve(String npcName, int combatLevel)
	{
		Encounter named = Encounter.byName(npcName);
		if (named != null || run == null || combatLevel < UNNAMED_BOSS_LEVEL)
		{
			return named;
		}
		if (open != null)
		{
			return open.getEncounter().isUnnamed() ? open.getEncounter() : null;
		}
		for (Encounter e : Encounter.ofRow(nextRow()))
		{
			if (e.isUnnamed())
			{
				return e;
			}
		}
		// Nothing unnamed waits ahead, but an unnamed boss just put down may only have changed form.
		if (canReopen() && lastClosed.getEncounter().isUnnamed())
		{
			return lastClosed.getEncounter();
		}
		return null;
	}

	private boolean canReopen()
	{
		return lastClosed != null && !announced && now - lastClosedAt <= REOPEN_TICKS
			&& lastClosed.getEncounter().getRow() == nextRow() - 1;
	}

	/**
	 * A big NPC was hit that is no boss of this run, as far as the names go. Kept so a run whose
	 * boss went unrecognised can show what it did see.
	 */
	public void foe(String npcName, int combatLevel)
	{
		if (run == null || npcName == null || npcName.isEmpty() || combatLevel < UNNAMED_BOSS_LEVEL)
		{
			return;
		}
		String key = (npcName.length() > 40 ? npcName.substring(0, 40) : npcName) + " (" + combatLevel + ")";
		if (foes.containsKey(key) || foes.size() < FOES)
		{
			foes.merge(key, 1, Integer::sum);
		}
	}

	/** A boss was hit, or seen fighting. The first time opens its split. */
	public void engage(Encounter encounter, int tick)
	{
		engage(encounter, tick, null, 0);
	}

	/**
	 * @param npcName the NPC hit, so a boss told by its row and size notes what it was told from
	 * @param combatLevel that NPC's combat level
	 */
	public void engage(Encounter encounter, int tick, String npcName, int combatLevel)
	{
		if (run == null || encounter == null || announced)
		{
			return;
		}
		int t = tick - base;
		now = Math.max(now, t);
		if (open != null)
		{
			if (open.getEncounter() == encounter)
			{
				// Still fighting: a form that fell was only a phase.
				pendingTick = -1;
				return;
			}
			if (encounter.getRow() == open.getEncounter().getRow() && guessed && !encounter.isUnnamed())
			{
				// What looked like the unnamed boss was something else in the room; this is the row's boss.
				open.retarget(encounter, t);
				guessed = false;
				pendingTick = -1;
				return;
			}
			if (encounter.getRow() <= open.getEncounter().getRow())
			{
				return;
			}
			// A later boss is up, so the open one fell without the client seeing it.
			close(pendingTick >= 0 ? pendingTick : t);
		}
		else if (lastClosed != null && lastClosedGuessed && !encounter.isUnnamed()
			&& encounter.getRow() == lastClosed.getEncounter().getRow() && lastClosed.getEncounter().getRow() == nextRow() - 1)
		{
			// What was taken for the unnamed boss fell, but it was an add: the row's named boss is only now being fought.
			lastClosed.retarget(encounter, t);
			reopenLast(false);
			return;
		}
		else if (lastClosed != null && lastClosed.getEncounter() == encounter && canReopen())
		{
			// The boss is back: what fell was a form, not the boss.
			reopenLast(lastClosedGuessed);
			return;
		}
		if (encounter.getRow() < nextRow())
		{
			return;
		}
		open = new Split(encounter, lastEnd, t);
		guessed = encounter.isUnnamed();
		if (npcName != null && Encounter.byName(npcName) != encounter)
		{
			open.guessedFrom(npcName, combatLevel);
		}
		run.splitsMutable().add(open);
	}

	private void reopenLast(boolean wasGuessed)
	{
		lastClosed.reopen();
		open = lastClosed;
		lastEnd = open.getStartTick();
		lastClosed = null;
		lastClosedGuessed = false;
		guessed = wasGuessed;
		finalTick = -1;
		pendingTick = -1;
	}

	/**
	 * A boss NPC fell.
	 *
	 * @param anyAlive whether another NPC of the same encounter is still standing, as with the trio
	 */
	public void fell(Encounter encounter, int tick, boolean anyAlive)
	{
		if (run == null || open == null || open.getEncounter() != encounter)
		{
			return;
		}
		if (anyAlive)
		{
			pendingTick = -1;
			return;
		}
		int t = tick - base;
		now = Math.max(now, t);
		// The death and the body leaving can both report a fall; the first is the true one.
		if (pendingTick < 0)
		{
			pendingTick = t;
		}
	}

	/** Closes a fallen boss's split once it has stayed down. */
	public void tick(int tick)
	{
		if (run == null)
		{
			return;
		}
		now = Math.max(now, tick - base);
		if (open != null && pendingTick >= 0)
		{
			int wait = open.getEncounter().getRow() == Encounter.ROWS - 1 ? FINAL_CONFIRM_TICKS : CONFIRM_TICKS;
			if (now - pendingTick >= wait)
			{
				close(pendingTick);
			}
		}
	}

	private void close(int t)
	{
		open.end(t);
		lastEnd = t;
		if (open.getEncounter().getRow() == Encounter.ROWS - 1)
		{
			finalTick = t;
		}
		lastClosed = open;
		lastClosedAt = now;
		lastClosedGuessed = guessed;
		open = null;
		guessed = false;
		pendingTick = -1;
	}

	/**
	 * The game announced the completion count, so the run is over whatever the client saw of the
	 * final boss. A final boss that fell closes at its fall; one never recognised leaves no split,
	 * and the run's time is the moment of the announcement.
	 */
	public void complete(int tick)
	{
		if (run == null || announced)
		{
			return;
		}
		int t = tick - base;
		now = Math.max(now, t);
		if (open != null)
		{
			boolean finalRow = open.getEncounter().getRow() == Encounter.ROWS - 1;
			if (pendingTick >= 0)
			{
				close(pendingTick);
			}
			else if (finalRow)
			{
				close(t);
			}
			else
			{
				// An earlier boss still open with no fall seen: its time is unknown, so it is dropped.
				run.splitsMutable().remove(open);
				open = null;
			}
		}
		if (finalTick < 0)
		{
			finalTick = t;
		}
		announced = true;
	}

	public void died()
	{
		if (run != null)
		{
			deaths++;
		}
	}

	/** What the pack holds now. Anything less than before was eaten or drunk; a resupply adding more is not counted. */
	public void pack(Map<Supply, Integer> units)
	{
		if (run == null || units == null)
		{
			return;
		}
		for (Supply s : Supply.values())
		{
			int now = units.getOrDefault(s, 0);
			int before = last.getOrDefault(s, now);
			if (now < before)
			{
				used.merge(s, before - now, Integer::sum);
			}
			last.put(s, now);
		}
	}

	public void kc(int kc)
	{
		if (run != null)
		{
			run.setKc(kc);
		}
	}

	/** A unique landed during the run. The first names the run; every one is logged when the run is recorded. */
	public void purple(String unique)
	{
		if (run != null && unique != null)
		{
			if (run.getPurple() == null)
			{
				run.setPurple(unique);
			}
			purples.add(unique);
		}
	}

	/** Every unique the run in progress has given, in order. */
	public List<String> purples()
	{
		return Collections.unmodifiableList(new ArrayList<>(purples));
	}

	/**
	 * Ends the run as the player leaves the archive.
	 *
	 * @param wiped whether the game sent the party out for falling
	 * @return the finished run, or null when none was going
	 */
	public Run finish(int tick, boolean wiped)
	{
		if (run == null)
		{
			return null;
		}
		if (open != null && pendingTick >= 0)
		{
			close(pendingTick);
		}
		Outcome outcome = finalTick >= 0 ? Outcome.COMPLETED : wiped || deaths > 0 ? Outcome.WIPED : Outcome.LEFT;
		int ticks = finalTick >= 0 ? finalTick : Math.max(0, tick - base);
		run.splitsMutable().removeIf(s -> !s.isDone() && outcome == Outcome.COMPLETED);
		run.finish(outcome, ticks, deaths, usedByTitle());
		List<Map.Entry<String, Integer>> seen = new ArrayList<>(foes.entrySet());
		// The most hit first; the sort keeps first-hit order on a tie.
		seen.sort((a, b) -> Integer.compare(b.getValue(), a.getValue()));
		List<String> names = new ArrayList<>();
		for (Map.Entry<String, Integer> e : seen)
		{
			names.add(e.getKey());
		}
		run.setUnknown(names);
		Run done = run;
		run = null;
		open = null;
		lastClosed = null;
		return done;
	}

	/** A copy of the run so far, for the panel and overlay. */
	public Run view(int tick)
	{
		if (run == null)
		{
			return null;
		}
		Run copy = run.copy();
		copy.finish(finalTick >= 0 ? Outcome.COMPLETED : null, elapsed(tick), deaths, usedByTitle());
		return copy;
	}

	/**
	 * Ticks since the run began. Once the final boss has fallen the clock stops at its fall, even
	 * before the fall is confirmed, so it never runs on and then jumps back.
	 */
	public int elapsed(int tick)
	{
		if (run == null)
		{
			return 0;
		}
		if (finalTick >= 0)
		{
			return finalTick;
		}
		if (open != null && pendingTick >= 0 && open.getEncounter().getRow() == Encounter.ROWS - 1)
		{
			return pendingTick;
		}
		return Math.max(0, tick - base);
	}

	private Map<String, Integer> usedByTitle()
	{
		Map<String, Integer> out = new LinkedHashMap<>();
		for (Supply s : Supply.values())
		{
			int n = used.getOrDefault(s, 0);
			if (n > 0)
			{
				out.put(s.name(), n);
			}
		}
		return out;
	}
}

package com.codex.archive.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * The run history in sittings: runs with less than a long break between them belong together.
 * Each sitting says how many clears and wipes it held, its best and average clear, the pace in
 * clears an hour, how long was spent between runs, how many personal bests it set and its purples.
 */
public final class Sessions
{
	/** A break longer than this between one run's end and the next one's start ends a sitting. */
	public static final long GAP_MS = 45 * 60_000L;
	private static final long TICK_MS = 600;

	/** One sitting. */
	public static final class Session
	{
		private final List<Run> runs;
		private final List<Run> counted;
		private final long start;
		private final long end;
		private final int clears;
		private final int wipes;
		private final int best;
		private final int average;
		private final int bests;
		private final int purples;
		private final long between;

		/**
		 * @param bucket the party-size group whose runs the figures count, or -1 for every run; the
		 *     sitting's start, end and time between runs always take every run
		 */
		Session(List<Run> runs, int bests, int bucket)
		{
			this.runs = Collections.unmodifiableList(runs);
			List<Run> mine = new ArrayList<>();
			this.start = runs.get(0).getStartedAt();
			this.end = endOf(runs.get(runs.size() - 1));
			int c = 0;
			int w = 0;
			int b = -1;
			long sum = 0;
			int p = 0;
			long gaps = 0;
			for (int i = 0; i < runs.size(); i++)
			{
				Run r = runs.get(i);
				if (i > 0)
				{
					gaps += Math.max(0, r.getStartedAt() - endOf(runs.get(i - 1)));
				}
				if (bucket >= 0 && Records.bucket(r.getTeamSize()) != bucket)
				{
					continue;
				}
				mine.add(r);
				if (r.isCompleted())
				{
					c++;
					sum += r.getTicks();
					b = b < 0 ? r.getTicks() : Math.min(b, r.getTicks());
				}
				else if (r.getOutcome() == Outcome.WIPED)
				{
					w++;
				}
				p += r.getPurple() != null ? 1 : 0;
			}
			this.counted = Collections.unmodifiableList(mine);
			this.clears = c;
			this.wipes = w;
			this.best = b;
			this.average = c == 0 ? -1 : (int) (sum / c);
			this.bests = bests;
			this.purples = p;
			this.between = runs.size() < 2 ? -1 : gaps / (runs.size() - 1);
		}

		public List<Run> getRuns()
		{
			return runs;
		}

		/** The runs the figures count: those of the party size asked for, or every run. */
		public List<Run> getCounted()
		{
			return counted;
		}

		public long getStart()
		{
			return start;
		}

		/** When the last run of the sitting ended. */
		public long getEnd()
		{
			return end;
		}

		public int getClears()
		{
			return clears;
		}

		public int getWipes()
		{
			return wipes;
		}

		/** The best clear in ticks, or -1 with none. */
		public int getBest()
		{
			return best;
		}

		/** The average clear in ticks, or -1 with none. */
		public int getAverage()
		{
			return average;
		}

		/** Clears that were a new personal best for their party size when they were made. */
		public int getBests()
		{
			return bests;
		}

		public int getPurples()
		{
			return purples;
		}

		/** The average time from one run's end to the next one's start, or -1 with one run. */
		public long getBetween()
		{
			return between;
		}

		/** Clears an hour, from the first run's start to the last one's end; 0 with under 15 minutes to go on. */
		public double perHour()
		{
			long span = end - start;
			return span < 15 * 60_000L ? 0 : clears * 3_600_000.0 / span;
		}
	}

	private Sessions()
	{
	}

	static long endOf(Run r)
	{
		return r.getStartedAt() + r.getTicks() * TICK_MS;
	}

	/** Every sitting, oldest first, counting every run. */
	public static List<Session> of(List<Run> runs)
	{
		return of(runs, -1);
	}

	/**
	 * Every sitting that held a run of a party-size group, oldest first, its figures counting only
	 * that group's runs. Sittings are still split by the breaks between all runs.
	 *
	 * @param bucket the party-size group, or -1 for every run
	 */
	public static List<Session> of(List<Run> runs, int bucket)
	{
		List<Run> sorted = new ArrayList<>(runs);
		sorted.sort((a, b) -> Long.compare(a.getStartedAt(), b.getStartedAt()));
		int[] bestSoFar = new int[Records.BUCKETS.length];
		java.util.Arrays.fill(bestSoFar, Integer.MAX_VALUE);
		List<Session> out = new ArrayList<>();
		List<Run> current = new ArrayList<>();
		int bests = 0;
		for (Run r : sorted)
		{
			if (!current.isEmpty() && r.getStartedAt() - endOf(current.get(current.size() - 1)) > GAP_MS)
			{
				add(out, current, bests, bucket);
				current = new ArrayList<>();
				bests = 0;
			}
			current.add(r);
			int b = Records.bucket(r.getTeamSize());
			if (r.isCompleted() && r.getTicks() < bestSoFar[b])
			{
				// The first clear of a party size is its first best, and counts; on a party tab, only that size's.
				bestSoFar[b] = r.getTicks();
				bests += bucket < 0 || b == bucket ? 1 : 0;
			}
		}
		if (!current.isEmpty())
		{
			add(out, current, bests, bucket);
		}
		return out;
	}

	/** Keeps a sitting when it held a run of the party size asked for. */
	private static void add(List<Session> out, List<Run> runs, int bests, int bucket)
	{
		Session s = new Session(runs, bests, bucket);
		if (!s.getCounted().isEmpty())
		{
			out.add(s);
		}
	}

	/** The sitting the newest run belongs to, if it ended within the gap of {@code now}; else null. */
	public static Session current(List<Run> runs, long now)
	{
		List<Session> all = of(runs);
		if (all.isEmpty())
		{
			return null;
		}
		Session last = all.get(all.size() - 1);
		return now - last.getEnd() <= GAP_MS ? last : null;
	}
}

package com.codex.archive.core;

/**
 * One encounter of a run. Times are game ticks from the moment the party entered the archive, so
 * the room time (since the last boss fell, walking included) and the fight itself both fall out.
 */
public class Split
{
	private Encounter encounter;
	/** When the previous boss fell, or the run began for the first encounter. */
	private int startTick;
	/** The first hit on this boss. */
	private int engageTick;
	/** When this boss fell; -1 while the fight goes on. */
	private int endTick = -1;
	/**
	 * For a boss told by its row and size rather than its name, the NPC it was told from and its
	 * combat level, so the player can see what the guess rested on; null when the name matched.
	 */
	private String seen;
	private Integer lvl;

	public Split()
	{
	}

	public Split(Encounter encounter, int startTick, int engageTick)
	{
		this.encounter = encounter;
		this.startTick = startTick;
		this.engageTick = engageTick;
	}

	public Encounter getEncounter()
	{
		return encounter;
	}

	public int getStartTick()
	{
		return startTick;
	}

	public int getEngageTick()
	{
		return engageTick;
	}

	public int getEndTick()
	{
		return endTick;
	}

	public boolean isDone()
	{
		return endTick >= 0;
	}

	void end(int tick)
	{
		endTick = tick;
	}

	void reopen()
	{
		endTick = -1;
	}

	/** A guessed boss turned out to be the row's other, named boss: the split is theirs, from their first hit. */
	void retarget(Encounter encounter, int engageTick)
	{
		this.encounter = encounter;
		this.engageTick = engageTick;
		// The name matched in the end, so nothing was guessed.
		this.seen = null;
		this.lvl = null;
	}

	/** Notes the NPC a guessed boss was told from. */
	void guessedFrom(String npcName, int combatLevel)
	{
		if (npcName != null && !npcName.isEmpty())
		{
			seen = npcName.length() > 40 ? npcName.substring(0, 40) : npcName;
			lvl = combatLevel > 0 ? combatLevel : null;
		}
	}

	/** The NPC this boss was guessed from, or null when it was known by name. */
	public String getSeen()
	{
		return seen;
	}

	/** That NPC's combat level, or 0 when not known. */
	public int getSeenLevel()
	{
		return lvl == null ? 0 : lvl;
	}

	/** Forgets what a guess rested on, to keep an old run's save small. */
	void forgetSeen()
	{
		seen = null;
		lvl = null;
	}

	/** The whole room, from the last boss falling to this one falling. */
	public int roomTicks(int now)
	{
		return (isDone() ? endTick : now) - startTick;
	}

	/** The fight alone, from the first hit. */
	public int fightTicks(int now)
	{
		return (isDone() ? endTick : now) - engageTick;
	}

	Split copy()
	{
		Split s = new Split(encounter, startTick, engageTick);
		s.endTick = endTick;
		s.seen = seen;
		s.lvl = lvl;
		return s;
	}
}

package com.codex.archive.core;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * The archive's uniques, the purples. They are matched by the game's item ids, and by name for
 * any form the game adds later; the shared loot (ascension shards and bolts, the folio, living
 * records, regular drops) never counts.
 */
public final class Spoils
{
	/** Name fragments of the uniques, most specific first. */
	private static final String[][] UNIQUES = {
		{"the obligator", "The Obligator"},
		{"obligator", "The Obligator"},
		{"ascension crossbow", "Ascension crossbow"},
		{"zorya's tome", "Zorya's tome"},
		{"zorya", "Zorya's tome"},
		{"rondache", "Rondache"},
		{"zeal", "Zeal"},
		{"elemental fragment", "Elemental fragment"},
		{"horn of bran", "Zeal"},
		{"fragment of living earth", "Elemental fragment"},
		{"fragment of deep water", "Elemental fragment"},
		{"fragment of whispering wind", "Elemental fragment"},
		{"fragment of burning fire", "Elemental fragment"},
		{"fragment of air", "Elemental fragment"},
		{"fragment of water", "Elemental fragment"},
		{"fragment of earth", "Elemental fragment"},
		{"fragment of fire", "Elemental fragment"},
	};

	private static final Map<Integer, String> BY_ID = new HashMap<>();

	static
	{
		BY_ID.put(34715, "The Obligator");
		BY_ID.put(34717, "The Obligator");
		BY_ID.put(34681, "Ascension crossbow");
		BY_ID.put(34725, "Zorya's tome");
		BY_ID.put(34727, "Zorya's tome");
		BY_ID.put(34719, "Rondache");
		// Zeal is unlocked from the Horn of Bran.
		BY_ID.put(34679, "Zeal");
		// Fragments of living earth, deep water, whispering wind and burning fire.
		BY_ID.put(34671, "Elemental fragment");
		BY_ID.put(34673, "Elemental fragment");
		BY_ID.put(34675, "Elemental fragment");
		BY_ID.put(34677, "Elemental fragment");
	}

	/** The uniques in the order the panel lists them. */
	public static final String[] ALL = {"The Obligator", "Ascension crossbow", "Zorya's tome", "Rondache", "Zeal", "Elemental fragment"};

	private Spoils()
	{
	}

	/**
	 * @return the unique this item is, by the panel's name for it, or null for anything else
	 */
	public static String unique(int itemId, String itemName)
	{
		String known = BY_ID.get(itemId);
		return known != null ? known : unique(itemName);
	}

	/**
	 * @return the unique an item of this name is, or null for anything else
	 */
	public static String unique(String itemName)
	{
		if (itemName == null)
		{
			return null;
		}
		String name = Encounter.clean(itemName);
		if (name.contains("ornament") || name.endsWith("(broken)") || name.contains("bolts"))
		{
			return null;
		}
		for (String[] u : UNIQUES)
		{
			// Whole words only, so a Zealot's robe is not Zeal.
			if ((" " + name.replaceAll("[^a-z' ]", " ") + " ").contains(" " + u[0].toLowerCase(Locale.ENGLISH) + " "))
			{
				return u[1];
			}
		}
		return null;
	}

	/** A short name that fits a small tablet. */
	public static String shortName(String unique)
	{
		switch (unique)
		{
			case "The Obligator":
				return "Obligator";
			case "Ascension crossbow":
				return "Crossbows";
			case "Zorya's tome":
				return "Tome";
			case "Elemental fragment":
				return "Fragment";
			default:
				return unique;
		}
	}

	/** The megarare has its own colour in the panel. */
	public static boolean isMegarare(String unique)
	{
		return "The Obligator".equals(unique);
	}
}

package com.codex.archive.core;

import java.util.List;

/**
 * How one run stood on the day it was raided: against the runs of the same party size that came
 * before it, never the ones after, so an old run's card still says "new best" if it was one. Kept
 * for the run card, which a player shares long after the run.
 */
public final class Standing
{
	private final Run run;
	private final Run priorBest;
	private final int clearNumber;
	private final int[] priorRooms = new int[Encounter.ROWS];
	private final boolean[] golds = new boolean[Encounter.ROWS];
	private final Integer[] deltas = new Integer[Encounter.ROWS];
	private int goldCount;

	private Standing(Run run, Run priorBest, int clearNumber)
	{
		this.run = run;
		this.priorBest = priorBest;
		this.clearNumber = clearNumber;
	}

	/** The run's standing among the runs kept; the run itself may or may not be among them. */
	public static Standing of(List<Run> runs, Run run)
	{
		int bucket = Records.bucket(run.getTeamSize());
		Run best = null;
		int clears = 0;
		int[] rooms = new int[Encounter.ROWS];
		for (Run r : runs)
		{
			if (r == run || r.getStartedAt() >= run.getStartedAt() || Records.bucket(r.getTeamSize()) != bucket)
			{
				continue;
			}
			if (r.isCompleted())
			{
				clears++;
				best = best == null || r.getTicks() < best.getTicks() ? r : best;
			}
			// A best room counts from any run that timed it, a wipe's earlier rooms included.
			for (int row = 0; row < Encounter.ROWS; row++)
			{
				Split s = r.split(row);
				if (s != null && s.isDone())
				{
					int t = s.roomTicks(0);
					rooms[row] = rooms[row] == 0 ? t : Math.min(rooms[row], t);
				}
			}
		}
		Standing st = new Standing(run, best, run.isCompleted() ? clears + 1 : 0);
		for (int row = 0; row < Encounter.ROWS; row++)
		{
			st.priorRooms[row] = rooms[row];
			Split s = run.split(row);
			if (s == null || !s.isDone())
			{
				continue;
			}
			// A gold beats a room timed before; the first time a row is timed there is nothing to beat.
			st.golds[row] = rooms[row] > 0 && s.roomTicks(0) < rooms[row];
			st.goldCount += st.golds[row] ? 1 : 0;
			Split b = best == null ? null : best.split(row);
			if (b != null && b.isDone())
			{
				st.deltas[row] = s.getEndTick() - b.getEndTick();
			}
		}
		return st;
	}

	public Run getRun()
	{
		return run;
	}

	/** The best clear of the same party size before this run, or null when there was none. */
	public Run getPriorBest()
	{
		return priorBest;
	}

	/** Whether it was the first clear of its party size. */
	public boolean isFirstClear()
	{
		return run.isCompleted() && priorBest == null;
	}

	/** Whether it beat every clear of its party size before it. A first clear is one too. */
	public boolean isNewBest()
	{
		return run.isCompleted() && (priorBest == null || run.getTicks() < priorBest.getTicks());
	}

	/** Ticks against the best before it: below nought is quicker. Null for a wipe or a first clear. */
	public Integer totalDelta()
	{
		return run.isCompleted() && priorBest != null ? run.getTicks() - priorBest.getTicks() : null;
	}

	/** Which clear of its party size it was, the first being 1; 0 for a run that did not clear. */
	public int getClearNumber()
	{
		return clearNumber;
	}

	/** Whether a row's room was quicker than any before it. */
	public boolean isGold(int row)
	{
		return golds[row];
	}

	public int getGoldCount()
	{
		return goldCount;
	}

	/** Rows the run timed whose room had been timed before, so a gold was there to be had. */
	public int getComparedRooms()
	{
		int n = 0;
		for (int row = 0; row < Encounter.ROWS; row++)
		{
			Split s = run.split(row);
			n += s != null && s.isDone() && priorRooms[row] > 0 ? 1 : 0;
		}
		return n;
	}

	/** The quickest room for a row before this run, or 0 when none was timed. */
	public int priorRoom(int row)
	{
		return priorRooms[row];
	}

	/** The run's time when a row's boss fell, against the best before it at the same boss; or null. */
	public Integer delta(int row)
	{
		return deltas[row];
	}
}

package com.codex.archive.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Small order statistics over tick counts. */
public final class Stats
{
	private Stats()
	{
	}

	/** The middle value, the mean of the two middle ones for an even count, or -1 for none. */
	public static int median(List<Integer> values)
	{
		return percentile(values, 0.5);
	}

	/** The value this share of the way up, interpolated between neighbours, or -1 for none. */
	public static int percentile(List<Integer> values, double share)
	{
		if (values == null || values.isEmpty())
		{
			return -1;
		}
		List<Integer> sorted = new ArrayList<>(values);
		Collections.sort(sorted);
		double at = share * (sorted.size() - 1);
		int lo = (int) Math.floor(at);
		int hi = Math.min(sorted.size() - 1, lo + 1);
		return (int) Math.round(sorted.get(lo) + (sorted.get(hi) - sorted.get(lo)) * (at - lo));
	}

	/** The standard deviation, or -1 with fewer than two values. */
	public static int deviation(List<Integer> values)
	{
		if (values == null || values.size() < 2)
		{
			return -1;
		}
		double mean = 0;
		for (int v : values)
		{
			mean += v;
		}
		mean /= values.size();
		double sum = 0;
		for (int v : values)
		{
			sum += (v - mean) * (v - mean);
		}
		return (int) Math.round(Math.sqrt(sum / (values.size() - 1)));
	}
}

package com.codex.archive.core;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * What a raider carries in. Nothing can be banked once inside the archive, so the pack check
 * counts these before the doors close, and the run history counts what each run ate and drank.
 * Items are told apart by name, so new potions in a family are counted without an update.
 */
public enum Supply
{
	FOOD("Food", "pieces"),
	BREWS("Brews", "doses"),
	RESTORES("Restores", "doses"),
	BOOSTS("Boosts", "doses");

	private static final Pattern DOSES = Pattern.compile("^(.*)\\((\\d)\\)$");

	private static final Set<String> FOODS = new HashSet<>(Arrays.asList(
		"shark", "manta ray", "anglerfish", "dark crab", "sea turtle", "tuna potato", "mushroom potato",
		"cooked karambwan", "monkfish", "curry", "pineapple pizza", "anchovy pizza", "meat pizza",
		"cooked moonlight antelope", "cooked sunlight antelope", "cooked dashing kebbit", "cooked wild kebbit",
		"cooked pyre fox", "cooked larupia", "cooked graahk", "cooked kyatt", "potato with cheese",
		"egg potato", "chilli potato", "swordfish", "lobster", "bass", "cooked bream", "cooked moss lizard",
		"tangled toad's legs", "summer pie", "half a summer pie", "wild pie", "half a wild pie",
		"botanical pie", "half a botanical pie", "admiral pie", "half an admiral pie", "cooked jubbly",
		"basket of strawberries", "jug of wine", "blighted manta ray", "blighted anglerfish", "blighted karambwan",
		"paddlefish", "leftovers"));

	private final String title;
	private final String unit;

	Supply(String title, String unit)
	{
		this.title = title;
		this.unit = unit;
	}

	public String getTitle()
	{
		return title;
	}

	public String getUnit()
	{
		return unit;
	}

	/**
	 * How many units of a supply one of these items is: a piece of food is one, a potion is its doses.
	 *
	 * @return the units, or 0 when the item is not a supply
	 */
	public int units(String itemName)
	{
		return this == of(itemName) ? unitsOf(itemName) : 0;
	}

	/** The kind of supply an item is, or null. */
	public static Supply of(String itemName)
	{
		if (itemName == null)
		{
			return null;
		}
		String name = Encounter.clean(itemName);
		Matcher m = DOSES.matcher(name);
		if (m.matches())
		{
			String potion = m.group(1).trim();
			if (potion.contains("saradomin brew") || potion.startsWith("ancient brew"))
			{
				return BREWS;
			}
			if (potion.contains("restore") || potion.startsWith("prayer potion") || potion.startsWith("sanfew")
				|| potion.startsWith("prayer regeneration") || potion.contains("moonlight potion"))
			{
				return RESTORES;
			}
			if (potion.contains("combat") || potion.contains("ranging") || potion.contains("bastion")
				|| potion.contains("battlemage") || potion.contains("magic potion") || potion.contains("super strength")
				|| potion.contains("super attack") || potion.contains("super defence") || potion.contains("forgotten brew")
				|| potion.contains("overload"))
			{
				return BOOSTS;
			}
			return null;
		}
		return FOODS.contains(name) ? FOOD : null;
	}

	/** A potion's doses, or one for anything else. */
	static int unitsOf(String itemName)
	{
		Matcher m = DOSES.matcher(Encounter.clean(itemName));
		return m.matches() ? Integer.parseInt(m.group(2)) : 1;
	}

	public static String lower(String s)
	{
		return s.toLowerCase(Locale.ENGLISH);
	}
}

package com.codex.archive.core;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.util.Map;

/**
 * Tells whether a save holds anything its read-back lacks: a field or an entry of a kind a later
 * version keeps, or something damage put in that reading had to leave out. Such a save reads
 * without an error, but the next save would quietly drop what this version did not understand,
 * so it is worth setting aside first. Figures set right in reading (a count below zero brought
 * up to it) are not counted; nor is a nothing (zero, false, empty) that the read-back leaves out.
 */
final class Unread
{
	private Unread()
	{
	}

	/** True when the save holds anything that reading it back left out. */
	static boolean any(Gson gson, String saved, Object read)
	{
		try
		{
			return lost(gson.fromJson(saved, JsonElement.class), gson.toJsonTree(read));
		}
		catch (RuntimeException e)
		{
			return true;
		}
	}

	private static boolean lost(JsonElement saved, JsonElement back)
	{
		if (nothing(saved))
		{
			return false;
		}
		if (back == null || back.isJsonNull())
		{
			return true;
		}
		if (saved.isJsonObject())
		{
			if (!back.isJsonObject())
			{
				return true;
			}
			JsonObject b = back.getAsJsonObject();
			for (Map.Entry<String, JsonElement> e : saved.getAsJsonObject().entrySet())
			{
				if (lost(e.getValue(), b.get(e.getKey())))
				{
					return true;
				}
			}
			return false;
		}
		if (saved.isJsonArray())
		{
			if (!back.isJsonArray())
			{
				return true;
			}
			JsonArray s = saved.getAsJsonArray();
			JsonArray b = back.getAsJsonArray();
			if (s.size() > b.size())
			{
				return true;
			}
			// Reading can add to a list (a count of boss clears filled out to every party size) but not take from it;
			// a list read back the same length is checked item by item.
			if (s.size() == b.size())
			{
				for (int i = 0; i < s.size(); i++)
				{
					if (lost(s.get(i), b.get(i)))
					{
						return true;
					}
				}
			}
			return false;
		}
		// A figure: kept when the read-back has one in its place, set right or not.
		return !back.isJsonPrimitive();
	}

	private static boolean nothing(JsonElement e)
	{
		if (e == null || e.isJsonNull())
		{
			return true;
		}
		if (e.isJsonPrimitive())
		{
			JsonPrimitive p = e.getAsJsonPrimitive();
			if (p.isBoolean())
			{
				return !p.getAsBoolean();
			}
			if (p.isNumber())
			{
				return p.getAsBigDecimal().signum() == 0;
			}
			return p.getAsString().isEmpty();
		}
		return e.isJsonArray() ? e.getAsJsonArray().size() == 0 : e.getAsJsonObject().size() == 0;
	}
}

package com.codex.archive.overlay;

import com.codex.archive.core.Supply;
import com.codex.archive.ui.Sigil;
import com.codex.archive.ui.Theme;
