	private void rebuild()
	{
		updateCrest();
		rebuildRun();
		rebuildRecords(true);
		rebuildSpoils();
	}

	private List<Run> runs()
	{
		return view.archive == null ? java.util.Collections.emptyList() : view.archive.getRuns();
	}

	private void updateCrest()
	{
		String heading = view.player != null ? view.player + "  \u00b7  ARCHIVE" : "FRACTURED ARCHIVE";
		if (view.archive == null)
		{
			crest.update(heading, "", null, false, "Log in to open the archive", null, null, null);
			return;
		}
		Archive a = view.archive;
		Run live = view.live;
		if (live != null)
		{
			int bucket = Records.bucket(live.getTeamSize());
			int row = live.reached();
			Split split = row < Encounter.ROWS ? live.split(row) : null;
			Comparison cmp = view.comparison;
			Integer delta = row > 0 && cmp != null ? cmp.delta(live, lastTimed(live, row - 1)) : null;
			String room = split == null ? (row >= Encounter.ROWS ? "Cleared" : "Walking") : split.getEncounter().getShortName();
			int possible = Comparison.bestPossible(live, view.bestRooms, live.getTicks());
			crest.update(heading, Format.clock(live.getTicks()), Records.BUCKETS[bucket].toLowerCase(), true, null,
				new String[]{"Room", view.measuredAgainst().getShortLabel(), "Can hit"},
				new String[]{room, delta == null ? "-" : Format.delta(delta), possible < 0 ? "-" : Format.clock(possible)},
				new Color[]{Theme.mix(Theme.TEAL, Theme.TEXT, 0.4), delta == null ? Theme.TEXT_FAINT : Theme.delta(delta), Theme.GOLD});
			return;
		}
		int bucket = party.getSelected();
		Run best = Records.best(a.getRuns(), bucket);
		String status = a.getRuns().isEmpty() ? (view.inLobby ? "In the lobby" : "Enter the archive to begin") : null;
		crest.update(heading, best == null ? "-" : Format.ticks(best.getTicks()),
			best == null ? null : Records.BUCKETS[bucket].toLowerCase(), false, status,
			new String[]{"KC", "Dry", "Purples"},
			new String[]{Format.count(Math.max(a.getKc(), totalClears(a))),
				String.valueOf(a.getDry()), String.valueOf(a.getDrops().size())},
			new Color[]{Theme.TEXT, a.getDry() >= 30 ? Theme.EMBER : Theme.TEXT, a.getDrops().isEmpty() ? Theme.TEXT_FAINT : Theme.PURPLE});
	}

	private void rebuildRun()
	{
		String key = runKey();
		if (key.equals(runKey) && view.live != null)
		{
			// Mid-run the page keeps its shape; only the thread, the clocks and the bars move.
			refreshLive();
			return;
		}
		if (runKey != null && !key.equals(runKey))
		{
			// A note on where the last card went belongs to that page, not the next run's.
			cardNote = null;
		}
		runKey = key;
		StackPanel stack = new StackPanel(Theme.GUTTER, Theme.GUTTER);
		if (view.archive == null)
		{
			stack.add(note("The archive is closed", "Log in and Codex Archive Splits times every trip into the Fractured Archive: each room, each fight and the whole run, against your best for the same party size."));
			setPage(runPage, stack);
			return;
		}
		if (view.inLobby && view.checksPack())
		{
			stack.add(new SectionHeader("Before you enter", "no bank inside"));
			packCard.update(view.pack, view.targets);
			stack.add(packCard);
		}
		else if (view.inLobby)
		{
			stack.add(note("In the lobby", "Set how much food and how many doses you want to carry in, under Pack check in the plugin's settings, and this page checks your pack before the doors close."));
		}
		Run run = view.live != null ? view.live : view.archive.last();
		if (run == null)
		{
			stack.add(note("No runs yet", "Enter the archive and your first run is timed from the moment the doors close. Each boss gets a split as it falls; the Guardian and Ocellus always, and whichever door you take in the three rows between."));
			setPage(runPage, stack);
			return;
		}
		boolean live = view.live != null;
		int bucket = Records.bucket(run.getTeamSize());
		// Against itself every delta is nothing; a finished run is measured against the runs before it.
		Run best = bestExcept(runs(), bucket, run);
		Comparison against = live ? view.comparison : Comparison.of(view.archive, bucket, view.compare, run);
		String trailing = (live ? "live, " + Records.BUCKETS[bucket].toLowerCase() : Format.ago(view.now - run.getStartedAt()))
			+ ", vs " + (against == null ? view.compare : against.getMode()).getShortLabel();
		stack.add(new SectionHeader(live ? "This run" : "Last run", trailing));
		if (live)
		{
			table.update(run, view.comparison, view.bestRooms, run.getTicks(), true);
		}
		else
		{
			table.update(run, against, View.bestRooms(view.archive, run), run.getTicks(), false);
		}
		stack.add(table);

		if (!live)
		{
			stack.add(summary(run, best));
			String route = routeLine(run, bucket);
			if (route != null)
			{
				stack.add(Ui.wrapped(route, Theme.small(), Theme.TEXT_MUTED, WIDTH - 16));
			}
			List<String> doubts = Doubts.of(run);
			if (!doubts.isEmpty())
			{
				stack.add(doubts(doubts));
			}
			// The run as a picture to share: what a clear is for, after the clear itself.
			JPanel buttons = new JPanel(new java.awt.FlowLayout(java.awt.FlowLayout.CENTER, 6, 0));
			buttons.setOpaque(false);
			buttons.add(new CodexButton("Save run card", true, () -> saveCard(run)));
			buttons.add(new CodexButton("Copy run card", false, () -> copyCard(run)));
			stack.add(buttons);
			if (cardNote != null && !noteOnSession)
			{
				stack.add(Ui.wrapped(cardNote, Theme.small(), Theme.TEAL, WIDTH - 16));
			}
		}
		Map<Supply, Integer> used = used(run);
		if (!used.isEmpty())
		{
			usedCard.update(used, null);
			stack.add(usedCard);
		}
		Sessions.Session session = live ? null : Sessions.current(runs(), view.now);
		if (session != null && session.getRuns().size() > 1)
		{
			session(stack, session);
		}
		setPage(runPage, stack);
	}

	/** Everything that decides the run page's shape, so it is only rebuilt when that changes. */
	private String runKey()
	{
		Run run = view.live != null ? view.live : view.archive == null ? null : view.archive.last();
		return System.identityHashCode(view.archive) + "|" + view.compare + "|" + (view.live != null) + "|" + view.inLobby + "|" + view.checksPack()
			+ "|" + (run == null ? "" : run.getStartedAt() + ":" + run.getTeamSize() + ":" + used(run).isEmpty())
			+ "|" + (view.live == null ? view.now / 60_000 : 0);
	}

	/** One tick of a live run on an unchanged page. */
	private void refreshLive()
	{
		Run run = view.live;
		table.update(run, view.comparison, view.bestRooms, run.getTicks(), true);
		Map<Supply, Integer> used = used(run);
		if (!used.isEmpty())
		{
			usedCard.update(used, null);
		}
	}

	private static Map<Supply, Integer> used(Run run)
	{
		Map<Supply, Integer> used = new EnumMap<>(Supply.class);
		for (Map.Entry<String, Integer> e : run.getUsed().entrySet())
		{
			try
			{
				used.put(Supply.valueOf(e.getKey()), e.getValue());
			}
			catch (IllegalArgumentException ignored)
			{
				// A kind of supply a later version no longer counts.
			}
		}
		return used;
	}

	/** The furthest row at or before this one whose boss has a time, so a missed row still leaves a delta. */
	private static int lastTimed(Run run, int row)
	{
		for (int r = row; r >= 0; r--)
		{
			Split s = run.split(r);
			if (s != null && s.isDone())
			{
				return r;
			}
		}
		return row;
	}

	private static Run bestExcept(List<Run> runs, int bucket, Run except)
	{
		Run best = null;
		for (Run r : runs)
		{
			if (r != except && r.isCompleted() && Records.bucket(r.getTeamSize()) == bucket && (best == null || r.getTicks() < best.getTicks()))
			{
				best = r;
			}
		}
		return best;
	}

	/** Three tablets under a finished run: its time, the best before it and the deaths. */
	private JComponent summary(Run run, Run previousBest)
	{
		JPanel grid = new JPanel(new GridLayout(1, 3, 6, 0));
		grid.setOpaque(false);
		if (run.isCompleted())
		{
			boolean pb = previousBest == null || run.getTicks() < previousBest.getTicks();
			grid.add(new StatTile(Format.ticks(run.getTicks()), "Time", pb ? "new best" : "cleared", pb ? Theme.GOLD_BRIGHT : Theme.TEXT));
		}
		else
		{
			grid.add(new StatTile(run.getOutcome() == Outcome.WIPED ? "Wiped" : "Left", "Ended", "at " + Format.ticks(run.getTicks()),
				run.getOutcome() == Outcome.WIPED ? Theme.BLOOD : Theme.TEXT_MUTED));
		}
		if (previousBest != null && run.isCompleted())
		{
			int d = run.getTicks() - previousBest.getTicks();
			grid.add(new StatTile(Format.delta(d), "On best", Format.ticks(previousBest.getTicks()), Theme.delta(d)));
		}
		else
		{
			grid.add(new StatTile(run.getKc() > 0 ? Format.count(run.getKc()) : "-", "KC", "in all", Theme.TEXT));
		}
		grid.add(new StatTile(String.valueOf(run.getDeaths()), "Deaths", Records.BUCKETS[Records.bucket(run.getTeamSize())].toLowerCase(),
			run.getDeaths() == 0 ? Theme.GREEN : Theme.EMBER));
		return grid;
	}

	/** How a clear stands on its own route of doors, or null when that cannot be said. */
	private String routeLine(Run run, int bucket)
	{
		List<Encounter> doors = Insights.doors(run);
		if (!run.isCompleted() || doors == null)
		{
			return null;
		}
		int[] before = Insights.routeBest(runs(), bucket, run);
		String name = doors.get(0).getShortName() + ", " + doors.get(1).getShortName() + ", " + doors.get(2).getShortName();
		if (before[0] < 0)
		{
			return "First clear through " + name + ".";
		}
		int d = run.getTicks() - before[0];
		if (d == 0)
		{
			return "Level with your best through " + name + ".";
		}
		return d < 0 ? "Fastest yet through " + name + ", " + Format.span(-d) + " under the " + before[1] + (before[1] == 1 ? " clear" : " clears") + " before."
			: Format.span(d) + " behind your best through " + name + " (" + Format.ticks(before[0]) + ").";
	}

	/** Newest personal bests listed, routes listed, and bosses listed under where runs wipe. */
	private static final int LADDER = 5;
	private static final int ROUTES = 4;
	private static final int WALLS = 3;

	private void rebuildRecords(boolean force)
	{
		int bucket = party.getSelected();
		if (!force && recordsFor == view.archive && recordsBucket == bucket)
		{
			return;
		}
		recordsFor = view.archive;
		recordsBucket = bucket;
		StackPanel stack = new StackPanel(Theme.GUTTER, Theme.GUTTER);
		if (view.archive == null)
		{
			stack.add(note("The archive is closed", "Log in to see your personal bests."));
			setPage(recordsPage, stack);
			return;
		}
		stack.add(party);
		List<Run> runs = runs();
		Run best = Records.best(runs, bucket);
		int sob = Records.sumOfBest(runs, bucket);
		int avg = Records.recentAverage(runs, bucket, 10);
		int done = 0;
		int wiped = 0;
		int left = 0;
		for (Run r : runs)
		{
			if (Records.bucket(r.getTeamSize()) == bucket)
			{
				done += r.isCompleted() ? 1 : 0;
				wiped += r.getOutcome() == Outcome.WIPED ? 1 : 0;
				left += r.getOutcome() == Outcome.LEFT ? 1 : 0;
			}
		}
		JPanel grid = new JPanel(new GridLayout(2, 2, 6, 6));
		grid.setOpaque(false);
		grid.add(new StatTile(best == null ? "-" : Format.ticks(best.getTicks()), "Best", best == null ? "no clear yet" : Format.shortDay(best.getStartedAt()), Theme.GOLD_BRIGHT));
		grid.add(new StatTile(sob < 0 ? "-" : Format.ticks(sob), "Sum of best", sob < 0 || best == null ? "every room" : Format.delta(sob - best.getTicks()) + " on best", Theme.TEAL));
		grid.add(new StatTile(avg < 0 ? "-" : Format.ticks(avg), "Average", "last 10 clears", Theme.TEXT));
		int allClears = view.archive.clears(bucket);
		int allWipes = view.archive.wipes(bucket);
		grid.add(new StatTile(Format.count(allClears), "Clears", allWipes == 0 ? "no wipes" : Format.count(allWipes) + (allWipes == 1 ? " wipe" : " wipes"), Theme.TEXT));
		stack.add(grid);
		goal(stack, runs, bucket);

		// A party size with nothing timed yet has no rooms or fights to list, only rows of dashes.
		boolean timed = false;
		for (Run r : runs)
		{
			timed |= Records.bucket(r.getTeamSize()) == bucket && r.reached() > 0;
		}
		if (timed)
		{
			stack.add(new SectionHeader("Best rooms", "and a typical one"));
			stack.add(rooms(runs, bucket));

			stack.add(new SectionHeader("Best fights", "first hit to fall"));
			Card fights = new Card(new GridLayout(0, 1, 0, 2));
			for (Encounter e : Encounter.values())
			{
				int t = Records.bestFight(runs, bucket, e);
				fights.add(line(e.getTitle(), t < 0 ? "-" : Format.ticks(t), t < 0 ? Theme.TEXT_FAINT : Theme.TEXT));
			}
			stack.add(fights);
		}

		List<Integer> trend = Insights.trend(runs, bucket);
		if (trend.size() >= 3)
		{
			stack.add(new SectionHeader("Steadiness", "last " + trend.size() + " clears"));
			stack.add(new TrendChart(trend, best == null ? -1 : best.getTicks(), Stats.median(trend)));
			JPanel steady = new JPanel(new GridLayout(1, 3, 6, 0));
			steady.setOpaque(false);
			int spread = Stats.deviation(trend);
			steady.add(new StatTile("±" + Format.span(spread), "Spread", "typical", Theme.TEXT));
			int pbs = Insights.personalBests(runs, bucket);
			steady.add(new StatTile(String.valueOf(pbs), "Bests", pbs == 1 ? "set once" : "times set", Theme.GOLD));
			int attempts = allClears + allWipes;
			// Rounded down once there is a wipe, so 199 clears and a wipe never read as 100%.
			long rate = attempts == 0 ? 0 : allWipes > 0 ? 100L * allClears / attempts : 100;
			steady.add(new StatTile(attempts == 0 ? "-" : rate + "%", "Clears", "of tries",
				allWipes == 0 ? Theme.GREEN : Theme.TEXT));
			stack.add(steady);
		}

		List<Insights.Best> ladder = Insights.ladder(runs, bucket);
		if (ladder.size() >= 2)
		{
			Insights.Best first = ladder.get(0);
			Insights.Best last = ladder.get(ladder.size() - 1);
			stack.add(new SectionHeader("Your best, over time", Format.span(first.ticks - last.ticks) + " off"));
			Card card = new Card(new GridLayout(0, 1, 0, 4));
			for (int i = ladder.size() - 1; i >= Math.max(0, ladder.size() - LADDER); i--)
			{
				Insights.Best b = ladder.get(i);
				card.add(twoLine(Format.day(b.at), b.saved < 0 ? "first clear" : Format.span(b.saved) + " off the one before",
					Format.ticks(b.ticks), i == ladder.size() - 1 ? "best now" : "", i == ladder.size() - 1 ? Theme.GOLD_BRIGHT : Theme.TEXT));
			}
			if (ladder.size() > LADDER)
			{
				card.add(Ui.label((ladder.size() - LADDER) + " more before, from " + Format.ticks(first.ticks),
					Theme.small(), Theme.TEXT_FAINT));
			}
			stack.add(card);
		}

		List<Insights.DoorStat[]> doors = Insights.doors(runs, bucket);
		if (!doors.isEmpty())
		{
			stack.add(new SectionHeader("Doors", "typical room"));
			Card card = new Card(new GridLayout(0, 1, 0, 8));
			for (Insights.DoorStat[] pair : doors)
			{
				card.add(doorLine(pair));
			}
			stack.add(card);
		}

		List<Insights.RouteStat> routes = Insights.routes(runs, bucket);
		if (routes.size() >= 2)
		{
			stack.add(new SectionHeader("Routes", "best clear"));
			// Stacked, not a grid: a grid would stretch the one-line trailer to a three-line route's height.
			Card card = new Card(new StackPanel.StackLayout(6));
			for (int i = 0; i < Math.min(ROUTES, routes.size()); i++)
			{
				Insights.RouteStat r = routes.get(i);
				// The route takes a line of its own: three boss names beside a time clip at sidebar width.
				JPanel row = new JPanel(new BorderLayout(0, 1));
				row.setOpaque(false);
				row.add(Ui.label(r.name(), Theme.body(), Theme.TEXT), BorderLayout.NORTH);
				row.add(twoLine(r.clears + (r.clears == 1 ? " clear" : " clears"), Theme.small(), r.clears >= 3 ? "typical " + Format.ticks(r.typical) : "",
					Format.ticks(r.best), i == 0 ? "fastest" : "+" + Format.span(r.best - routes.get(0).best), i == 0 ? Theme.GOLD_BRIGHT : Theme.TEXT), BorderLayout.CENTER);
				row.setToolTipText("<html>" + r.name() + "<br>Best clear " + Format.ticks(r.best) + (r.clears >= 2 ? ", middle of " + r.clears + " clears " + Format.ticks(r.typical) : "") + "</html>");
				card.add(row);
			}
			if (routes.size() > ROUTES)
			{
				card.add(Ui.label("and " + (routes.size() - ROUTES) + " slower " + (routes.size() - ROUTES == 1 ? "route" : "routes"), Theme.small(), Theme.TEXT_FAINT));
			}
			stack.add(card);
		}

		List<Insights.Wall> walls = Insights.walls(runs, bucket);
		if (!walls.isEmpty())
		{
			stack.add(new SectionHeader("Where runs wipe", null));
			Card card = new Card(new GridLayout(0, 1, 0, 4));
			for (int i = 0; i < Math.min(WALLS, walls.size()); i++)
			{
				Insights.Wall w = walls.get(i);
				long share = w.tries == 0 ? 0 : Math.round(100.0 * w.wipes / w.tries);
				card.add(twoLine(w.encounter.getTitle(), w.wipes + (w.wipes == 1 ? " wipe" : " wipes") + " in " + w.tries + (w.tries == 1 ? " try" : " tries"),
					share + "%", "of tries", i == 0 ? Theme.BEHIND : Theme.TEXT));
			}
			stack.add(card);
		}

		int inBucket = done + wiped + left;
		String party = Format.party(Records.BUCKETS[bucket]);
		stack.add(new SectionHeader("Recent " + party + " runs", inBucket > HISTORY ? "latest " + HISTORY : null));
		// Each row keeps its own height: a run whose route takes two lines must not stretch the rest.
		Card history = new Card(new BorderLayout());
		history.setBorder(new EmptyBorder(2, 4, 2, 4));
		StackPanel historyRows = new StackPanel(0, 0);
		history.add(historyRows, BorderLayout.CENTER);
		int shown = 0;
		for (int i = runs.size() - 1; i >= 0 && shown < HISTORY; i--)
		{
			Run r = runs.get(i);
			if (Records.bucket(r.getTeamSize()) != bucket)
			{
				continue;
			}
			RunRow row = new RunRow(r, r == best, best == null ? -1 : best.getTicks(), view.now);
			row.setComponentPopupMenu(runMenu(r, bucket));
			historyRows.add(row);
			shown++;
		}
		if (shown == 0)
		{
			history.setBorder(new EmptyBorder(8, 10, 8, 10));
			historyRows.add(Ui.wrapped(runs.isEmpty() ? "Your runs appear here as you finish them."
				: "No " + party + " runs yet. Pick another party size above.", Theme.small(), Theme.TEXT_FAINT, WIDTH - 24));
		}
		stack.add(history);
		if (shown > 0)
		{
			stack.add(Ui.wrapped("Right-click a run to note your role, write a note, copy its splits or delete one the plugin timed wrongly.",
				Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
		}

		// Only this party size's runs count, and a sitting without one is not listed here.
		List<Sessions.Session> sittings = Sessions.of(runs, bucket);
		if (sittings.size() > 1)
		{
			stack.add(new SectionHeader("Sessions", sittings.size() > SESSIONS ? "latest " + SESSIONS : null));
			Card card = new Card(new GridLayout(0, 1, 0, 4));
			for (int i = sittings.size() - 1; i >= Math.max(0, sittings.size() - SESSIONS); i--)
			{
				Sessions.Session t = sittings.get(i);
				String pace = t.perHour() > 0 ? String.format(java.util.Locale.ENGLISH, ", %.1f an hour", t.perHour()) : "";
				// "Best of 1" says nothing a lone run's time does not; the line is left empty then.
				String sub = t.getBest() < 0 ? "no clear" : t.getBests() == 1 ? "new best" : t.getBests() > 1 ? t.getBests() + " new bests"
					: t.getClears() > 1 ? "best of " + t.getClears() : "";
				card.add(twoLine(Format.day(t.getStart()), t.getCounted().size() + (t.getCounted().size() == 1 ? " run" : " runs") + pace,
					t.getBest() < 0 ? "-" : Format.ticks(t.getBest()), sub,
					t.getBests() > 0 ? Theme.GOLD_BRIGHT : Theme.TEXT));
			}
			stack.add(card);
		}

		List<Insights.Mate> crew = Insights.crew(runs, bucket);
		if (!crew.isEmpty())
		{
			stack.add(new SectionHeader("Crew", crew.size() > CREW ? "top " + CREW : null));
			Card card = new Card(new GridLayout(0, 1, 0, 4));
			for (int i = 0; i < Math.min(CREW, crew.size()); i++)
			{
				Insights.Mate m = crew.get(i);
				card.add(twoLine(m.name, m.runs + (m.runs == 1 ? " run" : " runs") + ", " + m.clears + (m.clears == 1 ? " clear" : " clears"),
					m.best < 0 ? "-" : Format.ticks(m.best), m.best < 0 ? "no clear" : "best together", Theme.TEXT));
			}
			stack.add(card);
		}

		if (!runs.isEmpty())
		{
			JPanel buttons = new JPanel(new java.awt.FlowLayout(java.awt.FlowLayout.CENTER, 0, 0));
			buttons.setOpaque(false);
			buttons.add(new CodexButton("Save runs as a spreadsheet", false, onExport));
			stack.add(buttons);
		}
		setPage(recordsPage, stack);
	}

	private void rebuildSpoils()
	{
		StackPanel stack = new StackPanel(Theme.GUTTER, Theme.GUTTER);
		Archive a = view.archive;
		if (a == null)
		{
			stack.add(note("The archive is closed", "Log in to see your purples."));
			setPage(spoilsPage, stack);
			return;
		}
		// The crest already gives the KC; these say how the luck has gone.
		JPanel grid = new JPanel(new GridLayout(1, 3, 6, 0));
		grid.setOpaque(false);
		int clears = totalClears(a);
		int longest = a.longestDry();
		grid.add(new StatTile(String.valueOf(a.getDry()), "Dry", longest > a.getDry() ? "max " + longest : "clears",
			a.getDry() > 0 && a.getDry() >= longest && !a.getDrops().isEmpty() ? Theme.EMBER : Theme.TEXT));
		int purples = a.getDrops().size();
		String rate = purples == 0 ? "none yet" : clears >= purples ? "1 in " + Math.round(clears / (double) purples) : "rate unknown";
		grid.add(new StatTile(String.valueOf(purples), "Purples", rate, purples == 0 ? Theme.TEXT_FAINT : Theme.PURPLE));
		Map<String, Integer> counts = new HashMap<>();
		for (Drop d : a.getDrops())
		{
			counts.merge(d.getUnique(), 1, Integer::sum);
		}
		int owned = 0;
		for (String u : Spoils.ALL)
		{
			owned += counts.containsKey(u) ? 1 : 0;
		}
		grid.add(new StatTile(owned + "/" + Spoils.ALL.length, "Log", owned == Spoils.ALL.length ? "complete" : "uniques",
			owned == Spoils.ALL.length ? Theme.GOLD_BRIGHT : owned == 0 ? Theme.TEXT_FAINT : Theme.TEXT));
		stack.add(grid);

		stack.add(new SectionHeader("Uniques"));
		JPanel uniques = new JPanel(new GridLayout(0, 3, 6, 6));
		uniques.setOpaque(false);
		for (String u : Spoils.ALL)
		{
			uniques.add(new UniqueTile(u, counts.getOrDefault(u, 0)));
		}
		stack.add(uniques);

		stack.add(new SectionHeader("Purple log"));
		Card log = new Card(new GridLayout(0, 1, 0, 4));
		List<Drop> drops = a.getDrops();
		for (int i = drops.size() - 1; i >= 0 && i >= drops.size() - DROPS; i--)
		{
			Drop d = drops.get(i);
			// The unique's name gets the whole width; how long it took joins the line beneath it.
			String after = d.getDry() <= 1 ? "first clear" : "after " + d.getDry() + " clears";
			String when = (d.getKc() > 0 ? "KC " + Format.count(d.getKc()) + " \u00b7 " : "") + Format.shortDay(d.getAt()) + " \u00b7 " + after;
			JComponent line = dropLine(d.getUnique(), when);
			line.setComponentPopupMenu(menu("Remove this purple",
				"Remove the " + d.getUnique() + " from " + Format.day(d.getAt()) + "? Only do this if it never dropped; the clears it took go back onto your dry streak.",
				() -> onDeleteDrop.accept(d.getAt(), d.getUnique())));
			Ui.inheritPopup(line);
			log.add(line);
		}
		if (drops.isEmpty())
		{
			log.add(Ui.wrapped("No purples yet. Each one lands here with the completion it came on and how long it took.", Theme.small(), Theme.TEXT_FAINT, WIDTH - 24));
		}
		stack.add(log);
		if (!drops.isEmpty())
		{
			stack.add(Ui.wrapped("Right-click a purple that never dropped to remove it.", Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
		}
		setPage(spoilsPage, stack);
	}

	/** The sitting the last run belongs to: clears, pace, average, time between runs, and any best or purple. */
	private void session(StackPanel stack, Sessions.Session t)
	{
		stack.add(new SectionHeader("This session", "since " + Format.time(t.getStart())));
		JPanel grid = new JPanel(new GridLayout(2, 2, 6, 6));
		grid.setOpaque(false);
		grid.add(new StatTile(String.valueOf(t.getClears()), "Clears", t.getWipes() == 0 ? "no wipes" : t.getWipes() + (t.getWipes() == 1 ? " wipe" : " wipes"),
			Theme.TEXT));
		grid.add(new StatTile(t.perHour() > 0 ? String.format(java.util.Locale.ENGLISH, "%.1f", t.perHour()) : "-", "An hour", "clears", Theme.TEAL));
		grid.add(new StatTile(t.getAverage() < 0 ? "-" : Format.ticks(t.getAverage()), "Average",
			t.getBest() < 0 ? "no clear yet" : "best " + Format.ticks(t.getBest()), Theme.TEXT));
		grid.add(new StatTile(t.getBetween() < 0 ? "-" : Format.clock((int) (t.getBetween() / 600)), "Downtime", "between runs", Theme.TEXT));
		stack.add(grid);
		java.util.List<String> parts = new java.util.ArrayList<>();
		if (t.getBests() > 0)
		{
			parts.add(t.getBests() == 1 ? "a new personal best" : t.getBests() + " new personal bests");
		}
		if (t.getPurples() > 0)
		{
			parts.add(t.getPurples() == 1 ? "a purple" : t.getPurples() + " purples");
		}
		if (!parts.isEmpty())
		{
			stack.add(Ui.wrapped("This session: " + String.join(" and ", parts) + ".", Theme.small(),
				t.getPurples() > 0 ? Theme.PURPLE : Theme.GOLD, WIDTH - 16));
		}
		// The whole sitting as a picture, with every run of it.
		JPanel buttons = new JPanel(new java.awt.FlowLayout(java.awt.FlowLayout.CENTER, 6, 0));
		buttons.setOpaque(false);
		buttons.add(new CodexButton("Save session card", true, () -> saveSessionCard(t)));
		buttons.add(new CodexButton("Copy", false, () -> copySessionCard(t)));
		stack.add(buttons);
		if (cardNote != null && noteOnSession)
		{
			stack.add(Ui.wrapped(cardNote, Theme.small(), Theme.TEAL, WIDTH - 16));
		}
	}

	/**
	 * The goal for a party size: how far the best is from it, how often it has been beaten, and the
	 * rooms where a typical run loses most against the goal's share. With none set, a way to set one.
	 */
	private void goal(StackPanel stack, List<Run> runs, int bucket)
	{
		int ticks = view.archive.goal(bucket);
		Goal g = Goal.of(runs, bucket, ticks);
		String party = Format.party(Records.BUCKETS[bucket]);
		JPanel buttons = new JPanel(new java.awt.FlowLayout(java.awt.FlowLayout.LEFT, 6, 0));
		buttons.setOpaque(false);
		buttons.add(new CodexButton(g == null ? "Set a goal time" : "Change goal", g == null, () -> askGoal(bucket, ticks)));
		if (g == null)
		{
			Card card = new Card(new BorderLayout(0, 6));
			card.add(Ui.wrapped("Set the time you are working towards for " + party + " runs, and see how far off it is and which rooms hold you back. "
				+ "Choose Goal time under Compare against in the settings to race it room by room.", Theme.small(), Theme.TEXT_MUTED, WIDTH - 30),
				BorderLayout.CENTER);
			card.add(buttons, BorderLayout.SOUTH);
			stack.add(card);
			return;
		}
		buttons.add(new CodexButton("Clear", false, () -> onGoal.accept(bucket, 0)));
		stack.add(new SectionHeader("Goal", Format.clock(g.getGoal()) + " " + party));
		Card card = new Card(new BorderLayout(0, 6));
		card.accent(g.getBeaten() > 0 ? Theme.GREEN : Theme.GOLD);
		JPanel lines = new JPanel(new GridLayout(0, 1, 0, 3));
		lines.setOpaque(false);
		if (g.getBest() < 0)
		{
			lines.add(line("Your best", "no clear yet", Theme.TEXT_FAINT));
		}
		else if (g.gap() > 0)
		{
			lines.add(line("Your best", Format.ticks(g.getBest()), Theme.TEXT));
			lines.add(line("Still to find", Format.span(g.gap()), Theme.EMBER));
		}
		else
		{
			lines.add(line("Your best", Format.ticks(g.getBest()), Theme.GREEN));
			lines.add(line("Beaten", g.getBeaten() + (g.getBeaten() == 1 ? " time" : " times"), Theme.GREEN));
			if (g.getFirst() != null)
			{
				lines.add(line("First on", Format.shortDay(g.getFirst().getStartedAt()), Theme.TEXT));
			}
		}
		int shown = 0;
		for (Goal.Row r : g.getRows())
		{
			if (r.over() <= 0 || shown >= 3)
			{
				continue;
			}
			if (shown++ == 0)
			{
				lines.add(Ui.label("Where a typical run loses it", Theme.small(), Theme.GOLD_DIM));
			}
			JComponent l = line(Encounter.rowLabel(r.row), "+" + Format.span(r.over()), Theme.EMBER);
			l.setToolTipText("A typical room here takes " + Format.ticks(r.typical) + "; the goal allows " + Format.ticks(r.allowed) + ".");
			lines.add(l);
		}
		card.add(lines, BorderLayout.CENTER);
		card.add(buttons, BorderLayout.SOUTH);
		stack.add(card);
	}

	/** Asks for a goal time, and passes on what was typed once it reads as a time. */
	private void askGoal(int bucket, int current)
	{
		String party = Format.party(Records.BUCKETS[bucket]);
		Object answer = JOptionPane.showInputDialog(this, "Goal time for " + party + " runs, in minutes and seconds (for example 20:00):",
			"Goal time", JOptionPane.PLAIN_MESSAGE, null, null, current > 0 ? Format.clock(current) : "");
		if (answer == null)
		{
			return;
		}
		int ticks = Goal.parse(answer.toString());
		if (ticks <= 0)
		{
			JOptionPane.showMessageDialog(this, "\"" + answer + "\" is not a time. Write it like 20:00 or 19:42.6.", "Goal time",
				JOptionPane.WARNING_MESSAGE);
			return;
		}
		onGoal.accept(bucket, ticks);
	}

	/** Each row's best room with a bar for what a typical run lately gives away, the worst row lit. */
	private static JComponent rooms(List<Run> runs, int bucket)
	{
		Map<Integer, Insights.RowStat> stats = new HashMap<>();
		int scale = 0;
		int worst = -1;
		for (Insights.RowStat r : Insights.rows(runs, bucket))
		{
			stats.put(r.row, r);
			if (r.loss() > scale)
			{
				scale = r.loss();
				worst = r.row;
			}
		}
		Card card = new Card(new BorderLayout());
		JPanel lines = new JPanel();
		lines.setOpaque(false);
		lines.setLayout(new javax.swing.BoxLayout(lines, javax.swing.BoxLayout.Y_AXIS));
		for (int row = 0; row < Encounter.ROWS; row++)
		{
			Insights.RowStat stat = stats.get(row);
			if (row > 0)
			{
				lines.add(javax.swing.Box.createVerticalStrut(5));
			}
			lines.add(new RoomLine(Encounter.rowLabel(row), Records.bestRoom(runs, bucket, row), stat == null ? -1 : stat.typical,
				scale, row == worst && scale > 0));
		}
		card.add(lines, BorderLayout.CENTER);
		return card;
	}

	/** Both doors of a row, one line each with its typical room, and which is quicker for you. */
	private static JComponent doorLine(Insights.DoorStat[] pair)
	{
		Insights.DoorStat a = pair[0];
		Insights.DoorStat b = pair[1];
		int gap = a.typical - b.typical;
		Insights.DoorStat quick = gap > 0 ? b : a;
		JPanel block = new JPanel(new GridLayout(0, 1, 0, 1));
		block.setOpaque(false);
		for (Insights.DoorStat d : pair)
		{
			JPanel line = new JPanel(new BorderLayout(6, 0));
			line.setOpaque(false);
			line.add(Ui.label(d.encounter.getTitle(), Theme.small(), Theme.TEXT_MUTED), BorderLayout.CENTER);
			JLabel time = Ui.label(d.runs + "x  " + Format.ticks(d.typical), Theme.small(),
				d == quick && gap != 0 ? Theme.GREEN : Theme.TEXT);
			line.add(time, BorderLayout.EAST);
			block.add(line);
		}
		block.add(Ui.label(gap == 0 ? "Level either way" : quick.encounter.getShortName() + " is " + Format.span(gap) + " quicker for you",
			Theme.small(), gap == 0 ? Theme.TEXT_FAINT : Theme.GOLD));
		block.setToolTipText("Typical room through each door in this party size, from " + a.runs + " and " + b.runs + " runs.");
		return block;
	}

	private static JComponent twoLine(String title, String sub, String value, String valueSub, Color color)
	{
		return twoLine(title, Theme.body(), sub, value, valueSub, color);
	}

	private static JComponent twoLine(String title, java.awt.Font titleFont, String sub, String value, String valueSub, Color color)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(false);
		JPanel left = new JPanel(new GridLayout(2, 1));
		left.setOpaque(false);
		left.add(Ui.label(title, titleFont, Theme.TEXT));
		left.add(Ui.label(sub, Theme.small(), Theme.TEXT_FAINT));
		row.add(left, BorderLayout.CENTER);
		JPanel right = new JPanel(new GridLayout(2, 1));
		right.setOpaque(false);
		JLabel v = Ui.label(value, Theme.body(), color);
		v.setHorizontalAlignment(javax.swing.SwingConstants.RIGHT);
		JLabel vs = Ui.label(valueSub, Theme.small(), Theme.TEXT_FAINT);
		vs.setHorizontalAlignment(javax.swing.SwingConstants.RIGHT);
		right.add(v);
		right.add(vs);
		row.add(right, BorderLayout.EAST);
		return row;
	}

	/** Everything a run can have done to it: a role, a note, its splits to share, or deleting it. */
	private JPopupMenu runMenu(Run r, int bucket)
	{
		JPopupMenu popup = new JPopupMenu();
		JMenu role = new JMenu("Role");
		for (String name : Run.ROLES)
		{
			JCheckBoxMenuItem item = new JCheckBoxMenuItem(name, name.equals(r.getRole()));
			item.addActionListener(e -> onRole.accept(r.getStartedAt(), name.equals(r.getRole()) ? null : name));
			role.add(item);
		}
		popup.add(role);
		JMenuItem note = new JMenuItem(r.getNote() == null ? "Write a note..." : "Edit the note...");
		note.addActionListener(e ->
		{
			Object answer = JOptionPane.showInputDialog(this, "A note on this run, up to " + Run.NOTE_LENGTH + " characters:",
				"Note", JOptionPane.PLAIN_MESSAGE, null, null, r.getNote() == null ? "" : r.getNote());
			if (answer != null)
			{
				onNote.accept(r.getStartedAt(), answer.toString());
			}
		});
		popup.add(note);
		JMenuItem copy = new JMenuItem("Copy splits");
		copy.addActionListener(e ->
		{
			Comparison pb = Comparison.of(runs(), bucket, Comparison.Mode.PERSONAL_BEST, r);
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(Share.splits(r, pb)), null);
		});
		popup.add(copy);
		JMenuItem save = new JMenuItem("Save run card...");
		save.addActionListener(e -> saveCard(r));
		popup.add(save);
		JMenuItem picture = new JMenuItem("Copy run card");
		picture.addActionListener(e -> copyCard(r));
		popup.add(picture);
		popup.addSeparator();
		JPopupMenu delete = menu("Delete this run",
			"Delete the " + describe(r) + " from " + Format.day(r.getStartedAt()) + " at " + Format.time(r.getStartedAt())
				+ "? Its times leave your records for good.",
			() -> onDeleteRun.accept(r.getStartedAt()));
		popup.add(delete.getComponent(0));
		return popup;
	}

	private static int totalClears(Archive a)
	{
		int n = 0;
		for (int b = 0; b < Records.BUCKETS.length; b++)
		{
			n += a.clears(b);
		}
		return n;
	}

	private static String describe(Run r)
	{
		String party = Format.party(Records.BUCKETS[Records.bucket(r.getTeamSize())]);
		if (r.isCompleted())
		{
			return Format.ticks(r.getTicks()) + " " + party + " clear";
		}
		return party + (r.getOutcome() == Outcome.WIPED ? " wipe" : " run");
	}

	/** A right-click menu with one action, asked about first since it cannot be undone. */
	private JPopupMenu menu(String label, String question, Runnable action)
	{
		JPopupMenu popup = new JPopupMenu();
		JMenuItem item = new JMenuItem(label);
		item.addActionListener(e ->
		{
			int answer = JOptionPane.showConfirmDialog(this, Ui.wrapped(question, Theme.body(), null, 240).getText(),
				label, JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE);
			if (answer == JOptionPane.OK_OPTION)
			{
				action.run();
			}
		});
		popup.add(item);
		return popup;
	}

	private static JComponent line(String label, String value, Color color)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(false);
		row.add(Ui.label(label, Theme.small(), Theme.TEXT_MUTED), BorderLayout.CENTER);
		row.add(Ui.label(value, Theme.body(), color), BorderLayout.EAST);
		return row;
	}

	private static JComponent dropLine(String unique, String when)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(false);
		Color tone = Spoils.isMegarare(unique) ? Theme.MEGARARE : Theme.PURPLE;
		JPanel left = new JPanel(new GridLayout(2, 1));
		left.setOpaque(false);
		left.add(Ui.label(unique, Theme.body(), tone));
		left.add(Ui.label(when, Theme.small(), Theme.TEXT_FAINT));
		row.add(left, BorderLayout.CENTER);
		row.setToolTipText(unique + ", " + when);
		return row;
	}

	/** What a run's times rest on when a boss was guessed or missed, and how to put a wrong run right. */
	private static JComponent doubts(List<String> lines)
	{
		Card card = new Card(new BorderLayout(0, 4));
		card.accent(Theme.EMBER);
		card.add(Ui.label("Check this run", Theme.body(), Theme.EMBER), BorderLayout.NORTH);
		StackPanel body = new StackPanel(3, 0);
		for (String line : lines)
		{
			body.add(Ui.wrapped(line, Theme.small(), Theme.TEXT_MUTED, WIDTH - 30));
		}
		body.add(Ui.wrapped("If a time is wrong, right-click the run under Records to delete it.", Theme.small(), Theme.TEXT_FAINT, WIDTH - 30));
		card.add(body, BorderLayout.CENTER);
		return card;
	}

	private static JComponent note(String title, String body)
	{
		Card card = new Card(new BorderLayout(0, 6));
		card.accent(Theme.GOLD);
		card.add(Ui.label(title, Theme.title(), Theme.GOLD), BorderLayout.NORTH);
		card.add(Ui.wrapped(body, Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		return card;
	}

	private static void setPage(JScrollPane page, StackPanel stack)
	{
		int scroll = page.getVerticalScrollBar().getValue();
		page.setViewportView(stack);
		page.getVerticalScrollBar().setValue(scroll);
		page.revalidate();
		page.repaint();
	}
}

package com.codex.archive.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.archive.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A gilt-edged button; the primary style is filled, the quiet style is just an outline. */
public class CodexButton extends JComponent
{
	private final String text;
	private final boolean primary;
	private boolean hover;
	private boolean pressed;

	public CodexButton(String text, boolean primary, Runnable action)
	{
		this.text = text;
		this.primary = primary;
		setFont(Theme.small());
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + 20, 22);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				pressed = false;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				pressed = true;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				boolean fire = pressed && contains(e.getPoint());
				pressed = false;
				repaint();
				if (fire)
				{
					action.run();
				}
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		int dy = pressed ? 1 : 0;
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f + dy, w - 1, h - 2, 8, 8);
		Color text;
		if (primary)
		{
			Color top = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
			g.setPaint(new GradientPaint(0, 0, top, 0, h, Theme.GOLD_DIM));
			g.fill(shape);
			text = Theme.INK_DEEP;
		}
		else
		{
			g.setColor(hover ? Theme.alpha(Theme.GOLD, 40) : Theme.alpha(Theme.GOLD, 14));
			g.fill(shape);
			text = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
		}
		g.setColor(Theme.alpha(Theme.GOLD, primary ? 220 : 140));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(text);
		g.drawString(this.text, (w - fm.stringWidth(this.text)) / 2, (h + fm.getAscent()) / 2 - 2 + dy);
		g.dispose();
	}
}

package com.codex.archive.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/**
 * The crest at the top of the panel: the medallion, one large gilt figure (the run's clock while
 * a run is going, the personal best otherwise) and three small figures under it.
 */
public class Crest extends JComponent
{
	private static final int HEIGHT = 104;

	private String heading = "FRACTURED ARCHIVE";
	private String figure = "-";
	private String unit;
	private boolean live;
	private String status = "Log in to open the archive";
	private String[] labels = new String[0];
	private String[] values = new String[0];
	private Color[] colors = new Color[0];

	public Crest()
	{
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setMinimumSize(new Dimension(10, HEIGHT));
	}

	/**
	 * @param live draws the figure in the arcane teal, for a clock that is running
	 * @param status a line in place of the three figures, or null to show them
	 */
	public void update(String heading, String figure, String unit, boolean live, String status,
		String[] labels, String[] values, Color[] colors)
	{
		this.heading = heading;
		this.figure = figure;
		this.unit = unit;
		this.live = live;
		this.status = status;
		this.labels = labels == null ? new String[0] : labels;
		this.values = values == null ? new String[0] : values;
		this.colors = colors == null ? new Color[0] : colors;
		repaint();
	}

	/**
	 * Draws text at twice the size of the game's bold font by doubling every pixel, the way the
	 * game itself draws large numbers, so the figures stay crisp instead of being re-rasterised.
	 *
	 * @return the width drawn
	 */
	private static int paintLarge(Graphics2D g, String text, int x, int y, boolean live)
	{
		Font font = Theme.title();
		FontMetrics fm = g.getFontMetrics(font);
		int w = Math.max(1, fm.stringWidth(text) + 1);
		int h = fm.getHeight() + 1;
		BufferedImage small = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D sg = small.createGraphics();
		sg.setFont(font);
		sg.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		int base = fm.getAscent();
		sg.setColor(Color.BLACK);
		sg.drawString(text, 1, base + 1);
		sg.setPaint(live
			? new GradientPaint(0, base - fm.getAscent() + 3, Theme.mix(Theme.TEAL, Theme.TEXT, 0.5), 0, base, Theme.TEAL)
			: new GradientPaint(0, base - fm.getAscent() + 3, Theme.GOLD_BRIGHT, 0, base, Theme.GOLD));
		sg.drawString(text, 0, base);
		sg.dispose();
		Graphics2D lg = (Graphics2D) g.create();
		lg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		lg.drawImage(small, x, y - 2 * fm.getAscent() + 22, w * 2, h * 2, null);
		lg.dispose();
		return w * 2;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.GOLD_DIM, 0.22), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);

		// The medallion: a gilt ring with the mark inside, lit from above.
		int mx = 10;
		int my = 14;
		int md = 54;
		g.setPaint(new RadialGradientPaint(mx + md / 2f, my + md / 3f, md * 0.7f, new float[]{0, 1},
			new Color[]{Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35), Theme.INK_DEEP}));
		g.fill(new Ellipse2D.Float(mx, my, md, md));
		g.setStroke(new BasicStroke(2f));
		g.setPaint(new GradientPaint(mx, my, Theme.GOLD_BRIGHT, mx, my + md, Theme.GOLD_DIM));
		g.draw(new Ellipse2D.Float(mx + 1, my + 1, md - 2, md - 2));
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD, 70));
		g.draw(new Ellipse2D.Float(mx + 5, my + 5, md - 10, md - 10));
		Sigil.paint(g, mx + 11, my + 11, md - 22);

		int tx = mx + md + 12;
		int room = w - tx - 8;
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(Ui.clip(heading, small, room), tx, 22);

		int top = 27;
		int figureW;
		if (figure == null || figure.isEmpty())
		{
			figureW = 0;
		}
		else if (figure.equals("-"))
		{
			// Nothing to show yet: a quiet line in place of a lone, broken-looking dash.
			g.setFont(Theme.title());
			String none = "No clear yet";
			Ui.shadowed(g, Ui.clip(none, g.getFontMetrics(), room), tx, top + 18, Theme.GOLD_DIM);
			figureW = g.getFontMetrics().stringWidth(none);
			g.setFont(Theme.small());
		}
		else
		{
			figureW = paintLarge(g, figure, tx, top, live);
		}
		if (unit != null)
		{
			g.setFont(Theme.small());
			g.setColor(live ? Theme.alpha(Theme.TEAL, 170) : Theme.GOLD_DIM);
			g.drawString(Ui.clip(unit, small, Math.max(0, room - figureW - 3)), tx + figureW + 3, top + 18);
		}
		int fy = top + 26;
		int cy = fy + 24;
		g.setFont(Theme.small());
		if (status != null)
		{
			g.setColor(Theme.mix(Theme.TEXT_MUTED, Theme.GOLD, 0.3));
			g.drawString(Ui.clip(status, small, room), tx, cy);
		}
		else if (labels.length > 0)
		{
			// Each column as wide as its words need, with what is left shared out evenly.
			int[] widths = new int[labels.length];
			int need = 0;
			for (int i = 0; i < labels.length; i++)
			{
				String value = i < values.length && values[i] != null ? values[i] : "-";
				widths[i] = Math.max(small.stringWidth(labels[i]), small.stringWidth(value)) + 8;
				need += widths[i];
			}
			int spare = (room - need) / labels.length;
			int x = tx;
			for (int i = 0; i < labels.length; i++)
			{
				int cw = need > room ? room * widths[i] / need : widths[i] + spare;
				g.setColor(Theme.TEXT_FAINT);
				g.drawString(Ui.clip(labels[i], small, cw - 4), x, cy - 11);
				String value = i < values.length && values[i] != null ? values[i] : "-";
				Color color = i < colors.length && colors[i] != null ? colors[i] : Theme.TEXT;
				Ui.shadowed(g, Ui.clip(value, small, cw - 4), x, cy + 1, color);
				x += cw;
			}
		}

		// The gilt rule under the crest, with a diamond at its middle.
		int y = h - 2;
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, y, w, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, y - 3);
		diamond.lineTo(w / 2f + 3, y);
		diamond.lineTo(w / 2f, y + 3);
		diamond.lineTo(w / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
	}
}

package com.codex.archive.ui;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

/** How numbers and times are written in the panel. */
public final class Format
{
	private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("EEE d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter SHORT = DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm", Locale.ENGLISH);

	private Format()
	{
	}

	/**
	 * Game ticks as a raid time, to the tenth of a second the way the game's own raid timers
	 * write it: "0:36.0", "24:31.8", "1:02:07.2". A tick is 0.6 seconds, so tenths are exact.
	 */
	public static String ticks(int ticks)
	{
		if (ticks < 0)
		{
			return "-";
		}
		int tenths = ticks * 6;
		int seconds = tenths / 10;
		int tenth = tenths % 10;
		int h = seconds / 3600;
		int m = seconds / 60 % 60;
		int s = seconds % 60;
		if (h > 0)
		{
			return String.format(Locale.ENGLISH, "%d:%02d:%02d.%d", h, m, s, tenth);
		}
		return String.format(Locale.ENGLISH, "%d:%02d.%d", m, s, tenth);
	}

	/** The same without tenths, for the big crest figure while a run is going: "12:04". */
	public static String clock(int ticks)
	{
		int seconds = Math.max(0, ticks) * 6 / 10;
		int h = seconds / 3600;
		if (h > 0)
		{
			return String.format(Locale.ENGLISH, "%d:%02d:%02d", h, seconds / 60 % 60, seconds % 60);
		}
		return String.format(Locale.ENGLISH, "%d:%02d", seconds / 60, seconds % 60);
	}

	/** A time against a best: "-4.2" ahead, "+1:12.0" behind, "0.0" level. Under a minute it drops the minutes. */
	public static String delta(int ticks)
	{
		int abs = Math.abs(ticks);
		String t = abs < 100 ? String.format(Locale.ENGLISH, "%d.%d", abs * 6 / 10, abs * 6 % 10) : ticks(abs);
		return ticks < 0 ? "-" + t : ticks > 0 ? "+" + t : t;
	}

	/** A gap in time without a sign: "4.2s" under a minute, "1:12.0" above. */
	public static String span(int ticks)
	{
		int abs = Math.abs(ticks);
		return abs < 100 ? String.format(Locale.ENGLISH, "%d.%ds", abs * 6 / 10, abs * 6 % 10) : ticks(abs);
	}

	/** A delta in words, for the chat box: "4.2s ahead of your best", "1:12.0 behind your best". */
	public static String versus(int ticks)
	{
		return versus(ticks, "your best");
	}

	/** The same against any mark: "4.2s ahead of your best rooms". */
	public static String versus(int ticks, String mark)
	{
		if (ticks == 0)
		{
			return "level with " + mark;
		}
		return span(ticks) + (ticks < 0 ? " ahead of " : " behind ") + mark;
	}

	public static String count(long n)
	{
		return String.format(Locale.ENGLISH, "%,d", n);
	}

	/** "just now", "12m ago", "3h ago", "2d ago". */
	public static String ago(long ms)
	{
		long minutes = Math.max(0, ms) / 60_000;
		if (minutes < 1)
		{
			return "just now";
		}
		if (minutes < 60)
		{
			return minutes + "m ago";
		}
		if (minutes < 48 * 60)
		{
			return minutes / 60 + "h ago";
		}
		return minutes / (24 * 60) + "d ago";
	}

	/** "Thu 16 Oct". */
	public static String day(long epochMs)
	{
		return DAY.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "16 Oct". */
	public static String shortDay(long epochMs)
	{
		return SHORT.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}

	/** "2026-10-20", for a file name. */
	public static String fileDay(long epochMs)
	{
		return Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()).toLocalDate().toString();
	}

	/** "14:02". */
	public static String time(long epochMs)
	{
		return time(epochMs, ZoneId.systemDefault());
	}

	/** The clock time in a zone, so a card's times agree with its date. */
	public static String time(long epochMs, ZoneId zone)
	{
		return CLOCK.format(Instant.ofEpochMilli(epochMs).atZone(zone));
	}

	/** "1st", "2nd", "11th", "23rd". */
	public static String ordinal(int n)
	{
		int mod100 = n % 100;
		String suffix = mod100 >= 11 && mod100 <= 13 ? "th" : n % 10 == 1 ? "st" : n % 10 == 2 ? "nd" : n % 10 == 3 ? "rd" : "th";
		return n + suffix;
	}

	/** A party-size group as a word before a noun: "trio", "4-raider", "6+ raider". */
	public static String party(String bucket)
	{
		if (bucket.isEmpty() || !Character.isDigit(bucket.charAt(0)))
		{
			return bucket.toLowerCase(Locale.ENGLISH);
		}
		return bucket + (bucket.endsWith("+") ? " raider" : "-raider");
	}

	/** "trio clear", "4-raider clear". */
	public static String clear(String bucket)
	{
		return party(bucket) + " clear";
	}
}

package com.codex.archive.ui;

import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.Transferable;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.awt.image.BufferedImage;

/** Hands a card to the system clipboard as a picture. */
public final class ImageTransfer implements Transferable
{
	private final BufferedImage image;

	public ImageTransfer(BufferedImage image)
	{
		this.image = image;
	}

	@Override
	public DataFlavor[] getTransferDataFlavors()
	{
		return new DataFlavor[]{DataFlavor.imageFlavor};
	}

	@Override
	public boolean isDataFlavorSupported(DataFlavor flavor)
	{
		return DataFlavor.imageFlavor.equals(flavor);
	}

	@Override
	public Object getTransferData(DataFlavor flavor) throws UnsupportedFlavorException
	{
		if (!isDataFlavorSupported(flavor))
		{
			throw new UnsupportedFlavorException(flavor);
		}
		return image;
	}
}

package com.codex.archive.ui;

import com.codex.archive.core.Supply;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.swing.JComponent;

/**
 * The pack check: one bar per kind of supply, filled as far as the pack meets what the player set
 * out to bring. Nothing can be banked once the archive's doors close, so short bars burn ember.
 * It also shows what a run used, with the same bars and no targets.
 */
public class PackCard extends JComponent
{
	private static final int ROW = 22;
	private static final int TOP = 26;

	private final String title;
	private Map<Supply, Integer> have;
	private Map<Supply, Integer> want;

	/** @param title the card's heading */
	public PackCard(String title)
	{
		this.title = title;
		setOpaque(false);
		int h = TOP + ROW * Supply.values().length + 6;
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
	}

	/** @param want the targets, or null to show plain counts */
	public void update(Map<Supply, Integer> have, Map<Supply, Integer> want)
	{
		this.have = have;
		this.want = want;
		int h = TOP + ROW * rows().size() + 6;
		if (getPreferredSize().height != h)
		{
			setPreferredSize(new Dimension(10, h));
			setMinimumSize(new Dimension(10, h));
			revalidate();
		}
		repaint();
	}

	/** The supplies to draw: against targets only those with one set, otherwise only those used. */
	private List<Supply> rows()
	{
		List<Supply> out = new ArrayList<>();
		for (Supply s : Supply.values())
		{
			if (want != null ? count(want, s) > 0 : count(have, s) > 0)
			{
				out.add(s);
			}
		}
		return out;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		boolean ready = true;
		if (want != null)
		{
			for (Supply s : Supply.values())
			{
				ready &= count(have, s) >= count(want, s);
			}
		}
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(0, 0, Theme.CARD_TOP, 0, h, Theme.CARD));
		g.fill(shape);
		g.setColor(want == null ? Theme.STROKE_SOFT : ready ? Theme.alpha(Theme.GREEN, 110) : Theme.alpha(Theme.EMBER, 140));
		g.draw(shape);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.GOLD);
		g.drawString(title.toUpperCase(), 10, 16);
		if (want != null)
		{
			String verdict = ready ? "Ready" : "Short";
			g.setColor(ready ? Theme.GREEN : Theme.EMBER);
			g.drawString(verdict, w - 10 - small.stringWidth(verdict), 16);
		}

		// One column for the figures, as wide as the widest, so every bar ends at the same place.
		int column = 0;
		for (Supply s : rows())
		{
			column = Math.max(column, small.stringWidth(figure(s)));
		}
		int y = TOP;
		for (Supply s : rows())
		{
			int n = count(have, s);
			int target = want == null ? 0 : count(want, s);
			g.setColor(Theme.TEXT_MUTED);
			g.drawString(s.getTitle(), 10, y + small.getAscent() + 1);
			String figure = figure(s);
			Color figureColor = want == null ? Theme.TEXT : target == 0 || n >= target ? Theme.TEXT : Theme.EMBER;
			Ui.shadowed(g, figure, w - 10 - small.stringWidth(figure), y + small.getAscent() + 1, figureColor);

			int bx = 70;
			int bw = w - bx - 10 - column - 8;
			if (bw > 12)
			{
				int by = y + 4;
				RoundRectangle2D track = new RoundRectangle2D.Float(bx, by, bw, 6, 6, 6);
				g.setColor(Theme.INK_DEEP);
				g.fill(track);
				double fill = want == null ? Math.min(1, n / (double) Math.max(1, maxOf(have))) : target == 0 ? 1 : Math.min(1, n / (double) target);
				if (fill > 0)
				{
					Color c = want == null ? Theme.GOLD : fill >= 1 ? Theme.GREEN : Theme.progressColor(fill * 0.5);
					g.setPaint(new GradientPaint(bx, 0, Theme.mix(c, Theme.INK, 0.25), bx + bw, 0, c));
					g.fill(new RoundRectangle2D.Float(bx, by, (float) (bw * fill), 6, 6, 6));
				}
				g.setColor(Theme.STROKE_SOFT);
				g.draw(track);
			}
			y += ROW;
		}
		g.dispose();
	}

	private String figure(Supply s)
	{
		int n = count(have, s);
		return want == null ? n + " " + s.getUnit() : n + " / " + count(want, s);
	}

	private static int count(Map<Supply, Integer> map, Supply s)
	{
		return map == null ? 0 : map.getOrDefault(s, 0);
	}

	private static int maxOf(Map<Supply, Integer> map)
	{
		int max = 0;
		if (map != null)
		{
			for (int v : map.values())
			{
				max = Math.max(max, v);
			}
		}
		return max;
	}
}

package com.codex.archive.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/**
 * One row of the raid on the records page: its best room, and under it a bar for what a
 * typical run lately gives away against that best. The row losing most is lit in ember.
 */
class RoomLine extends JComponent
{
	private final String label;
	private final int best;
	private final int typical;
	/** The biggest loss on the page, which fills a bar. */
	private final int scale;
	private final boolean worst;

	RoomLine(String label, int best, int typical, int scale, boolean worst)
	{
		this.label = label;
		this.best = best;
		this.typical = typical;
		this.scale = scale;
		this.worst = worst;
		setOpaque(false);
		setPreferredSize(new Dimension(10, typical >= 0 ? 30 : 18));
		if (typical >= 0)
		{
			setToolTipText("Best " + Format.ticks(best) + ", typical lately " + Format.ticks(typical) + ".");
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		int base = body.getAscent();
		String time = best < 0 ? "-" : Format.ticks(best);
		g.setColor(worst ? Theme.mix(Theme.EMBER, Theme.TEXT_MUTED, 0.3) : Theme.TEXT_MUTED);
		g.drawString(Ui.clip(label, small, w - body.stringWidth(time) - 10), 0, base);
		g.setFont(Theme.body());
		Ui.shadowed(g, time, w - body.stringWidth(time), base, best < 0 ? Theme.TEXT_FAINT : Theme.TEXT);
		if (typical < 0 || best < 0)
		{
			g.dispose();
			return;
		}
		int loss = Math.max(0, typical - best);
		g.setFont(Theme.small());
		String note = loss == 0 ? "typical is your best" : "typical " + Format.delta(loss);
		int nw = small.stringWidth(note);
		int barY = base + 7;
		int barW = Math.max(10, w - nw - 8);
		RoundRectangle2D track = new RoundRectangle2D.Float(0, barY, barW, 5, 5, 5);
		g.setColor(Theme.INK_DEEP);
		g.fill(track);
		Color fill = worst ? Theme.EMBER : Theme.mix(Theme.GOLD_DIM, Theme.GOLD, 0.5);
		if (scale > 0 && loss > 0)
		{
			float fw = Math.max(5, barW * Math.min(1f, loss / (float) scale));
			g.setColor(Theme.alpha(fill, 210));
			g.fill(new RoundRectangle2D.Float(0, barY, fw, 5, 5, 5));
		}
		g.setColor(Theme.STROKE_SOFT);
		g.draw(track);
		g.setColor(worst ? Theme.EMBER : Theme.TEXT_FAINT);
		g.drawString(note, w - nw, barY + 5);
		g.dispose();
	}
}

package com.codex.archive.ui;

import com.codex.archive.core.Encounter;
import com.codex.archive.core.Outcome;
import com.codex.archive.core.Records;
import com.codex.archive.core.Run;
import com.codex.archive.core.Split;
import com.codex.archive.core.Standing;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import java.util.Random;

/**
 * The run card: one run of the Fractured Archive on a gilt page, to save or paste into a chat.
 * The time large, how it stood against the best before it, and the five bosses down a thread,
 * each with its room time, the run's time at its fall and the gap to the best run there, and a
 * gold mark on every room that was the quickest yet. Drawn at twice the panel's scale so the
 * game's pixel fonts stay crisp.
 */
public final class RunCard
{
	static final int WIDTH = 360;
	static final int SCALE = 2;
	private static final int PAD = 20;
	private static final int ROW = 40;
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("EEEE d MMMM yyyy", Locale.ENGLISH);

	private RunCard()
	{
	}

	/** @param player the name to put on the card, or null to leave it off */
	public static BufferedImage render(Standing st, String player, ZoneId zone)
	{
		return render(st, player, true, zone);
	}

	/**
	 * @param player the name to put on the card, or null to leave it off
	 * @param names false to leave every name off, the player's and the party's, for a card shared without them
	 */
	public static BufferedImage render(Standing st, String player, boolean names, ZoneId zone)
	{
		if (!names)
		{
			player = null;
		}
		BufferedImage scratch = new BufferedImage(WIDTH, 1200, BufferedImage.TYPE_INT_ARGB);
		Graphics2D sg = scratch.createGraphics();
		int height = content(sg, st, player, names, zone);
		sg.dispose();

		BufferedImage image = new BufferedImage(WIDTH * SCALE, height * SCALE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.scale(SCALE, SCALE);
		Theme.smooth(g);
		frame(g, height, st.isNewBest());
		content(g, st, player, names, zone);
		g.dispose();
		return image;
	}

	private static int content(Graphics2D g, Standing st, String player, boolean names, ZoneId zone)
	{
		Theme.smooth(g);
		Run run = st.getRun();
		int x = PAD;
		int w = WIDTH - PAD * 2;
		int y = PAD + 4;

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		Sigil.paint(g, x, y - 2, 14);
		g.setColor(Theme.GOLD);
		g.drawString("CODEX ARCHIVE SPLITS", x + 19, y + small.getAscent() - 1);
		String place = "FRACTURED ARCHIVE";
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(place, x + w - small.stringWidth(place), y + small.getAscent() - 1);
		y += small.getHeight() + 10;

		// The time itself, large; a wipe's in ember, since it is where the run stopped.
		boolean cleared = run.getOutcome() == Outcome.COMPLETED;
		Font huge = Theme.title().deriveFont(Theme.title().getSize2D() * 3.5f);
		g.setFont(huge);
		FontMetrics hm = g.getFontMetrics();
		String time = Format.ticks(run.getTicks());
		// Set glyph by glyph: the pixel font gives a colon and a point a digit's spacing, which at
		// this size opens a gap ("6 :54.0"); they sit close to their figures instead.
		Tight.Layout set = Tight.layout(g, time);
		float tx = x + (w - set.width) / 2f;
		int base = y + hm.getAscent() - 10;
		g.setColor(Color.BLACK);
		set.draw(g, tx + 2, base + 2);
		Color top = cleared ? Theme.GOLD_BRIGHT : Theme.mix(Theme.EMBER, Theme.TEXT, 0.25);
		Color bottom = cleared ? Theme.GOLD_DIM : Theme.mix(Theme.EMBER, Theme.INK, 0.35);
		g.setPaint(new GradientPaint(0, base - hm.getAscent() + 12, top, 0, base, bottom));
		set.draw(g, tx, base);
		y = base + 10;

		// The ribbon: what the run was, in a word or two.
		ribbon(g, verdict(st), ribbonColor(st), x + w / 2, y);
		y += 24;

		g.setFont(Theme.small());
		String party = Records.BUCKETS[Records.bucket(run.getTeamSize())];
		StringBuilder line = new StringBuilder(party);
		if (run.getKc() > 0)
		{
			line.append(" · KC ").append(Format.count(run.getKc()));
		}
		line.append(" · ").append(DATE.format(Instant.ofEpochMilli(run.getStartedAt()).atZone(zone)));
		centered(g, Ui.clip(line.toString(), small, w), x, w, y + small.getAscent(), Theme.TEXT_MUTED);
		y += small.getHeight() + 2;
		if (player != null && !player.isEmpty())
		{
			g.setFont(Theme.title());
			FontMetrics bold = g.getFontMetrics();
			centered(g, Ui.clip(player, bold, w), x, w, y + bold.getAscent(), Theme.TEXT);
			y += bold.getHeight();
		}
		y += 6;
		rule(g, x, y, w);
		y += 12;

		// The thread of bosses.
		int nodeX = x + 10;
		int rows = 0;
		for (int row = 0; row < Encounter.ROWS; row++)
		{
			rows += show(run, row) ? 1 : 0;
		}
		int shown = 0;
		for (int row = 0; row < Encounter.ROWS; row++)
		{
			if (!show(run, row))
			{
				continue;
			}
			Split s = run.split(row);
			boolean done = s != null && s.isDone();
			boolean gold = done && st.isGold(row);
			int ny = y + 9;
			g.setStroke(new BasicStroke(1.2f));
			g.setColor(Theme.alpha(Theme.GOLD_DIM, 170));
			if (shown > 0)
			{
				g.drawLine(nodeX, y - 4, nodeX, ny);
			}
			if (shown < rows - 1)
			{
				g.drawLine(nodeX, ny, nodeX, y + ROW - 4);
			}
			node(g, nodeX, ny, gold, done);

			String name = s == null || s.getEncounter() == null ? Encounter.rowLabel(row) : s.getEncounter().getTitle();
			int nx = nodeX + 14;
			g.setFont(Theme.title());
			FontMetrics bold = g.getFontMetrics();
			int right = x + w;
			String end = done ? Format.ticks(s.getEndTick()) : run.getOutcome() == Outcome.WIPED && row == run.reached() ? "wiped" : "not timed";
			g.setFont(Theme.body());
			FontMetrics body = g.getFontMetrics();
			int ew = body.stringWidth(end);
			Ui.shadowed(g, end, right - ew, ny + body.getAscent() / 2 - 1, done ? Theme.TEXT : Theme.EMBER);
			g.setFont(Theme.title());
			Ui.shadowed(g, Ui.clip(name, bold, right - ew - 10 - nx), nx, ny + bold.getAscent() / 2 - 1, gold ? Theme.GOLD_BRIGHT : Theme.TEXT);

			g.setFont(Theme.small());
			if (done)
			{
				String room = "room " + Format.ticks(s.roomTicks(0));
				g.setColor(Theme.TEXT_MUTED);
				int sy = ny + body.getAscent() / 2 + small.getHeight() + 1;
				g.drawString(room, nx, sy);
				if (gold)
				{
					int gx = nx + small.stringWidth(room) + 6;
					goldTag(g, gx, sy - small.getAscent() + 1, "GOLD");
				}
				Integer delta = st.delta(row);
				if (delta != null)
				{
					SplitTable.paintPill(g, Format.delta(delta), Theme.delta(delta), right, sy - small.getAscent() - 1);
				}
			}
			y += ROW;
			shown++;
		}
		y += 2;
		rule(g, x, y, w);
		y += 10;

		// Three figures beneath: golds, deaths, and its place among the clears.
		int tileW = (w - 12) / 3;
		int tileH = 50;
		int compared = st.getComparedRooms();
		StatTile.paint(g, compared == 0 ? "-" : st.getGoldCount() + " of " + compared, "Golds", compared == 0 ? "first time" : "quickest yet",
			Theme.GOLD, x, y, tileW, tileH);
		StatTile.paint(g, String.valueOf(run.getDeaths()), "Deaths", run.getDeaths() == 0 ? "deathless" : "in the run",
			run.getDeaths() == 0 ? Theme.GREEN : Theme.EMBER, x + tileW + 6, y, tileW, tileH);
		if (st.getClearNumber() > 0)
		{
			StatTile.paint(g, Format.ordinal(st.getClearNumber()), "Clear", Format.clear(party),
				Theme.TEAL, x + (tileW + 6) * 2, y, w - (tileW + 6) * 2, tileH);
		}
		else
		{
			// A run that did not clear: how far down the archive it got.
			StatTile.paint(g, Math.min(run.reached(), Encounter.ROWS) + " of " + Encounter.ROWS, "Bosses", "down",
				Theme.EMBER, x + (tileW + 6) * 2, y, w - (tileW + 6) * 2, tileH);
		}
		y += tileH + 10;

		if (names && !run.getCrew().isEmpty())
		{
			g.setFont(Theme.small());
			String with = "With " + crew(run);
			centered(g, Ui.clip(with, small, w), x, w, y + small.getAscent(), Theme.TEXT_MUTED);
			y += small.getHeight() + 6;
		}

		rule(g, x, y, w);
		y += 8;
		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_FAINT);
		g.drawString("Codex Archive Splits for RuneLite", x, y + small.getAscent());
		String route = run.route();
		if (!route.isEmpty())
		{
			int room = w - small.stringWidth("Codex Archive Splits for RuneLite") - 12;
			String r = Ui.clip(route, small, room);
			g.drawString(r, x + w - small.stringWidth(r), y + small.getAscent());
		}
		y += small.getHeight();
		return y + PAD;
	}

	/** A row goes on the card when it was timed, or when the run passed it, or stopped there. */
	private static boolean show(Run run, int row)
	{
		Split s = run.split(row);
		return (s != null && s.isDone()) || row < run.reached() || (run.getOutcome() == Outcome.WIPED && row == run.reached());
	}

	/** "New personal best, 31.2s off", "First trio clear", "42.0s behind your best", "Wiped at Xarth". */
	static String verdict(Standing st)
	{
		Run run = st.getRun();
		if (run.getOutcome() != Outcome.COMPLETED)
		{
			Split last = null;
			for (int row = 0; row < Encounter.ROWS; row++)
			{
				Split s = run.split(row);
				last = s != null && s.getEncounter() != null && s.getEncounter().getRow() == run.reached() ? s : last;
			}
			// "The Trio" on its own would read as a party size beside a duo's or a trio's runs.
			String where = last == null ? (run.reached() < Encounter.ROWS ? Encounter.rowLabel(run.reached()) : null)
				: last.getEncounter() == Encounter.TRIO ? "the Trio" : last.getEncounter().getShortName();
			return (run.getOutcome() == Outcome.WIPED ? "Wiped" : "Left") + (where == null ? "" : " at " + where);
		}
		if (st.isFirstClear())
		{
			return "First " + Format.clear(Records.BUCKETS[Records.bucket(run.getTeamSize())]);
		}
		int delta = st.totalDelta();
		if (delta < 0)
		{
			return "New personal best, " + Format.span(-delta) + " off";
		}
		// "Off" is kept for time taken off a best; a slower run is behind it, in the same seconds.
		return delta == 0 ? "Level with your best" : Format.span(delta) + " behind your best";
	}

	private static Color ribbonColor(Standing st)
	{
		if (st.getRun().getOutcome() != Outcome.COMPLETED)
		{
			return Theme.EMBER;
		}
		return st.isNewBest() ? Theme.GOLD_BRIGHT : Theme.TEXT_MUTED;
	}

	private static String crew(Run run)
	{
		java.util.List<String> names = run.getCrew();
		if (names.size() <= 3)
		{
			return String.join(", ", names);
		}
		return String.join(", ", names.subList(0, 3)) + " and " + (names.size() - 3) + " more";
	}

	static void ribbon(Graphics2D g, String text, Color color, int cx, int y)
	{
		g.setFont(Theme.body());
		FontMetrics fm = g.getFontMetrics();
		int tw = fm.stringWidth(text);
		int pw = tw + 34;
		int ph = 18;
		RoundRectangle2D shape = new RoundRectangle2D.Float(cx - pw / 2f, y, pw, ph, ph, ph);
		g.setColor(Theme.alpha(color, 30));
		g.fill(shape);
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(color, 150));
		g.draw(shape);
		diamond(g, cx - pw / 2f + 9, y + ph / 2f, 2.4f, color);
		diamond(g, cx + pw / 2f - 9, y + ph / 2f, 2.4f, color);
		Ui.shadowed(g, text, cx - tw / 2, y + (ph + fm.getAscent()) / 2 - 2, color);
	}

	private static void goldTag(Graphics2D g, int x, int y, String text)
	{
		FontMetrics fm = g.getFontMetrics();
		int w = fm.stringWidth(text) + 8;
		int h = fm.getAscent() + 2;
		RoundRectangle2D tag = new RoundRectangle2D.Float(x, y, w, h, 4, 4);
		g.setColor(Theme.alpha(Theme.GOLD, 50));
		g.fill(tag);
		g.setColor(Theme.alpha(Theme.GOLD, 160));
		g.draw(tag);
		g.setColor(Theme.GOLD_BRIGHT);
		g.drawString(text, x + 4, y + fm.getAscent());
	}

	/** A node on the thread: a gold room shines, a timed one is gilt, an untimed one hollow. */
	private static void node(Graphics2D g, float x, float y, boolean gold, boolean done)
	{
		if (gold)
		{
			g.setColor(Theme.alpha(Theme.GOLD, 60));
			g.fill(new Ellipse2D.Float(x - 7.5f, y - 7.5f, 15, 15));
			g.setColor(Theme.alpha(Theme.GOLD_BRIGHT, 170));
			g.draw(new Ellipse2D.Float(x - 6.5f, y - 6.5f, 13, 13));
		}
		g.setColor(Theme.INK_DEEP);
		g.fill(new Ellipse2D.Float(x - 5, y - 5, 10, 10));
		if (done)
		{
			diamond(g, x, y, gold ? 4.5f : 3.8f, gold ? Theme.GOLD_BRIGHT : Theme.GOLD);
		}
		else
		{
			g.setStroke(new BasicStroke(1f));
			g.setColor(Theme.EMBER);
			Path2D d = new Path2D.Float();
			d.moveTo(x, y - 3.5f);
			d.lineTo(x + 3.5f, y);
			d.lineTo(x, y + 3.5f);
			d.lineTo(x - 3.5f, y);
			d.closePath();
			g.draw(d);
		}
	}

	static void frame(Graphics2D g, int h, boolean best)
	{
		int w = WIDTH;
		RoundRectangle2D page = new RoundRectangle2D.Float(0, 0, w, h, 18, 18);
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.CARD_TOP, 0.5), 0, h, Theme.INK_DEEP));
		g.fill(page);
		g.setClip(page);
		g.setPaint(new RadialGradientPaint(w / 2f, 64, w * 0.75f, new float[]{0f, 1f},
			new Color[]{Theme.alpha(best ? Theme.GOLD_BRIGHT : Theme.GOLD, best ? 74 : 50), Theme.alpha(Theme.GOLD, 0)}));
		g.fillRect(0, 0, w, h);
		// A faint grain, the same every time, so the page reads as vellum rather than a flat fill.
		Random grain = new Random(17);
		for (int i = 0; i < w * h / 26; i++)
		{
			g.setColor(Theme.alpha(grain.nextBoolean() ? Theme.GOLD_BRIGHT : Color.BLACK, 6 + grain.nextInt(8)));
			g.fillRect(grain.nextInt(w), grain.nextInt(h), 1, 1);
		}
		// The mark engraved faintly in the corner: lines only, so it never muddies what sits over it.
		Sigil.engrave(g, w - 196, h - 206, 180, Theme.alpha(Theme.GOLD, 16));
		g.setClip(null);
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD, 190));
		g.draw(new RoundRectangle2D.Float(4.5f, 4.5f, w - 9, h - 9, 14, 14));
		g.setColor(Theme.alpha(Theme.GOLD_DIM, 120));
		g.draw(new RoundRectangle2D.Float(8.5f, 8.5f, w - 17, h - 17, 10, 10));
		float[][] corners = {{14, 14}, {w - 14, 14}, {14, h - 14}, {w - 14, h - 14}};
		for (float[] c : corners)
		{
			diamond(g, c[0], c[1], 3.5f, Theme.GOLD);
		}
	}

	static void centered(Graphics2D g, String text, int x, int w, int baseline, Color color)
	{
		FontMetrics fm = g.getFontMetrics();
		Ui.shadowed(g, text, x + (w - fm.stringWidth(text)) / 2, baseline, color);
	}

	static void rule(Graphics2D g, int x, int y, int w)
	{
		g.setStroke(new BasicStroke(1f));
		g.setPaint(new GradientPaint(x, 0, Theme.alpha(Theme.GOLD, 0), x + w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(x, y, x + w, y);
		diamond(g, x + w / 2f, y, 3, Theme.GOLD);
	}

	static void diamond(Graphics2D g, float cx, float cy, float r, Color color)
	{
		Path2D d = new Path2D.Float();
		d.moveTo(cx, cy - r);
		d.lineTo(cx + r, cy);
		d.lineTo(cx, cy + r);
		d.lineTo(cx - r, cy);
		d.closePath();
		g.setColor(color);
		g.fill(d);
	}
}

package com.codex.archive.ui;

import com.codex.archive.core.Outcome;
import com.codex.archive.core.Run;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JComponent;

/** One run in the history: when, which doors, the time and how it ended, with a purple gem when it gave a unique. */
class RunRow extends JComponent
{
	/**
	 * The width a row gets in the Records card: the sidebar, less its scroll bar, the page's
	 * gutters and the card's own edge. A long page always scrolls, so the scroll bar is counted.
	 */
	private static final int ROW_WIDTH = 225 - 8 - 2 * Theme.GUTTER - 8;
	private static final int SHORT = 32;
	private static final int TALL = 44;
	private final Run run;
	private final boolean best;
	/** The party size's best time, for the gap under each clear; -1 with none. */
	private final int bestTicks;
	private final long now;

	RunRow(Run run, boolean best, int bestTicks, long now)
	{
		this.run = run;
		this.best = best;
		this.bestTicks = bestTicks;
		this.now = now;
		setOpaque(false);
		// A long route takes a second line of its own rather than being cut short.
		// A first guess at the width; once the row is laid out it measures again at its real width.
		setPreferredSize(new Dimension(10, heightAt(ROW_WIDTH)));
		StringBuilder tip = new StringBuilder("<html>").append(Format.day(run.getStartedAt())).append(" at ")
			.append(Format.time(run.getStartedAt())).append(run.getKc() > 0 ? ", completion " + Format.count(run.getKc()) : "");
		if (run.getRole() != null)
		{
			tip.append("<br>Role: ").append(Ui.escape(run.getRole()));
		}
		if (!run.getCrew().isEmpty())
		{
			tip.append("<br>With ").append(Ui.escape(String.join(", ", run.getCrew())));
		}
		if (run.getNote() != null)
		{
			tip.append("<br>").append(Ui.escape(run.getNote()));
		}
		setToolTipText(tip.append("</html>").toString());
	}

	/** Two lines when the route does not fit beside the time at this width, one when it does. */
	private int heightAt(int width)
	{
		int room = width - 6 - (run.getPurple() != null ? 14 : 0) - getFontMetrics(Theme.body()).stringWidth(timeText()) - 12;
		return routeLines(getFontMetrics(Theme.small()), room).size() > 1 ? TALL : SHORT;
	}

	@Override
	public void setBounds(int x, int y, int width, int height)
	{
		super.setBounds(x, y, width, height);
		int want = width > 0 ? heightAt(width) : getPreferredSize().height;
		if (want != getPreferredSize().height)
		{
			// The guess was wrong for the width the row really got: take the right height at the next layout.
			setPreferredSize(new Dimension(10, want));
			revalidate();
		}
	}

	/** The time on the right: the clear's time, or how the run ended. */
	private String timeText()
	{
		if (run.getOutcome() == Outcome.COMPLETED)
		{
			return Format.ticks(run.getTicks());
		}
		return run.getOutcome() == Outcome.WIPED ? "Wiped" : "Left";
	}

	/**
	 * The route on one line when it fits, else on two broken between doors, the second cut short
	 * only if a single door's name is longer than the line.
	 */
	List<String> routeLines(FontMetrics fm, int width)
	{
		String route = run.route().isEmpty() ? "Guardian" : run.route();
		List<String> lines = new ArrayList<>();
		if (fm.stringWidth(route) <= width)
		{
			lines.add(route);
			return lines;
		}
		String[] doors = route.split(", ");
		StringBuilder first = new StringBuilder(doors[0]);
		int i = 1;
		while (i < doors.length && fm.stringWidth(first + ", " + doors[i] + ",") <= width)
		{
			first.append(", ").append(doors[i]);
			i++;
		}
		if (i >= doors.length)
		{
			lines.add(first.toString());
			return lines;
		}
		lines.add(Ui.clip(first + ",", fm, width));
		StringBuilder rest = new StringBuilder(doors[i]);
		for (int k = i + 1; k < doors.length; k++)
		{
			rest.append(", ").append(doors[k]);
		}
		lines.add(rest.toString());
		return lines;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setColor(Theme.STROKE_SOFT);
		g.drawLine(4, h - 1, w - 4, h - 1);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();

		String time = timeText();
		Color color;
		if (run.getOutcome() == Outcome.COMPLETED)
		{
			color = best ? Theme.GOLD_BRIGHT : Theme.TEXT;
		}
		else
		{
			color = run.getOutcome() == Outcome.WIPED ? Theme.BLOOD : Theme.TEXT_MUTED;
		}
		int tw = body.stringWidth(time);
		Ui.shadowed(g, time, w - 6 - tw, 14, color);
		// Under the time: the best itself, or how far off it a clear was. The page is one party size, so it needs no saying.
		g.setFont(Theme.small());
		String note = "";
		Color noteColor = Theme.TEXT_FAINT;
		if (best)
		{
			note = "best";
			noteColor = Theme.GOLD;
		}
		else if (run.isCompleted() && bestTicks >= 0)
		{
			note = Format.delta(run.getTicks() - bestTicks);
			noteColor = Theme.mix(Theme.BEHIND, Theme.TEXT_FAINT, 0.45);
		}
		else if (!run.isCompleted())
		{
			note = "at " + Format.ticks(run.getTicks());
		}
		g.setColor(noteColor);
		g.drawString(note, w - 6 - small.stringWidth(note), h >= TALL ? 27 : h - 6);

		int x = 6;
		if (run.getPurple() != null)
		{
			Color gem = Theme.PURPLE;
			g.setColor(Theme.alpha(gem, 70));
			g.fill(new Ellipse2D.Float(x - 2, 6, 12, 12));
			g.setColor(gem);
			g.fill(new Ellipse2D.Float(x + 1, 9, 6, 6));
			x += 14;
		}
		g.setFont(Theme.small());
		List<String> route = h >= TALL ? routeLines(small, w - x - tw - 12)
			: java.util.Collections.singletonList(Ui.clip(run.route().isEmpty() ? "Guardian" : run.route(), small, w - x - tw - 12));
		Ui.shadowed(g, route.get(0), x, 14, Theme.TEXT);
		if (route.size() > 1)
		{
			// The second line runs beside the note under the time, so it stops short of it.
			Ui.shadowed(g, Ui.clip(route.get(1), small, w - x - Math.max(tw, small.stringWidth(note)) - 12), x, 27, Theme.TEXT);
		}
		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_FAINT);
		String when = Format.ago(now - run.getStartedAt());
		if (run.getRole() != null)
		{
			when += ", " + run.getRole().toLowerCase();
		}
		if (run.getNote() != null)
		{
			when += ", " + run.getNote();
		}
		if (run.getPurple() != null)
		{
			when = run.getPurple() + ", " + when;
			g.setColor(Theme.mix(Theme.PURPLE, Theme.TEXT_FAINT, 0.3));
		}
		// On a two-line route the note sits beside the route, so this last line has the row to itself.
		g.drawString(Ui.clip(when, small, h >= TALL ? w - x - 6 : w - x - 70), x, h - 6);
		g.dispose();
	}
}

package com.codex.archive.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A small-caps heading with a gold diamond and a line that fades into the dark. */
public class SectionHeader extends JComponent
{
	private final String text;
	private final String trailing;

	public SectionHeader(String text)
	{
		this(text, null);
	}

	public SectionHeader(String text, String trailing)
	{
		this.text = text.toUpperCase();
		this.trailing = trailing;
		setFont(Theme.small());
		setPreferredSize(new Dimension(10, 20));
		setMinimumSize(new Dimension(10, 20));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setFont(getFont());
		paint(g, text, trailing, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a heading in a box; the card uses the same drawing. The font must already be set. */
	static void paint(Graphics2D g, String text, String trailing, int x, int y, int w, int h)
	{
		int mid = y + h / 2 + 2;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(x + 4, mid - 4);
		diamond.lineTo(x + 8, mid);
		diamond.lineTo(x + 4, mid + 4);
		diamond.lineTo(x, mid);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);

		FontMetrics fm = g.getFontMetrics();
		int textX = x + 13;
		int baseline = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.GOLD);
		g.drawString(text, textX, baseline);

		int lineStart = textX + fm.stringWidth(text) + 6;
		int lineEnd = x + w;
		if (trailing != null && !trailing.isEmpty())
		{
			int tw = fm.stringWidth(trailing);
			lineEnd = x + w - tw - 6;
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(trailing, x + w - tw, baseline);
		}
		if (lineEnd > lineStart)
		{
			g.setPaint(new GradientPaint(lineStart, 0, Theme.alpha(Theme.GOLD, 110), lineEnd, 0, Theme.alpha(Theme.GOLD, 0)));
			g.drawLine(lineStart, mid, lineEnd, mid);
		}
	}
}

package com.codex.archive.ui;

import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.function.IntConsumer;
import javax.swing.JComponent;

/**
 * Tabs drawn as one engraved strip: the chosen segment is lit from below by a
 * gold glow, the rest sit quietly in the ink.
 */
public class Segmented extends JComponent
{
	private final String[] labels;
	private final boolean large;
	private final Animator slide = new Animator(this);
	private int selected;
	private int hover = -1;
	private IntConsumer listener;

	public Segmented(boolean large, String... labels)
	{
		this.labels = labels;
		this.large = large;
		setFont(large ? Theme.title() : Theme.small());
		int h = large ? 28 : 22;
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				setSelected(indexAt(e.getX()), true);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	public void onChange(IntConsumer listener)
	{
		this.listener = listener;
	}

	public int getSelected()
	{
		return selected;
	}

	public void setSelected(int index, boolean notify)
	{
		if (index < 0 || index >= labels.length)
		{
			return;
		}
		boolean changed = index != selected;
		selected = index;
		slide.set(index, true);
		repaint();
		if (changed && notify && listener != null)
		{
			listener.accept(index);
		}
	}

	private int indexAt(int x)
	{
		int w = Math.max(1, getWidth());
		return Math.max(0, Math.min(labels.length - 1, x * labels.length / w));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float seg = w / (float) labels.length;

		RoundRectangle2D strip = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setColor(Theme.INK_DEEP);
		g.fill(strip);

		float x = (float) (slide.get() * seg);
		RoundRectangle2D lit = new RoundRectangle2D.Float(x + 2, 2, seg - 4, h - 4, 6, 6);
		g.setPaint(new GradientPaint(0, 2, Theme.CARD_TOP, 0, h, Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35)));
		g.fill(lit);
		g.setColor(Theme.alpha(Theme.GOLD, 120));
		g.draw(lit);
		g.setColor(Theme.GOLD_BRIGHT);
		g.fillRect(Math.round(x + seg * 0.3f), h - 4, Math.round(seg * 0.4f), 1);

		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < labels.length; i++)
		{
			int tx = Math.round(i * seg + (seg - fm.stringWidth(labels[i])) / 2);
			int ty = (h + fm.getAscent()) / 2 - (large ? 2 : 1);
			java.awt.Color color = i == selected ? Theme.GOLD_BRIGHT : i == hover ? Theme.TEXT : Theme.TEXT_MUTED;
			Ui.shadowed(g, labels[i], tx, ty, color);
		}
		g.setColor(Theme.STROKE_SOFT);
		g.draw(strip);
		g.dispose();
	}
}

package com.codex.archive.ui;

import com.codex.archive.core.Encounter;
import com.codex.archive.core.Records;
import com.codex.archive.core.Run;
import com.codex.archive.core.Sessions;
import com.codex.archive.core.Split;
import com.codex.archive.core.Standing;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * The session card: one sitting in the Fractured Archive on the run card's gilt page. The sitting's
 * best clear large, a ribbon for what the sitting brought (a purple, a new best, how close it came
 * to the best), then every run as a bar of its time against the sitting's slowest clear, the best
 * lit, with its tags: a new best, a first clear, a purple, where a wipe stopped. Beneath, the
 * average clear, the pace and the time between runs.
 */
public final class SessionCard
{
	/** Runs drawn on the card; a longer sitting shows its latest. */
	static final int RUNS = 12;
	private static final int PAD = 20;
	private static final int ROW = 18;
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("EEEE d MMMM yyyy", Locale.ENGLISH);

	private SessionCard()
	{
	}

	/**
	 * @param all every run kept, so each run of the sitting is measured against those before it
	 * @param player the name to put on the card, or null to leave it off
	 */
	public static BufferedImage render(Sessions.Session s, List<Run> all, String player, ZoneId zone)
	{
		List<Row> rows = rows(s, all);
		BufferedImage scratch = new BufferedImage(RunCard.WIDTH, 1200, BufferedImage.TYPE_INT_ARGB);
		Graphics2D sg = scratch.createGraphics();
		int height = content(sg, s, rows, all, player, zone);
		sg.dispose();

		BufferedImage image = new BufferedImage(RunCard.WIDTH * RunCard.SCALE, height * RunCard.SCALE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.scale(RunCard.SCALE, RunCard.SCALE);
		Theme.smooth(g);
		RunCard.frame(g, height, s.getBests() > 0);
		content(g, s, rows, all, player, zone);
		g.dispose();
		return image;
	}

	/** One run of the sitting as the card tells it. */
	static final class Row
	{
		final Run run;
		/** "PB", "FIRST", or null. */
		final String tag;
		/** What the line ends with: a purple's name, or null. A run that did not clear says where it stopped in place of its time. */
		final String end;

		Row(Run run, String tag, String end)
		{
			this.run = run;
			this.tag = tag;
			this.end = end;
		}
	}

	static List<Row> rows(Sessions.Session s, List<Run> all)
	{
		List<Row> out = new ArrayList<>();
		for (Run r : s.getRuns())
		{
			Standing st = Standing.of(all, r);
			String tag = !r.isCompleted() ? null : st.isFirstClear() ? "FIRST" : st.isNewBest() ? "PB" : null;
			String end = r.getPurple();
			out.add(new Row(r, tag, end));
		}
		return out;
	}

	/**
	 * What the sitting brought, in a few words, never a figure the card shows elsewhere: its purples
	 * first, then its new bests, then how near its best clear came to the best before it.
	 */
	static String verdict(Sessions.Session s, List<Run> all)
	{
		List<String> purples = new ArrayList<>();
		for (Run r : s.getRuns())
		{
			if (r.getPurple() != null)
			{
				purples.add(r.getPurple());
			}
		}
		if (purples.size() == 1)
		{
			return "A purple: " + purples.get(0);
		}
		if (purples.size() > 1)
		{
			return purples.size() + " purples in one sitting";
		}
		int bests = 0;
		Run first = null;
		for (Run r : s.getRuns())
		{
			Standing st = r.isCompleted() ? Standing.of(all, r) : null;
			if (st != null && st.isFirstClear())
			{
				first = first == null ? r : first;
			}
			else if (st != null && st.isNewBest())
			{
				bests++;
			}
		}
		if (bests > 0)
		{
			return bests == 1 ? "A new personal best" : bests + " new personal bests";
		}
		if (first != null)
		{
			return "A first " + Format.clear(Records.BUCKETS[Records.bucket(first.getTeamSize())]);
		}
		if (s.getClears() == 0)
		{
			// The big figure already says No clear; the ribbon says how far the sitting got instead.
			String furthest = furthest(s);
			return furthest == null ? "A session in the archive" : "Furthest: " + furthest;
		}
		Run best = bestRun(s);
		Integer delta = best == null ? null : Standing.of(all, best).totalDelta();
		if (delta != null && delta > 0)
		{
			return "Within " + Format.span(delta) + " of your best";
		}
		return s.getWipes() == 0 ? "Every run cleared" : "A session in the archive";
	}

	/**
	 * The deepest boss the sitting's runs reached, by its full name, or null: a short name such as
	 * "Trio" reads as a party size on a duo's card.
	 */
	static String furthest(Sessions.Session s)
	{
		int deepest = -1;
		String name = null;
		for (Run r : s.getRuns())
		{
			int row = r.reached();
			for (int i = 0; i < Encounter.ROWS; i++)
			{
				Split sp = r.split(i);
				if (sp != null && sp.getEncounter() != null && sp.getEncounter().getRow() == row && row > deepest)
				{
					deepest = row;
					String title = sp.getEncounter().getTitle();
					name = title.startsWith("The ") ? "the " + title.substring(4) : title;
				}
			}
		}
		return name;
	}

	/** The sitting's quickest clear, or null with none. */
	static Run bestRun(Sessions.Session s)
	{
		Run best = null;
		for (Run r : s.getRuns())
		{
			if (r.isCompleted() && (best == null || r.getTicks() < best.getTicks()))
			{
				best = r;
			}
		}
		return best;
	}

	/**
	 * The runs the card draws, by their place in the sitting: every run when they fit, else the
	 * latest, with the sitting's best clear kept among them so the big figure is always one drawn.
	 */
	static List<Integer> shown(List<Row> rows, Run best)
	{
		List<Integer> out = new ArrayList<>();
		int from = Math.max(0, rows.size() - RUNS);
		int bestAt = -1;
		for (int i = 0; i < from; i++)
		{
			bestAt = rows.get(i).run == best ? i : bestAt;
		}
		if (bestAt >= 0)
		{
			out.add(bestAt);
			from++;
		}
		for (int i = from; i < rows.size(); i++)
		{
			out.add(i);
		}
		return out;
	}

	/** The slowest clear among the runs drawn, the end of every bar; 0 with none. */
	static int slowest(List<Row> rows, List<Integer> shown)
	{
		int slowest = 0;
		for (int i : shown)
		{
			Run r = rows.get(i).run;
			slowest = r.isCompleted() ? Math.max(slowest, r.getTicks()) : slowest;
		}
		return slowest;
	}

	/**
	 * The three figures beneath the runs, each {value, label, line beneath}: the average clear, the
	 * pace and the time between runs; with no clear, the bosses the runs felled and how long a run
	 * lasted in place of the first two, so the card never says No clear again.
	 */
	static String[][] tiles(Sessions.Session s)
	{
		String[] downtime = {s.getBetween() < 0 ? "-" : Format.clock((int) (s.getBetween() / 600)), "Downtime",
			s.getBetween() < 0 ? "one run" : "between runs"};
		if (s.getClears() == 0)
		{
			int felled = 0;
			long ticks = 0;
			for (Run r : s.getCounted())
			{
				for (Split sp : r.getSplits())
				{
					felled += sp.isDone() ? 1 : 0;
				}
				ticks += Math.max(0, r.getTicks());
			}
			int runs = Math.max(1, s.getCounted().size());
			return new String[][]{
				{String.valueOf(felled), "Bosses", "felled"},
				{Format.ticks((int) (ticks / runs)), "A run", "on average"},
				downtime};
		}
		double pace = s.perHour();
		return new String[][]{
			{s.getAverage() < 0 ? "-" : Format.ticks(s.getAverage()), "Average", "a clear"},
			{pace > 0 ? String.format(Locale.ENGLISH, "%.1f", pace) : "-", "An hour", pace > 0 ? "clears" : "too short to tell"},
			downtime};
	}

	/** "4 clears, 1 wipe", "1 clear, no wipes". */
	static String tally(Sessions.Session s)
	{
		String clears = s.getClears() + (s.getClears() == 1 ? " clear" : " clears");
		String wipes = s.getWipes() + (s.getWipes() == 1 ? " wipe" : " wipes");
		if (s.getClears() == 0)
		{
			return wipes;
		}
		return clears + ", " + (s.getWipes() == 0 ? "no wipes" : wipes);
	}

	/** The party the sitting was raided in: "Trio", or "Mixed parties". */
	static String party(Sessions.Session s)
	{
		int bucket = -1;
		for (Run r : s.getRuns())
		{
			int b = Records.bucket(r.getTeamSize());
			if (bucket >= 0 && b != bucket)
			{
				return "Mixed parties";
			}
			bucket = b;
		}
		return bucket < 0 ? "" : Records.BUCKETS[bucket];
	}

	private static int content(Graphics2D g, Sessions.Session s, List<Row> rows, List<Run> all, String player, ZoneId zone)
	{
		Theme.smooth(g);
		int x = PAD;
		int w = RunCard.WIDTH - PAD * 2;
		int y = PAD + 4;

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		Sigil.paint(g, x, y - 2, 14);
		g.setColor(Theme.GOLD);
		g.drawString("CODEX ARCHIVE SPLITS", x + 19, y + small.getAscent() - 1);
		String corner = "A SESSION";
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(corner, x + w - small.stringWidth(corner), y + small.getAscent() - 1);
		y += small.getHeight() + 10;

		// The sitting's best clear, large; with none, No clear in ember.
		Run best = bestRun(s);
		Font huge = Theme.title().deriveFont(Theme.title().getSize2D() * 3.5f);
		g.setFont(huge);
		FontMetrics hm = g.getFontMetrics();
		String big = best != null ? Format.ticks(best.getTicks()) : "No clear";
		Tight.Layout set = Tight.layout(g, big);
		float tx = x + (w - set.width) / 2f;
		int base = y + hm.getAscent() - 10;
		g.setColor(Color.BLACK);
		set.draw(g, tx + 2, base + 2);
		Color top = best != null ? Theme.GOLD_BRIGHT : Theme.mix(Theme.EMBER, Theme.TEXT, 0.25);
		Color bottom = best != null ? Theme.GOLD_DIM : Theme.mix(Theme.EMBER, Theme.INK, 0.35);
		g.setPaint(new GradientPaint(0, base - hm.getAscent() + 12, top, 0, base, bottom));
		set.draw(g, tx, base);
		y = base + 2;
		if (best != null)
		{
			g.setFont(Theme.small());
			RunCard.centered(g, "BEST CLEAR", x, w, y + small.getAscent(), Theme.TEXT_MUTED);
			y += small.getHeight() + 4;
		}
		else
		{
			y += 8;
		}

		g.setFont(Theme.body());
		// A long unique's name still leaves the ribbon its ends inside the page.
		String verdict = Ui.clip(verdict(s, all), g.getFontMetrics(), w - 40);
		Color ribbon = verdict.startsWith("A purple") || verdict.contains("purples") ? Theme.PURPLE
			: s.getBests() > 0 ? Theme.GOLD_BRIGHT : s.getClears() == 0 ? Theme.EMBER : Theme.TEXT_MUTED;
		RunCard.ribbon(g, verdict, ribbon, x + w / 2, y);
		y += 24;

		g.setFont(Theme.small());
		String when = Instant.ofEpochMilli(s.getStart()).atZone(zone).format(DATE) + ", " + Format.time(s.getStart(), zone) + " to " + Format.time(s.getEnd(), zone);
		String party = party(s);
		String line = party.isEmpty() ? when : party + " · " + when;
		RunCard.centered(g, Ui.clip(line, small, w), x, w, y + small.getAscent(), Theme.TEXT_MUTED);
		y += small.getHeight() + 2;
		if (player != null && !player.isEmpty())
		{
			g.setFont(Theme.title());
			FontMetrics bold = g.getFontMetrics();
			RunCard.centered(g, Ui.clip(player, bold, w), x, w, y + bold.getAscent(), Theme.TEXT);
			y += bold.getHeight();
		}
		y += 6;
		RunCard.rule(g, x, y, w);
		y += 10;

		// Every run, a bar for its time against the sitting's slowest clear.
		g.setFont(Theme.small());
		g.setColor(Theme.GOLD);
		g.drawString("THE RUNS", x, y + small.getAscent());
		String tally = tally(s);
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(tally, x + w - small.stringWidth(tally), y + small.getAscent());
		y += small.getHeight() + 6;

		List<Integer> shown = shown(rows, best);
		int slowest = slowest(rows, shown);
		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		int numW = small.stringWidth("00") + 6;
		int timeW = body.stringWidth("00:00.0") + 8;
		for (int k = 0; k < shown.size(); k++)
		{
			int i = shown.get(k);
			int prev = k == 0 ? -1 : shown.get(k - 1);
			if (i - prev > 1)
			{
				// Where runs are left off, one line says how many, in their place.
				int gap = i - prev - 1;
				g.setFont(Theme.small());
				String earlier = gap + (gap == 1 ? (prev < 0 ? " earlier run" : " run") : (prev < 0 ? " earlier runs" : " runs")) + " not shown";
				RunCard.centered(g, earlier, x, w, y + small.getAscent(), Theme.TEXT_FAINT);
				y += small.getHeight() + 2;
			}
			Row r = rows.get(i);
			int mid = y + ROW / 2;
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			String n = String.valueOf(i + 1);
			g.drawString(n, x + numW - 6 - small.stringWidth(n), mid + small.getAscent() / 2 - 1);
			int tx0 = x + numW;
			boolean top1 = best != null && r.run == best;
			g.setFont(Theme.body());
			if (r.run.isCompleted())
			{
				Ui.shadowed(g, Format.ticks(r.run.getTicks()), tx0, mid + body.getAscent() / 2 - 1, top1 ? Theme.GOLD_BRIGHT : Theme.TEXT);
			}
			else
			{
				// Where it stopped, once, in place of a time and a bar.
				Ui.shadowed(g, Ui.clip(RunCard.verdict(Standing.of(all, r.run)), body, w - numW - 60), tx0, mid + body.getAscent() / 2 - 1, Theme.EMBER);
			}

			// The tags and the end of the line, from the right.
			int right = x + w;
			g.setFont(Theme.small());
			if (r.end != null)
			{
				boolean purple = r.run.getPurple() != null;
				int room = Math.max(40, (w - numW - timeW) / 2);
				String end = Ui.clip(r.end, small, room);
				g.setColor(purple ? Theme.PURPLE : Theme.EMBER);
				g.drawString(end, right - small.stringWidth(end), mid + small.getAscent() / 2 - 1);
				right -= small.stringWidth(end) + 6;
			}
			if (r.tag != null)
			{
				right -= tag(g, r.tag, right, mid) + 6;
			}
			int barX = tx0 + timeW;
			int barW = right - barX;
			if (r.run.isCompleted() && slowest > 0 && barW > 8)
			{
				int len = Math.max(3, Math.round(barW * r.run.getTicks() / (float) slowest));
				g.setColor(Theme.alpha(Theme.STROKE_SOFT, 200));
				g.fill(new RoundRectangle2D.Float(barX, mid - 2, barW, 4, 4, 4));
				g.setPaint(new GradientPaint(barX, 0, top1 ? Theme.GOLD : Theme.GOLD_DIM, barX + len, 0, top1 ? Theme.GOLD_BRIGHT : Theme.GOLD));
				g.fill(new RoundRectangle2D.Float(barX, mid - 2, len, 4, 4, 4));
			}
			y += ROW;
		}
		y += 6;
		RunCard.rule(g, x, y, w);
		y += 10;

		// Three figures beneath: the average clear, the pace and the time between runs.
		int tileW = (w - 12) / 3;
		int tileH = 50;
		String[][] tiles = tiles(s);
		StatTile.paint(g, tiles[0][0], tiles[0][1], tiles[0][2], Theme.TEXT, x, y, tileW, tileH);
		StatTile.paint(g, tiles[1][0], tiles[1][1], tiles[1][2], Theme.TEAL, x + tileW + 6, y, tileW, tileH);
		StatTile.paint(g, tiles[2][0], tiles[2][1], tiles[2][2], Theme.TEXT, x + (tileW + 6) * 2, y, w - (tileW + 6) * 2, tileH);
		y += tileH + 10;

		RunCard.rule(g, x, y, w);
		y += 8;
		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_FAINT);
		g.drawString("Codex Archive Splits for RuneLite", x, y + small.getAscent());
		String span = span(s.getStart(), s.getEnd()) + " at the archive";
		g.drawString(span, x + w - small.stringWidth(span), y + small.getAscent());
		y += small.getHeight();
		return y + PAD;
	}

	/**
	 * "1h 35m", "48m": the minutes between the two clock times the card prints, so 15:04 to 16:15
	 * is 1h 11m however many seconds either end held.
	 */
	static String span(long start, long end)
	{
		long minutes = Math.max(1, Math.floorDiv(end, 60_000L) - Math.floorDiv(start, 60_000L));
		return minutes < 60 ? minutes + "m" : minutes / 60 + "h " + minutes % 60 + "m";
	}

	/** A small gilt tag ending at right; returns its width. */
	private static int tag(Graphics2D g, String text, int right, int mid)
	{
		FontMetrics fm = g.getFontMetrics();
		int w = fm.stringWidth(text) + 8;
		int h = fm.getAscent() + 2;
		RoundRectangle2D shape = new RoundRectangle2D.Float(right - w, mid - h / 2f - 1, w, h, 4, 4);
		g.setColor(Theme.alpha(Theme.GOLD, 50));
		g.fill(shape);
		g.setColor(Theme.alpha(Theme.GOLD, 160));
		g.draw(shape);
		g.setColor(Theme.GOLD_BRIGHT);
		g.drawString(text, right - w + 4, mid + fm.getAscent() / 2 - 1);
		return w;
	}
}

package com.codex.archive.ui;

import com.codex.archive.core.Comparison;
import com.codex.archive.core.Encounter;
import com.codex.archive.core.Outcome;
import com.codex.archive.core.Records;
import com.codex.archive.core.Run;
import com.codex.archive.core.Split;

/** A run's splits as plain text, lined up for pasting into a chat. */
public final class Share
{
	private Share()
	{
	}

	/**
	 * @param pb the best run before this one, to show each boss against; or null
	 */
	public static String splits(Run run, Comparison pb)
	{
		StringBuilder sb = new StringBuilder();
		String party = Format.party(Records.BUCKETS[Records.bucket(run.getTeamSize())]);
		sb.append("Fractured Archive, ").append(party).append(", ").append(Format.day(run.getStartedAt())).append('\n');
		for (int row = 0; row < Encounter.ROWS; row++)
		{
			Split s = run.split(row);
			if (s == null || !s.isDone())
			{
				continue;
			}
			sb.append(pad(s.getEncounter().getShortName(), 11))
				.append(pad(Format.ticks(s.getEndTick()), 9))
				.append("room ").append(pad(Format.ticks(s.roomTicks(0)), 8));
			Integer delta = pb == null ? null : pb.delta(run, row);
			if (delta != null)
			{
				sb.append(' ').append(Format.delta(delta));
			}
			sb.append('\n');
		}
		if (run.getOutcome() == Outcome.COMPLETED)
		{
			sb.append("Cleared in ").append(Format.ticks(run.getTicks()));
			int best = pb == null ? -1 : pb.total();
			if (best > 0)
			{
				sb.append(run.getTicks() < best ? ", a new best by " + Format.span(best - run.getTicks())
					: run.getTicks() == best ? ", level with the best"
					: ", " + Format.span(run.getTicks() - best) + " off the best");
			}
		}
		else
		{
			sb.append(run.getOutcome() == Outcome.WIPED ? "Wiped" : "Left").append(" at ").append(Format.ticks(run.getTicks()));
		}
		if (run.getDeaths() > 0)
		{
			sb.append(", ").append(run.getDeaths()).append(run.getDeaths() == 1 ? " death" : " deaths");
		}
		return sb.append('\n').toString();
	}

	private static String pad(String text, int width)
	{
		StringBuilder sb = new StringBuilder(text);
		while (sb.length() < width)
		{
			sb.append(' ');
		}
		return sb.toString();
	}
}

package com.codex.archive.ui;

import java.awt.BasicStroke;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;

/** The mark of Archive Splits: an open gilt tome split by a teal fracture, with a shard of the raid's purple above it. */
public final class Sigil
{
	private Sigil()
	{
	}

	public static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		paint(g, 0, 0, size);
		g.dispose();
		return image;
	}

	/** Draws the mark in a size by size box. */
	public static void paint(Graphics2D g, float x, float y, float size)
	{
		float s = size / 16f;
		float stroke = Math.max(0.7f, 0.6f * s);

		// The two pages, curving up from the spine.
		Path2D left = new Path2D.Float();
		left.moveTo(x + 8 * s, y + 6.4f * s);
		left.curveTo(x + 6 * s, y + 5.2f * s, x + 3 * s, y + 5 * s, x + 0.8f * s, y + 6 * s);
		left.lineTo(x + 0.8f * s, y + 14.2f * s);
		left.curveTo(x + 3 * s, y + 13.4f * s, x + 6 * s, y + 13.6f * s, x + 8 * s, y + 14.8f * s);
		left.closePath();
		Path2D right = new Path2D.Float();
		right.moveTo(x + 8 * s, y + 6.4f * s);
		right.curveTo(x + 10 * s, y + 5.2f * s, x + 13 * s, y + 5 * s, x + 15.2f * s, y + 6 * s);
		right.lineTo(x + 15.2f * s, y + 14.2f * s);
		right.curveTo(x + 13 * s, y + 13.4f * s, x + 10 * s, y + 13.6f * s, x + 8 * s, y + 14.8f * s);
		right.closePath();
		g.setPaint(new GradientPaint(x, y + 5 * s, Theme.GOLD_BRIGHT, x, y + 15 * s, Theme.GOLD_DIM));
		g.fill(left);
		g.setPaint(new GradientPaint(x, y + 5 * s, Theme.GOLD, x, y + 15 * s, Theme.mix(Theme.GOLD_DIM, Theme.INK_DEEP, 0.3)));
		g.fill(right);
		g.setStroke(new BasicStroke(stroke, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.INK_DEEP);
		g.draw(left);
		g.draw(right);

		// Lines of script on each page.
		g.setColor(Theme.alpha(Theme.INK_DEEP, 120));
		g.setStroke(new BasicStroke(Math.max(0.5f, 0.45f * s)));
		for (int i = 0; i < 3; i++)
		{
			float ly = y + (8.4f + i * 1.9f) * s;
			g.draw(new java.awt.geom.Line2D.Float(x + 2.2f * s, ly, x + 6.4f * s, ly + 0.3f * s));
		}

		// The fracture, down the right page.
		Path2D crack = new Path2D.Float();
		crack.moveTo(x + 11.6f * s, y + 5.6f * s);
		crack.lineTo(x + 10.6f * s, y + 8.4f * s);
		crack.lineTo(x + 12.4f * s, y + 9.8f * s);
		crack.lineTo(x + 10.8f * s, y + 13.8f * s);
		g.setStroke(new BasicStroke(Math.max(1.8f, 1.9f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.INK_DEEP);
		g.draw(crack);
		g.setStroke(new BasicStroke(Math.max(0.9f, 0.95f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.TEAL);
		g.draw(crack);

		// A purple shard rising from the break.
		Path2D shard = new Path2D.Float();
		shard.moveTo(x + 11.2f * s, y + 0.6f * s);
		shard.lineTo(x + 12.9f * s, y + 2.6f * s);
		shard.lineTo(x + 11.2f * s, y + 4.6f * s);
		shard.lineTo(x + 9.5f * s, y + 2.6f * s);
		shard.closePath();
		float r = 2.6f * s;
		g.setColor(Theme.alpha(Theme.PURPLE, 70));
		g.fill(new Ellipse2D.Float(x + 11.2f * s - r, y + 2.6f * s - r, r * 2, r * 2));
		g.setPaint(new GradientPaint(x + 9.5f * s, y, Theme.mix(Theme.PURPLE, Theme.TEXT, 0.45f), x + 12.9f * s, y + 4.6f * s, Theme.PURPLE_DEEP));
		g.fill(shard);
		g.setStroke(new BasicStroke(stroke));
		g.setColor(Theme.INK_DEEP);
		g.draw(shard);
	}

	/**
	 * The mark as a fine engraving: its outlines only, in one colour, for a watermark. Filled
	 * shapes faded to a few percent read as a smudge on the page; thin lines stay crisp.
	 */
	public static void engrave(Graphics2D g, float x, float y, float size, java.awt.Color color)
	{
		float s = size / 16f;
		g.setColor(color);
		g.setStroke(new BasicStroke(1.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		for (int side = -1; side <= 1; side += 2)
		{
			Path2D page = new Path2D.Float();
			page.moveTo(x + 8 * s, y + 6.4f * s);
			page.curveTo(x + (8 + side * 2) * s, y + 5.2f * s, x + (8 + side * 5) * s, y + 5 * s, x + (8 + side * 7.2f) * s, y + 6 * s);
			page.lineTo(x + (8 + side * 7.2f) * s, y + 14.2f * s);
			page.curveTo(x + (8 + side * 5) * s, y + 13.4f * s, x + (8 + side * 2) * s, y + 13.6f * s, x + 8 * s, y + 14.8f * s);
			page.closePath();
			g.draw(page);
		}
		for (int i = 0; i < 3; i++)
		{
			float ly = y + (8.4f + i * 1.9f) * s;
			g.draw(new java.awt.geom.Line2D.Float(x + 2.2f * s, ly, x + 6.4f * s, ly + 0.3f * s));
		}
		Path2D crack = new Path2D.Float();
		crack.moveTo(x + 11.6f * s, y + 5.6f * s);
		crack.lineTo(x + 10.6f * s, y + 8.4f * s);
		crack.lineTo(x + 12.4f * s, y + 9.8f * s);
		crack.lineTo(x + 10.8f * s, y + 13.8f * s);
		g.draw(crack);
		Path2D shard = new Path2D.Float();
		shard.moveTo(x + 11.2f * s, y + 0.6f * s);
		shard.lineTo(x + 12.9f * s, y + 2.6f * s);
		shard.lineTo(x + 11.2f * s, y + 4.6f * s);
		shard.lineTo(x + 9.5f * s, y + 2.6f * s);
		shard.closePath();
		g.draw(shard);
	}
}

package com.codex.archive.ui;

import com.codex.archive.core.Comparison;
import com.codex.archive.core.Encounter;
import com.codex.archive.core.Run;
import com.codex.archive.core.Split;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/**
 * The five encounters of a run as a thread of gilt nodes, top to bottom. Each fallen boss shows
 * its room time, the run's time when it fell and how that stands against the best run; the boss
 * being fought glows teal with its clock running; rows not reached wait in faint ink, naming the
 * two doors they offer.
 */
public class SplitTable extends JComponent
{
	private static final int ROW = 38;
	private static final int PAD = 10;
	private static final int NODE_X = 16;

	private Run run;
	private Comparison comparison;
	private int elapsed;
	private boolean live;
	private int[] bestRooms = new int[Encounter.ROWS];

	public SplitTable()
	{
		setOpaque(false);
		int h = ROW * Encounter.ROWS + PAD * 2;
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
	}

	/**
	 * @param run the run to show, live or finished
	 * @param comparison the marks to measure against, or null
	 * @param bestRooms each row's best room time, or -1
	 * @param elapsed ticks since a live run began
	 */
	public void update(Run run, Comparison comparison, int[] bestRooms, int elapsed, boolean live)
	{
		this.run = run;
		this.comparison = comparison;
		this.bestRooms = bestRooms;
		this.elapsed = elapsed;
		this.live = live;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(0, 0, Theme.CARD_TOP, 0, h, Theme.CARD));
		g.fill(shape);
		g.setColor(live ? Theme.alpha(Theme.TEAL, 110) : Theme.STROKE_SOFT);
		g.draw(shape);

		int reached = reachedRow();
		// The row being fought is the one after the furthest boss down, even if a row before it went untimed.
		int current = live && run != null && reached < Encounter.ROWS ? reached : -1;

		// The thread joining the nodes, gilt as far as the run has come.
		int top = PAD + ROW / 2;
		int bottom = PAD + ROW * (Encounter.ROWS - 1) + ROW / 2;
		g.setStroke(new BasicStroke(2f));
		g.setColor(Theme.STROKE);
		g.drawLine(NODE_X, top, NODE_X, bottom);
		if (reached > 0)
		{
			int end = PAD + ROW * Math.min(reached, Encounter.ROWS - 1) + ROW / 2;
			g.setPaint(new GradientPaint(0, top, Theme.GOLD_BRIGHT, 0, end, Theme.GOLD_DIM));
			g.drawLine(NODE_X, top, NODE_X, end);
		}
		g.setStroke(new BasicStroke(1f));

		for (int row = 0; row < Encounter.ROWS; row++)
		{
			paintRow(g, row, PAD + row * ROW, w, row == current, row < reached);
		}
		g.dispose();
	}

	/** The rows the run has finished, the next one being the one it is on. */
	private int reachedRow()
	{
		return run == null ? 0 : run.reached();
	}

	private void paintRow(Graphics2D g, int row, int y, int w, boolean current, boolean passed)
	{
		Split split = run == null ? null : run.split(row);
		boolean done = split != null && split.isDone();
		boolean failed = !live && split != null && !done;
		// Behind the furthest boss down but with no time: the client never saw this boss fall.
		boolean untimed = passed && !done;
		int mid = y + ROW / 2;

		if (current)
		{
			RoundRectangle2D glow = new RoundRectangle2D.Float(4, y + 2, w - 8, ROW - 4, 8, 8);
			g.setPaint(new GradientPaint(0, y, Theme.alpha(Theme.TEAL, 46), w, y, Theme.alpha(Theme.TEAL, 6)));
			g.fill(glow);
		}

		// The node: a filled gilt diamond once fallen, a teal ring while fighting, a hollow mark ahead.
		Path2D diamond = new Path2D.Float();
		float r = done ? 5.5f : 4.5f;
		diamond.moveTo(NODE_X, mid - r);
		diamond.lineTo(NODE_X + r, mid);
		diamond.lineTo(NODE_X, mid + r);
		diamond.lineTo(NODE_X - r, mid);
		diamond.closePath();
		if (done)
		{
			g.setPaint(new GradientPaint(0, mid - r, Theme.GOLD_BRIGHT, 0, mid + r, Theme.GOLD_DIM));
			g.fill(diamond);
			g.setColor(Theme.INK_DEEP);
			g.draw(diamond);
		}
		else if (current)
		{
			g.setColor(Theme.alpha(Theme.TEAL, 60));
			g.fill(new Ellipse2D.Float(NODE_X - 8, mid - 8, 16, 16));
			g.setColor(Theme.INK_DEEP);
			g.fill(diamond);
			g.setColor(Theme.TEAL);
			g.draw(diamond);
		}
		else
		{
			g.setColor(Theme.INK_DEEP);
			g.fill(diamond);
			g.setColor(failed ? Theme.BLOOD : Theme.STROKE);
			g.draw(diamond);
		}

		int tx = NODE_X + 14;
		int rightW = 74;
		int nameRoom = w - tx - rightW - 8;
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();

		String name = split != null ? split.getEncounter().getTitle() : Encounter.rowLabel(row);
		if (split != null && bold.stringWidth(name) > nameRoom)
		{
			name = split.getEncounter().getShortName();
		}
		Color nameColor = done ? Theme.TEXT : current ? Theme.mix(Theme.TEAL, Theme.TEXT, 0.55) : failed ? Theme.BLOOD : Theme.TEXT_FAINT;
		g.setFont(split != null ? Theme.title() : Theme.small());
		FontMetrics nameFm = split != null ? bold : small;
		Ui.shadowed(g, Ui.clip(name, nameFm, nameRoom), tx, mid - 2, nameColor);

		g.setFont(Theme.small());
		String sub;
		Color subColor = Theme.TEXT_FAINT;
		if (done)
		{
			sub = "room " + Format.ticks(split.roomTicks(0));
			int bestRoom = bestRooms != null && row < bestRooms.length ? bestRooms[row] : -1;
			if (bestRoom >= 0 && split.roomTicks(0) <= bestRoom)
			{
				subColor = Theme.mix(Theme.GOLD, Theme.TEXT_FAINT, 0.2);
				sub = "best room " + Format.ticks(split.roomTicks(0));
			}
			else if (bestRoom >= 0)
			{
				// What the room alone gave away against its best, apart from how the run stands overall;
				// a long room and its delta close up rather than lose the delta's last figures.
				String delta = Format.delta(split.roomTicks(0) - bestRoom);
				sub = small.stringWidth(sub + "  " + delta) <= nameRoom ? sub + "  " + delta
					: small.stringWidth(sub + " " + delta) <= nameRoom ? sub + " " + delta
					: Format.ticks(split.roomTicks(0)) + " room " + delta;
			}
		}
		else if (current)
		{
			sub = split == null ? "walking in" : "fight " + Format.ticks(split.fightTicks(elapsed));
			subColor = Theme.alpha(Theme.TEAL, 200);
		}
		else if (untimed)
		{
			sub = "not timed";
		}
		else if (failed)
		{
			sub = "the run ended here";
			subColor = Theme.alpha(Theme.BLOOD, 200);
		}
		else
		{
			sub = row == 0 ? "always first" : row == Encounter.ROWS - 1 ? "always last" : "left or right door";
		}
		g.setColor(subColor);
		g.drawString(Ui.clip(sub, small, nameRoom), tx, mid + small.getAscent() + 3);

		// The right column: the run's time at this boss, and the delta under it. The row being
		// fought shows the best's time here as the mark to beat; the crest already runs the clock.
		int rx = w - 10;
		int bestEnd = comparison == null ? -1 : comparison.end(row);
		String time = null;
		Color timeColor = Theme.TEXT;
		if (done)
		{
			time = Format.ticks(split.getEndTick());
		}
		else if (current)
		{
			time = Format.ticks(bestEnd >= 0 ? bestEnd : elapsed);
			timeColor = bestEnd >= 0 ? Theme.alpha(Theme.TEAL, 190) : Theme.mix(Theme.TEAL, Theme.TEXT, 0.4);
		}
		else if (!untimed && !failed && bestEnd >= 0)
		{
			time = Format.ticks(bestEnd);
			timeColor = Theme.TEXT_FAINT;
		}
		if (time != null)
		{
			g.setFont(Theme.body());
			FontMetrics body = g.getFontMetrics();
			Ui.shadowed(g, time, rx - body.stringWidth(time), mid - 2, timeColor);
		}

		Integer delta = done && comparison != null ? comparison.delta(run, row) : null;
		if (current && bestEnd >= 0 && elapsed > bestEnd)
		{
			// While fighting, only show a delta once the run is already behind: being ahead is not known until the boss falls.
			delta = elapsed - bestEnd;
		}
		if (delta != null)
		{
			paintPill(g, Format.delta(delta), Theme.delta(delta), rx, mid + 3);
		}
		else if (!done && time != null && bestEnd >= 0)
		{
			g.setFont(Theme.small());
			String label = current ? "to beat" : comparison.getMode() == Comparison.Mode.PERSONAL_BEST ? "best"
				: comparison.getMode().getShortLabel().toLowerCase();
			g.setColor(current ? Theme.alpha(Theme.TEAL, 170) : Theme.TEXT_FAINT);
			g.drawString(label, rx - small.stringWidth(label), mid + small.getAscent() + 3);
		}
	}

	/** A small rounded tag, right-aligned at x, for a delta. */
	static void paintPill(Graphics2D g, String text, Color color, int right, int top)
	{
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		int pw = fm.stringWidth(text) + 10;
		int ph = fm.getHeight() + 1;
		RoundRectangle2D pill = new RoundRectangle2D.Float(right - pw, top, pw, ph, ph, ph);
		g.setColor(Theme.alpha(color, 40));
		g.fill(pill);
		g.setColor(Theme.alpha(color, 130));
		g.draw(pill);
		g.setColor(color);
		g.drawString(text, right - pw + 5, top + fm.getAscent());
	}
}

package com.codex.archive.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * A vertical stack where every child spans the full width at its preferred height.
 * It tracks the viewport width so nothing ever scrolls sideways in the side panel.
 */
public class StackPanel extends JPanel implements Scrollable
{
	public StackPanel(int gap, int pad)
	{
		super(new StackLayout(gap));
		setOpaque(false);
		setBorder(new EmptyBorder(pad, pad, pad, pad));
	}

	public StackPanel space(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new Dimension(1, height));
		add(spacer);
		return this;
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return Math.max(16, visibleRect.height - 32);
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	static final class StackLayout implements LayoutManager
	{
		private final int gap;

		StackLayout(int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				width = Math.max(width, d.width);
				height += d.height;
				visible++;
			}
			height += Math.max(0, visible - 1) * gap;
			return new Dimension(width + in.left + in.right, height + in.top + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets in = parent.getInsets();
			int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}
}

package com.codex.archive.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tablet: a big number, its label, and a quiet line of context. */
class StatTile extends JComponent
{
	private final String value;
	private final String label;
	private final String note;
	private final Color color;

	StatTile(String value, String label, String note, Color color)
	{
		this.value = value;
		this.label = label;
		this.note = note;
		this.color = color;
		setPreferredSize(new Dimension(10, 54));
		setOpaque(false);
		setToolTipText(note == null || note.isEmpty() ? label : label + ": " + note);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, value, label, note, color, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a tablet in a box; the card uses the same drawing. */
	static void paint(Graphics2D g, String value, String label, String note, Color color, int x, int y, int w, int h)
	{
		RoundRectangle2D shape = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(x, y, Theme.CARD_TOP, x, y + h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);
		g.setColor(Theme.alpha(color, 160));
		g.fillRect(x + Theme.RADIUS, y + 1, w - Theme.RADIUS * 2, 1);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label.toUpperCase(), x + 8, y + 6 + small.getAscent());

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		int baseline = y + 8 + small.getHeight() + bold.getAscent();
		if (bold.stringWidth(value) > w - 16)
		{
			// A clear of ten minutes or more is too wide for a third of the panel in the large face.
			g.setFont(Theme.body());
			bold = g.getFontMetrics();
		}
		Ui.shadowed(g, Ui.clip(value, bold, w - 14), x + 8, baseline, color);
		if (note != null && !note.isEmpty())
		{
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip(note, small, w - 16), x + 8, y + h - 6);
		}
	}
}

package com.codex.archive.ui;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;

/**
 * The Codex look: warm ink, aged gold and a single arcane teal, drawn with the
 * game's own fonts so the panel reads as part of Gielinor rather than a web page.
 * Archive Splits writes time gained on a best in green and time lost in blood, gives the run in
 * progress the arcane teal and keeps the raid's purple for its uniques.
 */
public final class Theme
{
	public static final Color INK = new Color(23, 20, 16);
	public static final Color INK_DEEP = new Color(16, 14, 11);
	public static final Color CARD = new Color(34, 30, 24);
	public static final Color CARD_TOP = new Color(42, 37, 29);
	public static final Color CARD_HOVER = new Color(48, 42, 33);
	public static final Color STROKE = new Color(66, 56, 42);
	public static final Color STROKE_SOFT = new Color(48, 41, 32);

	public static final Color GOLD = new Color(214, 178, 106);
	public static final Color GOLD_BRIGHT = new Color(246, 214, 144);
	public static final Color GOLD_DIM = new Color(132, 108, 66);
	public static final Color TEAL = new Color(96, 184, 170);
	public static final Color GREEN = new Color(130, 196, 108);
	public static final Color EMBER = new Color(222, 134, 86);
	public static final Color BLOCKED = new Color(176, 92, 84);
	public static final Color BLOOD = new Color(204, 70, 60);
	public static final Color BLOOD_DEEP = new Color(120, 32, 28);
	public static final Color VIOLET = new Color(176, 132, 222);

	public static final Color TEXT = new Color(234, 224, 202);
	public static final Color TEXT_MUTED = new Color(160, 148, 126);
	public static final Color TEXT_FAINT = new Color(110, 100, 84);

	public static final int RADIUS = 10;
	public static final int GUTTER = 8;

	private Theme()
	{
	}

	public static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	public static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	public static Color mix(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			(int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	/** Progress colour: ember when just begun, gold through the middle, green when nearly there. */
	public static Color progressColor(double progress)
	{
		if (progress >= 1)
		{
			return GREEN;
		}
		if (progress < 0.5)
		{
			return mix(EMBER, GOLD, progress * 2);
		}
		return mix(GOLD, TEAL, (progress - 0.5) * 2);
	}

	/** Ahead of the best in green, behind in blood. */
	public static final Color AHEAD = GREEN;
	public static final Color BEHIND = new Color(214, 92, 78);
	/** The raid's purple, for uniques. */
	public static final Color PURPLE = new Color(186, 120, 236);
	public static final Color PURPLE_DEEP = new Color(84, 44, 120);
	/** The megarare's own colour, a fiercer gold. */
	public static final Color MEGARARE = new Color(255, 196, 92);

	/** A delta's colour: green when ahead (negative), blood when behind. */
	public static Color delta(int ticks)
	{
		return ticks < 0 ? AHEAD : ticks > 0 ? BEHIND : TEXT_MUTED;
	}

	/** Smooth shapes, but the pixel fonts stay crisp. */
	public static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}
}

package com.codex.archive.ui;

import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.font.FontRenderContext;
import java.awt.font.GlyphVector;
import java.awt.geom.Rectangle2D;

/**
 * A time set large in the pixel font with even spacing. The font gives a colon and a point as
 * much room as a digit, so at three or four times its size a gap opens beside them ("6 :54.0").
 * Its figures are uneven too: a 1 keeps a whole digit's room and a 9 a wide left side ("1 0:0 9.0").
 * Here every figure, colon and point is placed by the ink it draws, one small even gap from the
 * next; letters keep the font's own spacing.
 */
final class Tight
{
	/** The gap between the figures, colons and points of a time, as a share of the font's size. */
	private static final float GAP = 0.07f;

	private Tight()
	{
	}

	/** Where each glyph of a text goes, and how wide the whole is as drawn. */
	static final class Layout
	{
		final String text;
		final float[] pens;
		/** From the first glyph's ink to the last's. */
		final float width;
		private final float lead;

		private Layout(String text, float[] pens, float width, float lead)
		{
			this.text = text;
			this.pens = pens;
			this.width = width;
			this.lead = lead;
		}

		/** Draws it with its ink starting at x, in the graphics' font and paint. */
		void draw(Graphics2D g, float x, float baseline)
		{
			for (int i = 0; i < text.length(); i++)
			{
				g.drawString(String.valueOf(text.charAt(i)), x - lead + pens[i], baseline);
			}
		}
	}

	static boolean narrow(char c)
	{
		return c == ':' || c == '.';
	}

	/** A digit, colon or point: set by its ink, as the font's own spacing of them is uneven. */
	static boolean figure(char c)
	{
		return narrow(c) || (c >= '0' && c <= '9');
	}

	/** Lays a text out in the graphics' current font. */
	static Layout layout(Graphics2D g, String text)
	{
		Font font = g.getFont();
		FontRenderContext frc = g.getFontRenderContext();
		float gap = font.getSize2D() * GAP;
		float[] pens = new float[text.length()];
		float pen = 0;
		float right = 0;
		float lead = 0;
		float advance = 0;
		for (int i = 0; i < text.length(); i++)
		{
			char c = text.charAt(i);
			GlyphVector gv = font.createGlyphVector(frc, String.valueOf(c));
			Rectangle2D box = ink(gv);
			if (i == 0)
			{
				lead = (float) box.getX();
			}
			else if (figure(c) && figure(text.charAt(i - 1)))
			{
				pen = right + gap - (float) box.getX();
			}
			else
			{
				pen += advance;
			}
			pens[i] = pen;
			advance = gv.getGlyphMetrics(0).getAdvance();
			right = pen + (float) (box.getX() + box.getWidth());
		}
		return new Layout(text, pens, right - lead, lead);
	}

	/** The ink a glyph draws, from its pen position; a space is given its advance. */
	private static Rectangle2D ink(GlyphVector gv)
	{
		Rectangle2D box = gv.getVisualBounds();
		return box.isEmpty() ? new Rectangle2D.Float(0, 0, gv.getGlyphMetrics(0).getAdvance(), 0) : box;
	}
}

package com.codex.archive.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.util.List;
import javax.swing.JComponent;

/**
 * Recent clear times, oldest on the left, as beads on a thread. Quicker sits higher, so a
 * line climbing to the right is a raider improving. The best is a gilt rule, the typical
 * time a teal one, and each new best along the way is a filled gold bead.
 */
class TrendChart extends JComponent
{
	private static final int HEIGHT = 86;
	private static final int PAD = 8;
	private static final int LABELS = 36;

	private final List<Integer> times;
	private final int best;
	private final int typical;

	/**
	 * @param times   clear times, oldest first
	 * @param best    the party size's best, drawn as a rule
	 * @param typical the median of these times
	 */
	TrendChart(List<Integer> times, int best, int typical)
	{
		this.times = times;
		this.best = best;
		this.typical = typical;
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setMinimumSize(new Dimension(10, HEIGHT));
		setToolTipText("Your last " + times.size() + " clears, oldest on the left; higher is quicker.");
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(0, 0, Theme.CARD_TOP, 0, h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);
		if (times.isEmpty())
		{
			g.dispose();
			return;
		}
		int lo = Math.min(best, times.get(0));
		int hi = times.get(0);
		for (int t : times)
		{
			lo = Math.min(lo, t);
			hi = Math.max(hi, t);
		}
		if (best > 0)
		{
			lo = Math.min(lo, best);
		}
		// A little air above and below, and never a flat zero range.
		int range = Math.max(10, hi - lo);
		lo -= range / 8;
		hi += range / 8;
		int left = PAD;
		int right = w - PAD - LABELS;
		int top = PAD + 2;
		int bottom = h - PAD - 2;

		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		rule(g, best, lo, hi, top, bottom, left, right, Theme.GOLD, "best", fm, true);
		if (typical > 0 && typical != best)
		{
			rule(g, typical, lo, hi, top, bottom, left, right, Theme.TEAL, "typ", fm, false);
		}

		Path2D line = new Path2D.Float();
		int n = times.size();
		float[] xs = new float[n];
		float[] ys = new float[n];
		for (int i = 0; i < n; i++)
		{
			xs[i] = n == 1 ? (left + right) / 2f : left + (right - left) * i / (float) (n - 1);
			ys[i] = y(times.get(i), lo, hi, top, bottom);
			if (i == 0)
			{
				line.moveTo(xs[i], ys[i]);
			}
			else
			{
				line.lineTo(xs[i], ys[i]);
			}
		}
		g.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.alpha(Theme.TEXT_MUTED, 150));
		g.draw(line);
		g.setStroke(new BasicStroke(1f));
		int record = Integer.MAX_VALUE;
		for (int i = 0; i < n; i++)
		{
			boolean pb = times.get(i) < record;
			record = Math.min(record, times.get(i));
			boolean last = i == n - 1;
			Color c = pb ? Theme.GOLD_BRIGHT : last ? Theme.TEXT : Theme.TEXT_MUTED;
			float r = last ? 3.5f : 2.5f;
			g.setColor(Theme.INK_DEEP);
			g.fill(new java.awt.geom.Ellipse2D.Float(xs[i] - r - 1, ys[i] - r - 1, r * 2 + 2, r * 2 + 2));
			g.setColor(c);
			if (pb)
			{
				g.fill(new java.awt.geom.Ellipse2D.Float(xs[i] - r, ys[i] - r, r * 2, r * 2));
			}
			else
			{
				g.draw(new java.awt.geom.Ellipse2D.Float(xs[i] - r, ys[i] - r, r * 2, r * 2));
			}
		}
		g.dispose();
	}

	private static float y(int ticks, int lo, int hi, int top, int bottom)
	{
		// Quicker is higher.
		return top + (bottom - top) * (ticks - lo) / (float) (hi - lo);
	}

	private static void rule(Graphics2D g, int ticks, int lo, int hi, int top, int bottom, int left, int right, Color color,
		String label, FontMetrics fm, boolean solid)
	{
		if (ticks <= 0)
		{
			return;
		}
		int y = Math.round(y(ticks, lo, hi, top, bottom));
		g.setStroke(solid ? new BasicStroke(1f)
			: new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 1f, new float[]{3f, 3f}, 0f));
		g.setColor(Theme.alpha(color, solid ? 120 : 110));
		g.drawLine(left, y, right, y);
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(color, 220));
		g.drawString(label, right + 8, y + fm.getAscent() / 2 - 1);
	}
}

package com.codex.archive.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import javax.swing.JLabel;

/** Small helpers shared by the panel's components. */
public final class Ui
{
	private Ui()
	{
	}

	public static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	/**
	 * A label that wraps inside the side panel's narrow width. Swing's HTML renderer
	 * treats CSS pixels as points, so the width is converted to keep it in screen pixels.
	 */
	public static JLabel wrapped(String text, Font font, Color color, int width)
	{
		int css = Math.round(width * 0.75f);
		return label("<html><div style='width:" + css + "px'>" + escape(text) + "</div></html>", font, color);
	}

	public static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Lets a clickable card keep its hover and click while the pointer is over its children. */
	static void forwardMouse(Container root, MouseAdapter adapter)
	{
		for (Component child : root.getComponents())
		{
			child.addMouseListener(adapter);
			if (child instanceof Container)
			{
				forwardMouse((Container) child, adapter);
			}
		}
	}

	/** Lets a right-click anywhere on a row, its labels included, open the row's menu. */
	static void inheritPopup(Container root)
	{
		for (Component child : root.getComponents())
		{
			if (child instanceof javax.swing.JComponent)
			{
				((javax.swing.JComponent) child).setInheritsPopupMenu(true);
			}
			if (child instanceof Container)
			{
				inheritPopup((Container) child);
			}
		}
	}

	/** Text with the one pixel black shadow the game puts under its own lettering. */
	public static void shadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	/** Cuts text to fit a width, ending it with an ellipsis. */
	public static String clip(String text, java.awt.FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + "...") > width)
		{
			end--;
		}
		return text.substring(0, end) + "...";
	}
}

package com.codex.archive.ui;

import com.codex.archive.core.Spoils;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A tablet for one unique: a cut gem, lit purple once owned and dark until then, with how many have come. */
class UniqueTile extends JComponent
{
	private final String unique;
	private final int count;

	UniqueTile(String unique, int count)
	{
		this.unique = unique;
		this.count = count;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 66));
		setToolTipText(unique + (count == 0 ? ": not yet" : ": " + count));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		boolean owned = count > 0;
		Color tone = Spoils.isMegarare(unique) ? Theme.MEGARARE : Theme.PURPLE;
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(0, 0, owned ? Theme.mix(Theme.CARD_TOP, tone, 0.12) : Theme.CARD_TOP, 0, h, Theme.CARD));
		g.fill(shape);
		g.setColor(owned ? Theme.alpha(tone, 120) : Theme.STROKE_SOFT);
		g.draw(shape);

		// The gem: a cut lozenge with a bright facet.
		float cx = w / 2f;
		float cy = 22;
		float r = 11;
		if (owned)
		{
			g.setPaint(new RadialGradientPaint(cx, cy, r * 2, new float[]{0, 1}, new Color[]{Theme.alpha(tone, 90), Theme.alpha(tone, 0)}));
			g.fill(new Ellipse2D.Float(cx - r * 2, cy - r * 2, r * 4, r * 4));
		}
		Path2D gem = new Path2D.Float();
		gem.moveTo(cx, cy - r);
		gem.lineTo(cx + r * 0.8f, cy - r * 0.25f);
		gem.lineTo(cx, cy + r);
		gem.lineTo(cx - r * 0.8f, cy - r * 0.25f);
		gem.closePath();
		g.setPaint(owned
			? new GradientPaint(cx - r, cy - r, Theme.mix(tone, Theme.TEXT, 0.45), cx + r, cy + r, Theme.mix(tone, Theme.INK_DEEP, 0.5))
			: new GradientPaint(cx - r, cy - r, Theme.STROKE, cx + r, cy + r, Theme.INK_DEEP));
		g.fill(gem);
		g.setStroke(new BasicStroke(1f));
		g.setColor(owned ? Theme.mix(tone, Theme.TEXT, 0.6) : Theme.STROKE);
		g.draw(new java.awt.geom.Line2D.Float(cx - r * 0.8f, cy - r * 0.25f, cx + r * 0.8f, cy - r * 0.25f));
		g.setColor(Theme.INK_DEEP);
		g.draw(gem);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		String name = Ui.clip(Spoils.shortName(unique), small, w - 8);
		g.setColor(owned ? Theme.TEXT : Theme.TEXT_FAINT);
		g.drawString(name, (w - small.stringWidth(name)) / 2, h - 18);
		String n = owned ? "\u00d7" + count : "not yet";
		g.setColor(owned ? tone : Theme.TEXT_FAINT);
		g.drawString(n, (w - small.stringWidth(n)) / 2, h - 6);
		g.dispose();
	}
}

package com.codex.archive.ui;

import com.codex.archive.core.Archive;
import com.codex.archive.core.Comparison;
import com.codex.archive.core.Encounter;
import com.codex.archive.core.Records;
import com.codex.archive.core.Run;
import com.codex.archive.core.Supply;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;

/** One moment of the plugin's state, handed to the panel and overlays so Swing never reads what the client thread writes. */
public final class View
{
	public final String player;
	public final boolean loggedIn;
	/** A copy of the account's archive, or null with no account open. */
	public final Archive archive;
	/** The run in progress, or null. */
	public final Run live;
	public final boolean inLobby;
	/** What the pack holds now, by supply. */
	public final Map<Supply, Integer> pack;
	/** What the player wants to carry in, by supply. */
	public final Map<Supply, Integer> targets;
	public final long now;
	/** The best run for the live run's party size, or null. */
	public final Run liveBest;
	/** A run cleared moments ago while the player is still inside, for the plaque's last word; or null. */
	public final Run cleared;
	/** What runs are measured against. */
	public final Comparison.Mode compare;
	/** The marks for the live or just-cleared run, never itself; or null with neither. */
	public final Comparison comparison;
	/** Each row's best room for that run's party size, not counting the run itself; -1 where none. */
	public final int[] bestRooms;

	public View(String player, boolean loggedIn, Archive archive, Run live, boolean inLobby,
		Map<Supply, Integer> pack, Map<Supply, Integer> targets, long now)
	{
		this(player, loggedIn, archive, live, inLobby, pack, targets, now, null, Comparison.Mode.PERSONAL_BEST);
	}

	public View(String player, boolean loggedIn, Archive archive, Run live, boolean inLobby,
		Map<Supply, Integer> pack, Map<Supply, Integer> targets, long now, Run cleared)
	{
		this(player, loggedIn, archive, live, inLobby, pack, targets, now, cleared, Comparison.Mode.PERSONAL_BEST);
	}

	public View(String player, boolean loggedIn, Archive archive, Run live, boolean inLobby,
		Map<Supply, Integer> pack, Map<Supply, Integer> targets, long now, Run cleared, Comparison.Mode compare)
	{
		this.player = player;
		this.loggedIn = loggedIn;
		this.archive = archive;
		this.live = live;
		this.inLobby = inLobby;
		this.pack = pack == null ? Collections.emptyMap() : new EnumMap<>(pack);
		this.targets = targets == null ? Collections.emptyMap() : new EnumMap<>(targets);
		this.now = now;
		this.cleared = cleared;
		Run shownRun = live != null ? live : cleared;
		this.liveBest = archive == null || shownRun == null ? null : bestBefore(archive, shownRun);
		this.compare = compare == null ? Comparison.Mode.PERSONAL_BEST : compare;
		this.comparison = archive == null || shownRun == null ? null
			: Comparison.of(archive, Records.bucket(shownRun.getTeamSize()), this.compare, shownRun);
		this.bestRooms = archive == null || shownRun == null ? new int[0] : bestRooms(archive, shownRun);
	}

	/** Each row's best room in a run's party size, from every run but that one. */
	static int[] bestRooms(Archive archive, Run run)
	{
		Comparison golds = Comparison.of(archive.getRuns(), Records.bucket(run.getTeamSize()), Comparison.Mode.BEST_ROOMS, run);
		int[] rooms = new int[Encounter.ROWS];
		for (int row = 0; row < rooms.length; row++)
		{
			rooms[row] = golds.room(row);
		}
		return rooms;
	}

	/** The best run of the same party size, other than the run itself. */
	private static Run bestBefore(Archive archive, Run run)
	{
		Run best = null;
		int bucket = Records.bucket(run.getTeamSize());
		for (Run r : archive.getRuns())
		{
			if (r != run && r.getStartedAt() != run.getStartedAt() && r.isCompleted()
				&& Records.bucket(r.getTeamSize()) == bucket && (best == null || r.getTicks() < best.getTicks()))
			{
				best = r;
			}
		}
		return best;
	}

	/** What the shown run is really measured against: a goal mode with no goal set falls back on the best. */
	public Comparison.Mode measuredAgainst()
	{
		return comparison != null ? comparison.getMode() : compare;
	}

	/** Whether any supply has a target at all; with none, there is no pack check. */
	public boolean checksPack()
	{
		for (int v : targets.values())
		{
			if (v > 0)
			{
				return true;
			}
		}
		return false;
	}

	public static View loggedOut()
	{
		return new View(null, false, null, null, false, null, null, System.currentTimeMillis());
	}

	/** Supplies the pack is short of, against the targets. */
	public Map<Supply, Integer> shortfall()
	{
		Map<Supply, Integer> out = new EnumMap<>(Supply.class);
		for (Supply s : Supply.values())
		{
			int want = targets.getOrDefault(s, 0);
			int have = pack.getOrDefault(s, 0);
			if (have < want)
			{
				out.put(s, want - have);
			}
		}
		return out;
	}
}

package com.codex.archive;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.HashSet;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import org.junit.Test;

/** Every setting has a short name, one plain sentence and a place of its own, worded as across the suite. */
public class SettingsTest
{
	@Test
	public void everySettingIsNamedAndPlacedClearly()
	{
		Set<String> sections = new HashSet<>();
		for (Field f : CodexArchiveConfig.class.getFields())
		{
			if (f.isAnnotationPresent(ConfigSection.class))
			{
				ConfigSection section = f.getAnnotation(ConfigSection.class);
				assertFalse(section.name().isEmpty());
				assertFalse(section.description().isEmpty());
				try
				{
					sections.add((String) f.get(null));
				}
				catch (IllegalAccessException e)
				{
					throw new AssertionError(e);
				}
			}
		}
		Set<String> places = new HashSet<>();
		Set<String> names = new HashSet<>();
		for (Method m : CodexArchiveConfig.class.getMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item == null || item.hidden())
			{
				continue;
			}
			String name = item.name();
			String description = item.description();
			assertTrue(m.getName(), !name.isEmpty() && name.length() <= 26);
			assertTrue(m.getName(), names.add(name));
			assertTrue(m.getName(), Character.isUpperCase(name.charAt(0)) && !name.endsWith("."));
			assertTrue(m.getName() + " " + description.length(), description.length() >= 20 && description.length() <= 220);
			assertTrue(m.getName(), Character.isUpperCase(description.charAt(0)) && !description.endsWith("."));
			// Top-level settings come first; any other sits in a section that exists.
			assertTrue(m.getName() + " is in no known section", item.section().isEmpty() || sections.contains(item.section()));
			assertTrue(m.getName() + " shares its place", places.add(item.section() + "#" + item.position()));
			if ("nameOnCard".equals(item.keyName()))
			{
				assertEquals("Name on cards", name);
			}
			if ("worthOnCard".equals(item.keyName()))
			{
				assertEquals("Worth on cards", name);
			}
		}
		assertFalse(names.isEmpty());
	}

	@Test
	public void savedSettingsKeepTheirKeys()
	{
		// A setting's key is where its value is saved: renaming one quietly resets it for every player
		// who changed it. These are the keys as released; settings may be added and renamed on screen,
		// but not moved.
		assertEquals("codexarchive", CodexArchiveConfig.GROUP);
		Set<String> keys = new HashSet<>();
		for (Method m : CodexArchiveConfig.class.getMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item != null)
			{
				keys.add(item.keyName());
			}
		}
		for (String key : new String[]{"boosts", "brews", "chatSplits", "food", "packPlaque", "restores", "showPlaque"})
		{
			assertTrue(key, keys.contains(key));
		}
	}
}

package com.codex.archive.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class ArchiveTest
{
	private static Run clear(long at)
	{
		RunTracker t = new RunTracker();
		t.begin(at, 0, 3, null);
		t.complete(500);
		return t.finish(510, false);
	}

	@Test
	public void aPurpleDuringTheRunCountsThatRun()
	{
		Archive a = new Archive();
		a.record(clear(1), null, 0);
		a.record(clear(2), null, 0);
		Run third = clear(3);
		a.record(third, Collections.singletonList("Zeal"), 10);
		assertEquals("the streak ends with the run that gave it", 0, a.getDry());
		assertEquals(3, a.getDrops().get(0).getDry());
	}

	@Test
	public void thePanelsCopyIsNotChangedByRemovingAPurple()
	{
		// The panel draws its copy on the Swing thread while the client thread changes the archive.
		Archive a = new Archive();
		a.record(clear(1_000), null, 0);
		a.purple("Zeal", 1_500);
		a.record(clear(2_000), null, 0);
		a.purple("Rondache", 2_500);
		Archive copy = a.copy();
		assertEquals(1, copy.getDrops().get(1).getDry());
		assertTrue(a.removeDrop(1_500, "Zeal"));
		assertEquals(2, a.getDrops().get(0).getDry());
		assertEquals(1, copy.getDrops().get(1).getDry());
	}

	@Test
	public void twoPurplesInOneRun()
	{
		Archive a = new Archive();
		a.record(clear(1), Arrays.asList("Zeal", "Rondache"), 10);
		assertEquals(2, a.getDrops().size());
		assertEquals(1, a.getDrops().get(0).getDry());
		assertEquals(0, a.getDrops().get(1).getDry());
		assertEquals(0, a.getDry());
	}

	@Test
	public void deletingARunTakesItOffTheStreak()
	{
		Archive a = new Archive();
		a.record(clear(1_000), null, 0);
		a.purple("Zeal", 2_000);
		a.record(clear(3_000), null, 0);
		a.record(clear(4_000), null, 0);
		assertEquals(2, a.getDry());
		assertTrue(a.removeRun(4_000));
		assertEquals(1, a.getDry());
		assertTrue("a run before the purple leaves the streak alone", a.removeRun(1_000));
		assertEquals(1, a.getDry());
		assertFalse(a.removeRun(99));
		assertEquals(1, a.getRuns().size());
	}

	@Test
	public void removingAPurpleGivesItsClearsBack()
	{
		Archive a = new Archive();
		for (int i = 1; i <= 3; i++)
		{
			a.record(clear(i * 1_000), null, 0);
		}
		a.purple("Zeal", 3_500);
		a.record(clear(4_000), null, 0);
		a.record(clear(5_000), null, 0);
		a.purple("Rondache", 5_500);
		a.record(clear(6_000), null, 0);
		assertEquals(3, a.getDrops().get(0).getDry());
		assertEquals(2, a.getDrops().get(1).getDry());

		assertTrue(a.removeDrop(3_500, "Zeal"));
		assertEquals("the next purple took longer", 5, a.getDrops().get(0).getDry());
		assertTrue(a.removeDrop(5_500, "Rondache"));
		assertEquals("the newest goes back on the dry streak", 6, a.getDry());
		assertNull(a.getRuns().get(4).getPurple());
		assertFalse(a.removeDrop(5_500, "Rondache"));
	}

	@Test
	public void repairSurvivesAnEmptyOrDamagedSave()
	{
		Archive a = new com.google.gson.Gson().fromJson("{\"runs\":[null,{\"splits\":[{\"encounter\":\"NOT_A_BOSS\"}]}],\"dry\":-3}", Archive.class).repair();
		assertEquals(1, a.getRuns().size());
		assertEquals(Outcome.LEFT, a.getRuns().get(0).getOutcome());
		assertTrue(a.getRuns().get(0).getSplits().isEmpty());
		assertEquals(0, a.getDry());
		assertTrue(a.getDrops().isEmpty());
	}

	private static Run timed(long at, int team, int ticks)
	{
		RunTracker t = new RunTracker();
		t.begin(at, 0, team, null);
		t.engage(Encounter.GUARDIAN, 1);
		t.fell(Encounter.GUARDIAN, ticks / 2, false);
		t.tick(ticks / 2 + RunTracker.CONFIRM_TICKS);
		t.complete(ticks);
		return t.finish(ticks + 5, false);
	}

	@Test
	public void oldRunsGoButRecordsStay()
	{
		Archive a = new Archive();
		a.record(timed(0, 3, 500), null, 0);
		for (int i = 1; i <= Archive.MAX_RUNS + 50; i++)
		{
			a.record(timed(i, 3, 900), null, 0);
		}
		assertEquals(Archive.MAX_RUNS, a.getRuns().size());
		assertEquals("the best is kept however old", 0, a.getRuns().get(0).getStartedAt());
		assertEquals(500, Records.best(a.getRuns(), Records.bucket(3)).getTicks());
		assertEquals("clears are counted apart from the runs kept", Archive.MAX_RUNS + 51, a.clears(Records.bucket(3)));
	}

	@Test
	public void countsComeBackForAnOlderSave()
	{
		Archive a = new Archive();
		a.record(timed(1, 2, 500), null, 0);
		a.record(timed(2, 2, 600), null, 0);
		RunTracker t = new RunTracker();
		t.begin(3, 0, 2, null);
		t.died();
		a.record(t.finish(40, true), null, 0);
		com.google.gson.Gson gson = new com.google.gson.Gson();
		com.google.gson.JsonObject json = gson.toJsonTree(a).getAsJsonObject();
		json.remove("clears");
		json.remove("wipes");
		Archive old = gson.fromJson(json, Archive.class).repair();
		assertEquals(2, old.clears(Records.bucket(2)));
		assertEquals(1, old.wipes(Records.bucket(2)));
		assertTrue(old.removeRun(3));
		assertEquals(0, old.wipes(Records.bucket(2)));
	}

	@Test
	public void longestDryCountsTheStreakNow()
	{
		Archive a = new Archive();
		for (int i = 0; i < 4; i++)
		{
			a.record(clear(i), null, 0);
		}
		a.purple("Zeal", 10);
		a.record(clear(20), null, 0);
		assertEquals(4, a.longestDry());
		for (int i = 0; i < 6; i++)
		{
			a.record(clear(30 + i), null, 0);
		}
		assertEquals(7, a.longestDry());
	}
}

package com.codex.archive.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

/** What each boss of a run was told from, kept so a guessed or missed boss can be checked. */
public class DoubtsTest
{
	private static final Gson GSON = new Gson();

	private static void fight(RunTracker t, Encounter e, String npc, int level, int engage, int fall)
	{
		t.engage(e, engage, npc, level);
		t.fell(e, fall, false);
		for (int i = fall; i <= fall + RunTracker.FINAL_CONFIRM_TICKS; i++)
		{
			t.tick(i);
		}
	}

	@Test
	public void aRunOfNamedBossesHasNothingToCheck()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, 1, null);
		fight(t, Encounter.GUARDIAN, "Archive Guardian", 300, 5, 50);
		fight(t, Encounter.BORK, "Bork", 267, 70, 150);
		fight(t, Encounter.DREADNOTH, "Dreadnoth the Jellied", 400, 170, 250);
		fight(t, Encounter.XARTH, "Xarth", 380, 270, 350);
		fight(t, Encounter.HOODED_FIGURE, "Ocellus", 600, 370, 500);
		Run run = t.finish(520, false);
		assertTrue(run.isCompleted());
		assertFalse(run.hasDoubts());
		assertTrue(Doubts.of(run).isEmpty());
	}

	@Test
	public void aGuessTheNamedBossCorrectedIsNoLongerInDoubt()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, 1, null);
		fight(t, Encounter.GUARDIAN, "Archive Guardian", 300, 5, 50);
		fight(t, Encounter.BORK, "Bork", 267, 70, 150);
		// A big add is hit first and taken for the unnamed boss; then Dreadnoth himself is engaged.
		t.engage(t.resolve("Jelly Spawn", 180), 160, "Jelly Spawn", 180);
		t.engage(Encounter.DREADNOTH, 170, "Dreadnoth the Jellied", 400);
		t.fell(Encounter.DREADNOTH, 250, false);
		for (int i = 250; i < 262; i++)
		{
			t.tick(i);
		}
		Run run = t.finish(300, false);
		assertEquals(Encounter.DREADNOTH, run.split(2).getEncounter());
		assertNull(run.split(2).getSeen());
	}

	@Test
	public void aBossNotRecognisedShowsTheBigFoesTheRunFought()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, 1, null);
		fight(t, Encounter.GUARDIAN, "Archive Guardian", 300, 5, 50);
		// Row 1's boss turned out to have another name: the plugin never opens its split.
		for (int i = 0; i < 5; i++)
		{
			t.foe("Bork the Unbroken", 290);
		}
		t.foe("Smork", 160);
		// Small fry is not counted.
		t.foe("Imp", 7);
		Run run = t.finish(400, true);
		assertEquals(Arrays.asList("Bork the Unbroken (290)", "Smork (160)"), run.getUnknown());
		assertTrue(run.hasDoubts());
		List<String> lines = Doubts.of(run);
		assertEquals(1, lines.size());
		assertEquals("Not timed: Bork / Ezekiel. Big foes no boss name matched: Bork the Unbroken (290), Smork (160).", lines.get(0));
	}

	@Test
	public void addsInATimedRunAreNoDoubt()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, 1, null);
		fight(t, Encounter.GUARDIAN, "Archive Guardian", 300, 5, 50);
		fight(t, Encounter.BORK, "Bork", 267, 70, 150);
		t.foe("Smork", 160);
		fight(t, Encounter.DREADNOTH, "Dreadnoth the Jellied", 400, 170, 250);
		fight(t, Encounter.XARTH, "Xarth", 380, 270, 350);
		fight(t, Encounter.HOODED_FIGURE, "Ocellus", 600, 370, 500);
		Run run = t.finish(520, false);
		assertFalse(run.hasDoubts());
	}

	@Test
	public void addsInAWipeWhereEveryBossReachedWasTimedAreNoDoubt()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, 1, null);
		fight(t, Encounter.GUARDIAN, "Archive Guardian", 300, 5, 50);
		fight(t, Encounter.BORK, "Bork", 267, 70, 150);
		t.foe("Smork", 160);
		// The team falls to Dreadnoth, known by name: every boss reached has its split.
		t.engage(Encounter.DREADNOTH, 170, "Dreadnoth the Jellied", 400);
		Run run = t.finish(300, true);
		assertFalse(run.hasDoubts());
		assertTrue(Doubts.of(run).isEmpty());
	}

	@Test
	public void onlyTheLatestRunsKeepWhatTheyWereToldFrom()
	{
		Archive archive = new Archive();
		for (int i = 0; i < Archive.DOUBT_RUNS + 2; i++)
		{
			RunTracker t = new RunTracker();
			t.begin(i * 1_000_000L, 0, 1, null);
			fight(t, Encounter.GUARDIAN, "Archive Guardian", 300, 5, 50);
			t.foe("Bork the Unbroken", 290);
			archive.record(t.finish(400, true), java.util.Collections.emptyList(), i * 1_000_000L + 1000);
		}
		Archive read = GSON.fromJson(GSON.toJson(archive), Archive.class).repair();
		List<Run> runs = read.getRuns();
		assertEquals(Archive.DOUBT_RUNS + 2, runs.size());
		assertTrue(runs.get(0).getUnknown().isEmpty());
		assertFalse(runs.get(runs.size() - 1).getUnknown().isEmpty());
	}

	@Test
	public void aSaveFromBeforeKeepsReading()
	{
		String old = "{\"runs\":[{\"startedAt\":1,\"teamSize\":1,\"outcome\":\"COMPLETED\",\"ticks\":900,"
			+ "\"splits\":[{\"encounter\":\"GUARDIAN\",\"startTick\":0,\"engageTick\":5,\"endTick\":50}]}]}";
		Archive read = GSON.fromJson(old, Archive.class).repair();
		Run run = read.getRuns().get(0);
		assertNull(run.split(0).getSeen());
		assertEquals(0, run.split(0).getSeenLevel());
		assertTrue(run.getUnknown().isEmpty());
	}
}

package com.codex.archive.core;

import static com.codex.archive.core.InsightsTest.run;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

/** A goal time raced room by room, and the history told in sittings. */
public class GoalAndSessionsTest
{
	private static final Encounter[] ROUTE = {Encounter.GUARDIAN, Encounter.BORK, Encounter.DREADNOTH, Encounter.XARTH,
		Encounter.HOODED_FIGURE};
	private static final long MIN = 60_000L;

	private static List<Run> history()
	{
		// Three trio clears: rooms of 100, 100, 100, 100, 100 ticks at best, and typically 120 each.
		return Arrays.asList(
			run(1, 3, ROUTE, 120, 240, 360, 480, 600),
			run(2, 3, ROUTE, 100, 200, 300, 400, 500),
			run(3, 3, ROUTE, 120, 240, 360, 480, 600));
	}

	@Test
	public void aGoalIsSharedOutInTheShapeOfYourRuns()
	{
		Comparison c = Comparison.of(history(), 2, Comparison.Mode.GOAL, null, 451);
		assertEquals(Comparison.Mode.GOAL, c.getMode());
		// Five equal rooms of 451 ticks: 90 each, and the one tick over goes to the first.
		int sum = 0;
		for (int row = 0; row < Encounter.ROWS; row++)
		{
			assertTrue(c.room(row) == 90 || c.room(row) == 91);
			sum += c.room(row);
		}
		assertEquals(451, sum);
		assertEquals(451, c.total());
		// A run at 500 when the goal's Bork mark is 181 is behind by its own time less the mark.
		Run live = history().get(1);
		assertEquals(Integer.valueOf(200 - c.end(1)), c.delta(live, 1));
	}

	@Test
	public void withoutAGoalTheGoalModeIsTheBest()
	{
		Comparison c = Comparison.of(history(), 2, Comparison.Mode.GOAL, null, 0);
		assertEquals(Comparison.Mode.PERSONAL_BEST, c.getMode());
		assertEquals(500, c.total());
		Archive a = new Archive();
		history().forEach(a::record);
		assertEquals(Comparison.Mode.PERSONAL_BEST, Comparison.of(a, 2, Comparison.Mode.GOAL, null).getMode());
		a.setGoal(2, 450);
		assertEquals(Comparison.Mode.GOAL, Comparison.of(a, 2, Comparison.Mode.GOAL, null).getMode());
		// Other party sizes keep no goal.
		assertEquals(0, a.goal(0));
	}

	@Test
	public void aGoalWithNoRunsMarksOnlyTheWholeRun()
	{
		Comparison c = Comparison.of(new ArrayList<>(), 2, Comparison.Mode.GOAL, null, 1000);
		assertEquals(1000, c.total());
		assertEquals(-1, c.end(0));
		assertEquals(-1, c.room(2));
	}

	@Test
	public void theGoalSaysWhereTheTimeIs()
	{
		List<Run> runs = new ArrayList<>(history());
		// Three more clears, slow in the third row only.
		for (int i = 4; i <= 6; i++)
		{
			runs.add(run(i, 3, ROUTE, 120, 240, 420, 540, 660));
		}
		Goal g = Goal.of(runs, 2, 450);
		assertNotNull(g);
		assertEquals(500, g.getBest());
		assertEquals(50, g.gap());
		assertEquals(0, g.getBeaten());
		// The typical third room (median of 180, 180, 180, 120, 100, 120) is the furthest over the goal's share.
		assertEquals(2, g.getRows().get(0).row);
		assertTrue(g.getRows().get(0).over() > g.getRows().get(1).over());
		Goal beaten = Goal.of(runs, 2, 600);
		assertEquals(3, beaten.getBeaten());
		// Best rooms of 100 each share a 600-tick goal evenly.
		assertEquals(120, beaten.getRows().get(0).allowed);
		assertEquals(30, beaten.getRows().get(0).over());
		assertEquals(1, beaten.getFirst().getStartedAt());
		assertNull(Goal.of(runs, 2, 0));
	}

	@Test
	public void theLiveMarksAndTheGoalCardShareTheGoalAlike()
	{
		List<Run> runs = new ArrayList<>(history());
		for (int i = 4; i <= 6; i++)
		{
			runs.add(run(i, 3, ROUTE, 120, 240, 420, 540, 660));
		}
		// The goal card says what each room is allowed; the splits must race those same marks.
		Comparison c = Comparison.of(runs, 2, Comparison.Mode.GOAL, null, 450);
		for (Goal.Row r : Goal.of(runs, 2, 450).getRows())
		{
			assertEquals("row " + r.row, r.allowed, c.room(r.row));
		}
	}

	@Test
	public void goalTimesAreReadAsPlayersWriteThem()
	{
		assertEquals(2000, Goal.parse("20:00"));
		assertEquals(Math.round((19 * 60 + 42.6) / 0.6), Goal.parse(" 19:42.6 "));
		assertEquals(6250, Goal.parse("1:02:30"));
		// A bare number is minutes, as the prompt asks for: "20" means twenty minutes, not seconds.
		assertEquals(2000, Goal.parse("20"));
		assertEquals(2050, Goal.parse("20.5"));
		assertEquals(-1, Goal.parse("20:75"));
		assertEquals(-1, Goal.parse("twenty"));
		assertEquals(-1, Goal.parse("0:00"));
		assertEquals(-1, Goal.parse(""));
		assertEquals(-1, Goal.parse(null));
	}

	@Test
	public void goalsSurviveASaveAndOlderSavesHaveNone()
	{
		Gson gson = new Gson();
		Archive a = new Archive();
		a.setGoal(5, 3000);
		Archive read = gson.fromJson(gson.toJson(a), Archive.class).repair();
		assertEquals(3000, read.goal(5));
		Archive old = gson.fromJson("{\"runs\":[],\"kc\":3}", Archive.class).repair();
		assertEquals(0, old.goal(2));
		old.setGoal(2, 100);
		assertEquals(100, old.goal(2));
		a.setGoal(9, 100);
		a.setGoal(-1, 100);
		assertEquals(0, a.goal(9));
	}

	@Test
	public void runsAreToldInSittings()
	{
		long day = 1_000_000_000_000L;
		List<Run> runs = new ArrayList<>();
		// Three trio runs in an evening, ten minutes apart, the second a new best and the third a wipe.
		runs.add(run(day, 3, ROUTE, 120, 240, 360, 480, 600));
		runs.add(run(day + 16 * MIN, 3, ROUTE, 100, 200, 300, 400, 500));
		Run wipe = run(day + 31 * MIN, 3, ROUTE, 100, 200);
		runs.add(wipe);
		// The next day, one slower clear.
		runs.add(run(day + 24 * 60 * MIN, 3, ROUTE, 130, 260, 390, 520, 650));
		List<Sessions.Session> all = Sessions.of(runs);
		assertEquals(2, all.size());
		Sessions.Session evening = all.get(0);
		assertEquals(3, evening.getRuns().size());
		assertEquals(2, evening.getClears());
		assertEquals(500, evening.getBest());
		assertEquals(550, evening.getAverage());
		// The first clear and the second both set a best when they were made.
		assertEquals(2, evening.getBests());
		// Ten minutes between the first's end (6:00 in) and the second's start, and the same again to the third.
		assertEquals(10 * MIN, evening.getBetween(), 1);
		Sessions.Session next = all.get(1);
		assertEquals(0, next.getBests());
		assertEquals(-1, next.getBetween());
		assertEquals(0, next.perHour(), 0);
		assertEquals(next.getStart(), Sessions.current(runs, day + 24 * 60 * MIN + 30 * MIN).getStart());
		assertNull(Sessions.current(runs, day + 48 * 60 * MIN));
	}

	@Test
	public void aPartyTabCountsOnlyItsOwnRunsInEachSitting()
	{
		long day = 1_000_000_000_000L;
		List<Run> runs = new ArrayList<>();
		// An evening of a quick solo clear, then two trio clears; the next day, solo only.
		runs.add(run(day, 1, ROUTE, 80, 160, 240, 320, 400));
		runs.add(run(day + 10 * MIN, 3, ROUTE, 120, 240, 360, 480, 600));
		runs.add(run(day + 26 * MIN, 3, ROUTE, 110, 220, 330, 440, 550));
		runs.add(run(day + 24 * 60 * MIN, 1, ROUTE, 90, 180, 270, 360, 450));
		List<Sessions.Session> trio = Sessions.of(runs, 2);
		// The solo-only day has no trio runs, so the trio tab does not list it.
		assertEquals(1, trio.size());
		Sessions.Session evening = trio.get(0);
		assertEquals(2, evening.getCounted().size());
		assertEquals(2, evening.getClears());
		// The solo clear's 400 is not the trio best, and is not in the average.
		assertEquals(550, evening.getBest());
		assertEquals(575, evening.getAverage());
		assertEquals(2, evening.getBests());
		// The sitting itself is whole: it starts at the solo run, and the downtime spans every run.
		assertEquals(day, evening.getStart());
		assertEquals(3, evening.getRuns().size());
		// Clears an hour counts only trio clears over the whole sitting.
		double span = Sessions.endOf(runs.get(2)) - day;
		assertEquals(2 * 3_600_000.0 / span, evening.perHour(), 1e-9);
		List<Sessions.Session> solo = Sessions.of(runs, 0);
		assertEquals(2, solo.size());
		assertEquals(400, solo.get(0).getBest());
		assertEquals(1, solo.get(0).getClears());
	}
}

package com.codex.archive.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class InsightsTest
{
	private static final Encounter[] LEFT = {Encounter.GUARDIAN, Encounter.BORK, Encounter.DREADNOTH, Encounter.XARTH,
		Encounter.HOODED_FIGURE};
	private static final Encounter[] RIGHT = {Encounter.GUARDIAN, Encounter.EZEKIEL, Encounter.DREADNOTH, Encounter.TRIO,
		Encounter.HOODED_FIGURE};

	/** A run through these bosses, each falling at the given tick from the start. */
	static Run run(long at, int team, Encounter[] route, int... falls)
	{
		RunTracker t = new RunTracker();
		t.begin(at, 0, team, null);
		int prev = 0;
		for (int i = 0; i < falls.length; i++)
		{
			t.engage(route[i], prev + 5);
			t.fell(route[i], falls[i], false);
			for (int k = falls[i]; k <= falls[i] + RunTracker.FINAL_CONFIRM_TICKS; k++)
			{
				t.tick(k);
			}
			prev = falls[i];
		}
		return t.finish(prev + 50, false);
	}

	private static List<Run> history()
	{
		return Arrays.asList(
			run(1, 3, LEFT, 100, 200, 300, 400, 500),
			run(2, 3, RIGHT, 90, 210, 290, 420, 480),
			run(3, 3, LEFT, 110, 200, 320, 410, 520),
			run(4, 5, LEFT, 50, 100, 150, 200, 250));
	}

	@Test
	public void personalBestComparesBossByBoss()
	{
		List<Run> runs = history();
		Comparison pb = Comparison.of(runs, 2, Comparison.Mode.PERSONAL_BEST, null);
		assertEquals(480, pb.total());
		assertEquals(210, pb.end(1));
		Run live = run(9, 3, LEFT, 95, 205);
		assertEquals(Integer.valueOf(5), pb.delta(live, 0));
		assertEquals(Integer.valueOf(-5), pb.delta(live, 1));
		assertNull(pb.delta(live, 2));
	}

	@Test
	public void bestRoomsStringTheFastestRoomsTogether()
	{
		Comparison golds = Comparison.of(history(), 2, Comparison.Mode.BEST_ROOMS, null);
		// Each row's fastest room in any of the three trio runs.
		assertEquals(90, golds.room(0));
		assertEquals(90, golds.room(1));
		assertEquals(80, golds.room(2));
		assertEquals(90, golds.room(3));
		assertEquals(60, golds.room(4));
		assertEquals(410, golds.total());
		assertEquals(Records.sumOfBest(history(), 2), golds.total());
	}

	@Test
	public void typicalRunIsTheMedianOfEachRoom()
	{
		Comparison typical = Comparison.of(history(), 2, Comparison.Mode.TYPICAL, null);
		assertEquals(100, typical.room(0));
		assertEquals(100, typical.end(0));
		// Rooms 2: 100, 120, 90.
		assertEquals(100, typical.room(1));
		assertEquals(200, typical.end(1));
	}

	@Test
	public void aRunIsNeverComparedWithItself()
	{
		List<Run> runs = history();
		Run best = runs.get(1);
		Comparison pb = Comparison.of(runs, 2, Comparison.Mode.PERSONAL_BEST, best);
		assertEquals(500, pb.total());
	}

	@Test
	public void missingRowBreaksTheChainOfMarks()
	{
		Comparison none = Comparison.of(Collections.singletonList(run(1, 3, LEFT, 100, 200)), 2, Comparison.Mode.BEST_ROOMS, null);
		assertEquals(200, none.end(1));
		assertEquals(-1, none.end(2));
		assertEquals(-1, none.total());
	}

	@Test
	public void bestPossibleCountsTheRoomBeingFought()
	{
		int[] best = {90, 90, 80, 90, 60};
		Run live = run(9, 3, LEFT, 100, 200);
		// 200 so far, then 80 + 90 + 60 at their best.
		assertEquals(430, Comparison.bestPossible(live, best, 230));
		// Already 120 into a room whose best is 80: that room costs at least what it has taken.
		assertEquals(470, Comparison.bestPossible(live, best, 320));
		assertEquals(-1, Comparison.bestPossible(live, new int[]{90, 90, -1, 90, 60}, 230));
