package com.codex.archive.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.codex.archive.core.Presence.Action;
import org.junit.Test;

public class PresenceTest
{
	@Test
	public void anOpenWorldLobbyThenTheInstance()
	{
		Presence p = new Presence();
		p.lobbyNpc(true, 1);
		assertEquals(Action.NONE, p.tick(2, false, false, 0));
		assertTrue(p.isInLobby());
		p.sceneLoaded(10);
		p.lobbyNpc(false, 10);
		assertEquals(Action.NONE, p.tick(11, true, false, 0));
		assertEquals(Action.NONE, p.tick(12, true, false, 0));
		assertEquals(Action.BEGIN, p.tick(13, true, false, 0));
		assertEquals(11, p.beginTick());
		assertEquals(Action.NONE, p.tick(14, true, true, 3));
		// Out through the exit.
		assertEquals(Action.END, p.tick(800, false, true, 789));
	}

	@Test
	public void aLobbyThatIsItselfAnInstance()
	{
		Presence p = new Presence();
		p.sceneLoaded(1);
		p.tick(2, true, false, 0);
		p.lobbyNpc(true, 3);
		assertEquals("the lobby is not the archive", Action.NONE, p.tick(3, true, false, 0));
		assertEquals(Action.NONE, p.tick(4, true, false, 0));
		assertEquals(Action.NONE, p.tick(40, true, false, 0));
		p.sceneLoaded(50);
		p.lobbyNpc(false, 50);
		p.tick(51, true, false, 0);
		p.tick(52, true, false, 0);
		assertEquals(Action.BEGIN, p.tick(53, true, false, 0));
		assertEquals(Action.NONE, p.tick(300, true, true, 249));
		// Back to the lobby: another instance, with its NPCs about again.
		p.sceneLoaded(900);
		p.lobbyNpc(true, 901);
		assertEquals(Action.END, p.tick(901, true, true, 850));
	}

	@Test
	public void anyOtherInstanceIsNotTheArchive()
	{
		Presence p = new Presence();
		p.sceneLoaded(5);
		assertEquals("no lobby seen", Action.NONE, p.tick(8, true, false, 0));
		p.lobbyNpc(true, 10);
		p.lobbyNpc(false, 20);
		assertEquals(Action.NONE, p.tick(21, false, false, 0));
		p.sceneLoaded(400);
		assertEquals("long after the lobby", Action.NONE, p.tick(403, true, false, 0));
	}

	@Test
	public void lateStartGuessesTheDoor()
	{
		Presence p = new Presence();
		p.lobbyNpc(true, 1);
		p.tick(1, true, false, 0);
		p.lobbyNpc(false, 60);
		assertEquals("left the lobby at 60", 60, p.likelyStart(90));
		p.reset();
		assertFalse(p.isInLobby());
		assertFalse(p.isInInstance());
	}
}

package com.codex.archive.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class RecordsTest
{
	private static Run run(int team, int... falls)
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, team, null);
		Encounter[] route = {Encounter.GUARDIAN, Encounter.BORK, Encounter.DREADNOTH, Encounter.XARTH, Encounter.HOODED_FIGURE};
		int prev = 0;
		for (int i = 0; i < falls.length; i++)
		{
			t.engage(route[i], prev + 5);
			t.fell(route[i], falls[i], false);
			for (int k = falls[i]; k <= falls[i] + RunTracker.FINAL_CONFIRM_TICKS; k++)
			{
				t.tick(k);
			}
			prev = falls[i];
		}
		return t.finish(prev + 50, false);
	}

	@Test
	public void bestsAreKeptPerPartySize()
	{
		List<Run> runs = Arrays.asList(
			run(3, 100, 200, 300, 400, 500),
			run(3, 90, 210, 290, 420, 480),
			run(5, 80, 160, 240, 320, 400),
			run(3, 100, 150));
		Run best = Records.best(runs, Records.bucket(3));
		assertEquals(480, best.getTicks());
		assertEquals(400, Records.best(runs, Records.bucket(5)).getTicks());
		assertNull(Records.best(runs, Records.bucket(1)));
		assertEquals(90, Records.bestRoom(runs, 2, 0));
		assertEquals(50, Records.bestRoom(runs, 2, 1));
		assertEquals(90 + 50 + 80 + 100 + 60, Records.sumOfBest(runs, 2));
		assertEquals(490, Records.recentAverage(runs, 2, 10));
		assertEquals(2, Records.favouriteBucket(runs));
		assertEquals(Integer.valueOf(-60), Records.delta(runs.get(3), best, 1));
		assertEquals(1, Records.count(runs, Outcome.LEFT));
		assertEquals(3, Records.count(runs, Outcome.COMPLETED));
	}

	@Test
	public void purplesResetTheDryStreak()
	{
		Archive a = new Archive();
		for (int i = 0; i < 4; i++)
		{
			a.record(run(3, 10, 20, 30, 40, 50));
		}
		assertEquals(4, a.getDry());
		a.kc(4, 0);
		a.purple("Rondache", 0);
		assertEquals(0, a.getDry());
		assertEquals(4, a.getDrops().get(0).getDry());
		assertEquals(4, a.getDrops().get(0).getKc());
		assertEquals("Rondache", a.last().getPurple());
		a.record(run(3, 10, 20, 30, 40, 50));
		assertEquals(5, a.getKc());
		assertEquals(1, a.getDry());
	}
}

package com.codex.archive.core;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class RoutesAndWallsTest
{
	private static final Encounter[] LEFT = {Encounter.GUARDIAN, Encounter.BORK, Encounter.DREADNOTH, Encounter.XARTH,
		Encounter.HOODED_FIGURE};
	private static final Encounter[] RIGHT = {Encounter.GUARDIAN, Encounter.EZEKIEL, Encounter.DREADNOTH, Encounter.TRIO,
		Encounter.HOODED_FIGURE};

	/** A run through these bosses, each falling at the given tick; ended by a wipe when asked. */
	private static Run run(long at, int team, Encounter[] route, boolean wiped, int... falls)
	{
		return run(at, team, route, wiped, true, falls);
	}

	private static Run run(long at, int team, Encounter[] route, boolean wiped, boolean engageNext, int... falls)
	{
		RunTracker t = new RunTracker();
		t.begin(at, 0, team, null);
		int prev = 0;
		for (int i = 0; i < falls.length; i++)
		{
			t.engage(route[i], prev + 5);
			t.fell(route[i], falls[i], false);
			for (int k = falls[i]; k <= falls[i] + RunTracker.FINAL_CONFIRM_TICKS; k++)
			{
				t.tick(k);
			}
			prev = falls[i];
		}
		if (wiped && engageNext && falls.length < route.length)
		{
			// Fought the next boss, then the party fell.
			t.engage(route[falls.length], prev + 5);
		}
		return t.finish(prev + 50, wiped);
	}

	@Test
	public void routesAreRankedByTheirBestClear()
	{
		List<Run> runs = Arrays.asList(
			run(1, 3, LEFT, false, 100, 200, 300, 400, 500),
			run(2, 3, RIGHT, false, 90, 210, 290, 420, 480),
			run(3, 3, LEFT, false, 110, 200, 320, 410, 520),
			run(4, 3, LEFT, false, 100, 200, 300, 400, 510),
			run(5, 5, LEFT, false, 50, 100, 150, 200, 250));
		List<Insights.RouteStat> routes = Insights.routes(runs, 2);
		assertEquals(2, routes.size());
		assertEquals("Ezekiel, Dreadnoth, Trio", routes.get(0).name());
		assertEquals(480, routes.get(0).best);
		assertEquals(1, routes.get(0).clears);
		Insights.RouteStat left = routes.get(1);
		assertEquals(Arrays.asList(Encounter.BORK, Encounter.DREADNOTH, Encounter.XARTH), left.doors);
		assertEquals(3, left.clears);
		assertEquals(500, left.best);
		assertEquals(510, left.typical);
		// The five-man run is another party size.
		assertEquals(1, Insights.routes(runs, 4).size());
	}

	@Test
	public void aRouteWithAnUntimedDoorIsLeftOut()
	{
		Encounter[] missed = {Encounter.GUARDIAN, Encounter.BORK, Encounter.XARTH, Encounter.HOODED_FIGURE};
		Run gap = run(1, 1, missed, false, 100, 200, 400, 500);
		assertTrue(gap.isCompleted());
		assertNull(Insights.doors(gap));
		assertTrue(Insights.routes(Arrays.asList(gap), 0).isEmpty());
		assertArrayEquals(new int[]{-1, 0}, Insights.routeBest(Arrays.asList(gap), 0, gap));
	}

	@Test
	public void aClearIsMeasuredAgainstItsOwnRoute()
	{
		Run a = run(1, 2, LEFT, false, 100, 200, 300, 400, 500);
		Run b = run(2, 2, RIGHT, false, 90, 180, 270, 360, 450);
		Run c = run(3, 2, LEFT, false, 100, 200, 300, 400, 490);
		List<Run> runs = Arrays.asList(a, b, c);
		// The right-hand route was faster, but this clear is the best on its own.
		assertArrayEquals(new int[]{500, 1}, Insights.routeBest(runs, 1, c));
		assertArrayEquals(new int[]{-1, 0}, Insights.routeBest(runs, 1, b));
	}

	@Test
	public void ladderListsEveryNewBest()
	{
		List<Run> runs = Arrays.asList(
			run(3, 1, LEFT, false, 100, 200, 300, 400, 480),
			run(1, 1, LEFT, false, 100, 200, 300, 400, 520),
			run(2, 1, LEFT, false, 100, 200, 300, 400, 530),
			run(4, 1, LEFT, true, 100, 200),
			run(5, 1, LEFT, false, 100, 200, 300, 400, 470));
		List<Insights.Best> ladder = Insights.ladder(runs, 0);
		assertEquals(3, ladder.size());
		assertEquals(1, ladder.get(0).at);
		assertEquals(-1, ladder.get(0).saved);
		assertEquals(3, ladder.get(1).at);
		assertEquals(520 - 480, ladder.get(1).saved);
		assertEquals(10, ladder.get(2).saved);
		assertEquals(3, Insights.personalBests(runs, 0));
	}

	@Test
	public void wipesArePutOnTheBossBeingFought()
	{
		List<Run> runs = Arrays.asList(
			run(1, 2, LEFT, true, 100, 200, 300),
			run(2, 2, RIGHT, true, 90, 210, 290),
			run(3, 2, LEFT, true, 100, 200, 300),
			run(4, 2, LEFT, false, 100, 200, 300, 400, 500),
			run(5, 2, LEFT, true, 100, 200, 300, 400),
			run(6, 2, LEFT, true, 100));
		List<Insights.Wall> walls = Insights.walls(runs, 1);
		assertEquals(Encounter.XARTH, walls.get(0).encounter);
		assertEquals(2, walls.get(0).wipes);
		// Xarth was reached by four runs: three left-hand runs and the clear.
		assertEquals(4, walls.get(0).tries);
		Insights.Wall trio = walls.stream().filter(w -> w.encounter == Encounter.TRIO).findFirst().get();
		assertEquals(1, trio.wipes);
		assertEquals(1, trio.tries);
		Insights.Wall last = walls.stream().filter(w -> w.encounter == Encounter.HOODED_FIGURE).findFirst().get();
		assertEquals(1, last.wipes);
		assertEquals(2, last.tries);
		// Dreadnoth was never wiped at, so it is not listed.
		assertTrue(walls.stream().noneMatch(w -> w.encounter == Encounter.DREADNOTH));
	}

	@Test
	public void aWipeBeforeTheBossIsSeenIsPutOnlyOnARowWithOneBoss()
	{
		// Wiped on the way to the final room: it can only be the final boss.
		Run toFinal = run(1, 1, LEFT, true, false, 100, 200, 300, 400);
		// Wiped before either door of the first row was seen: no telling which.
		Run toDoor = run(2, 1, LEFT, true, false, 100);
		List<Insights.Wall> walls = Insights.walls(Arrays.asList(toFinal, toDoor), 0);
		assertEquals(1, walls.size());
		assertEquals(Encounter.HOODED_FIGURE, walls.get(0).encounter);
		assertEquals(1, walls.get(0).wipes);
		assertEquals(1, walls.get(0).tries);
	}
}

package com.codex.archive.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.EnumMap;
import java.util.Map;
import org.junit.Test;

public class RunTrackerTest
{
	private static Map<Supply, Integer> pack(int food, int brews)
	{
		Map<Supply, Integer> m = new EnumMap<>(Supply.class);
		m.put(Supply.FOOD, food);
		m.put(Supply.BREWS, brews);
		return m;
	}

	/** Fights one boss: first hit at engage, falls at fall, then waits for the split to close. */
	private static int fight(RunTracker t, Encounter e, int engage, int fall)
	{
		t.engage(e, engage);
		t.fell(e, fall, false);
		for (int i = fall; i <= fall + RunTracker.FINAL_CONFIRM_TICKS; i++)
		{
			t.tick(i);
		}
		return fall + RunTracker.FINAL_CONFIRM_TICKS;
	}

	@Test
	public void timesAWholeRunFromTheEntrance()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 100, 3, pack(20, 16));
		fight(t, Encounter.GUARDIAN, 110, 200);
		fight(t, Encounter.BORK, 230, 330);
		fight(t, Encounter.DREADNOTH, 360, 500);
		t.pack(pack(12, 8));
		fight(t, Encounter.TRIO, 520, 650);
		assertFalse(t.isFinished());
		fight(t, Encounter.HOODED_FIGURE, 700, 900);
		assertTrue(t.isFinished());

		Run run = t.finish(1000, false);
		assertEquals(Outcome.COMPLETED, run.getOutcome());
		assertEquals(800, run.getTicks());
		assertEquals(3, run.getTeamSize());
		assertEquals(5, run.getSplits().size());
		assertEquals("Bork, Dreadnoth, Trio", run.route());
		Split bork = run.split(1);
		assertEquals(100, bork.getStartTick());
		assertEquals(130, bork.getEngageTick());
		assertEquals(130, bork.roomTicks(0));
		assertEquals(100, bork.fightTicks(0));
		assertEquals(Integer.valueOf(8), run.getUsed().get("FOOD"));
		assertEquals(Integer.valueOf(8), run.getUsed().get("BREWS"));
		assertFalse(t.isActive());
	}

	@Test
	public void aPhaseChangeDoesNotCloseTheSplit()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, 2, null);
		t.engage(Encounter.GUARDIAN, 5);
		t.fell(Encounter.GUARDIAN, 50, false);
		t.tick(52);
		// The next form is hit before the fall is confirmed.
		t.engage(Encounter.GUARDIAN, 53);
		for (int i = 53; i < 70; i++)
		{
			t.tick(i);
		}
		assertEquals(0, t.nextRow());
		t.fell(Encounter.GUARDIAN, 120, false);
		for (int i = 120; i < 130; i++)
		{
			t.tick(i);
		}
		assertEquals(1, t.nextRow());
		assertEquals(120, t.view(130).split(0).getEndTick());
	}

	@Test
	public void theTrioFallsWhenTheLastOneDoes()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, 4, null);
		fight(t, Encounter.GUARDIAN, 1, 10);
		fight(t, Encounter.EZEKIEL, 20, 30);
		fight(t, Encounter.NECROMANCER, 40, 50);
		t.engage(Encounter.TRIO, 60);
		t.fell(Encounter.TRIO, 70, true);
		for (int i = 70; i < 90; i++)
		{
			t.tick(i);
		}
		assertEquals(3, t.nextRow());
		t.fell(Encounter.TRIO, 95, false);
		for (int i = 95; i < 110; i++)
		{
			t.tick(i);
		}
		assertEquals(4, t.nextRow());
		assertEquals(95, t.view(110).split(3).getEndTick());
	}

	@Test
	public void aMissedFallClosesWhenTheNextBossIsHit()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, 3, null);
		t.engage(Encounter.GUARDIAN, 5);
		t.engage(Encounter.BORK, 80);
		Run view = t.view(90);
		assertEquals(80, view.split(0).getEndTick());
		assertEquals(80, view.split(1).getStartTick());
		// A stale hit on an earlier row does nothing.
		t.engage(Encounter.GUARDIAN, 95);
		assertEquals(2, t.view(96).getSplits().size());
	}

	@Test
	public void wipesAndEarlyExits()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, 2, null);
		fight(t, Encounter.GUARDIAN, 1, 10);
		t.engage(Encounter.BORK, 20);
		t.died();
		Run wiped = t.finish(60, true);
		assertEquals(Outcome.WIPED, wiped.getOutcome());
		assertEquals(60, wiped.getTicks());
		assertEquals(1, wiped.getDeaths());
		assertFalse(wiped.split(1).isDone());

		t.begin(0, 0, 2, null);
		Run left = t.finish(30, false);
		assertEquals(Outcome.LEFT, left.getOutcome());
	}

	@Test
	public void partySizeGrowsAsRaidersArrive()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, 1, null);
		t.seeTeam(4);
		t.seeTeam(2);
		assertEquals(4, t.view(1).getTeamSize());
		fight(t, Encounter.GUARDIAN, 1, 10);
		t.seeTeam(6);
		assertEquals(4, t.view(20).getTeamSize());
	}

	@Test
	public void aLongPhaseChangeReopensTheSplit()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, 3, null);
		t.engage(Encounter.GUARDIAN, 5);
		t.fell(Encounter.GUARDIAN, 60, false);
		// A cutscene between forms, longer than the confirmation.
		for (int i = 60; i < 80; i++)
		{
			t.tick(i);
		}
		assertEquals(1, t.nextRow());
		t.engage(Encounter.GUARDIAN, 85);
		assertEquals("the second form reopens the split", 0, t.nextRow());
		fight(t, Encounter.GUARDIAN, 86, 150);
		Run view = t.view(170);
		assertEquals(1, view.getSplits().size());
		assertEquals(150, view.split(0).getEndTick());
		assertEquals(5, view.split(0).getEngageTick());
	}

	@Test
	public void aBossLongDownIsNotReopened()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, 3, null);
		fight(t, Encounter.GUARDIAN, 5, 60);
		for (int i = 70; i < 70 + RunTracker.REOPEN_TICKS + 10; i++)
		{
			t.tick(i);
		}
		t.engage(Encounter.GUARDIAN, 200);
		assertEquals(1, t.nextRow());
		assertEquals(60, t.view(201).split(0).getEndTick());
	}

	@Test
	public void theGameSayingCompleteEndsTheRunEvenWithTheLastBossUnseen()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 100, 2, null);
		fight(t, Encounter.GUARDIAN, 110, 200);
		fight(t, Encounter.EZEKIEL, 230, 330);
		fight(t, Encounter.DREADNOTH, 360, 500);
		fight(t, Encounter.XARTH, 520, 650);
		// The final boss is never recognised; the completion message comes.
		t.complete(900);
		assertTrue(t.isFinished());
		assertTrue(t.isAnnounced());
		Run run = t.finish(950, false);
		assertEquals(Outcome.COMPLETED, run.getOutcome());
		assertEquals(800, run.getTicks());
		assertEquals(4, run.getSplits().size());
	}

	@Test
	public void theGameSayingCompleteKeepsTheFinalFall()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, 2, null);
		fight(t, Encounter.GUARDIAN, 1, 10);
		fight(t, Encounter.BORK, 20, 30);
		fight(t, Encounter.DREADNOTH, 40, 50);
		fight(t, Encounter.TRIO, 60, 70);
		t.engage(Encounter.HOODED_FIGURE, 90);
		t.fell(Encounter.HOODED_FIGURE, 200, false);
		t.tick(201);
		assertEquals("the clock stops at the fall while it is confirmed", 200, t.elapsed(203));
		t.complete(202);
		Run run = t.finish(260, false);
		assertEquals(200, run.getTicks());
		assertEquals(200, run.split(4).getEndTick());
		// Nothing reopens once the game has spoken.
		t.engage(Encounter.HOODED_FIGURE, 205);
		assertFalse(t.isActive());
	}

	@Test
	public void anOpenEarlierBossIsDroppedWhenTheRunCompletes()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, 2, null);
		fight(t, Encounter.GUARDIAN, 1, 10);
		t.engage(Encounter.BORK, 20);
		t.complete(400);
		Run run = t.finish(410, false);
		assertEquals(Outcome.COMPLETED, run.getOutcome());
		assertNull(run.split(1));
		assertEquals(400, run.getTicks());
	}

	@Test
	public void theFirstFallReportedIsTheOneKept()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, 2, null);
		t.engage(Encounter.GUARDIAN, 5);
		t.fell(Encounter.GUARDIAN, 40, false);
		// The body leaving a few ticks later reports again.
		t.fell(Encounter.GUARDIAN, 44, false);
		for (int i = 40; i < 60; i++)
		{
			t.tick(i);
		}
		assertEquals(40, t.view(60).split(0).getEndTick());
	}

	@Test
	public void everyPurpleOfARunIsKept()
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, 2, null);
		t.purple("Rondache");
		t.purple("Zeal");
		assertEquals(2, t.purples().size());
		assertEquals("Rondache", t.view(1).getPurple());
		t.begin(0, 0, 2, null);
		assertTrue(t.purples().isEmpty());
	}

}

package com.codex.archive.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class StandingTest
{
	@Test
	public void standsAgainstOnlyTheRunsBeforeIt()
	{
		Run first = StandingTestRuns.run(1_000, 3, false, 100, 300, 500, 700, 1000);
		Run second = StandingTestRuns.run(2_000, 3, false, 90, 310, 480, 690, 980);
		// A quicker run later does not take "new best" away from the second.
		Run later = StandingTestRuns.run(3_000, 3, false, 80, 250, 400, 600, 900);
		// Another party size never counts.
		Run duo = StandingTestRuns.run(1_500, 2, false, 50, 100, 150, 200, 300);
		List<Run> runs = Arrays.asList(first, second, later, duo);

		Standing s = Standing.of(runs, second);
		assertTrue(s.isNewBest());
		assertFalse(s.isFirstClear());
		assertEquals(first, s.getPriorBest());
		assertEquals(-20, (int) s.totalDelta());
		assertEquals(2, s.getClearNumber());
		// Guardian's room 90 beat 100; Bork's room 220 did not beat 200; Dreadnoth's 170 beat 200.
		assertTrue(s.isGold(0));
		assertFalse(s.isGold(1));
		assertTrue(s.isGold(2));
		assertEquals(5, s.getComparedRooms());
		// At Bork the run stood 10 ticks behind the best before it.
		assertEquals(10, (int) s.delta(1));
		assertEquals(-20, (int) s.delta(4));

		Standing f = Standing.of(runs, first);
		assertTrue(f.isFirstClear());
		assertTrue(f.isNewBest());
		assertNull(f.totalDelta());
		assertEquals(1, f.getClearNumber());
		// The first time through, there is nothing to beat: no golds, no rooms compared.
		assertEquals(0, f.getGoldCount());
		assertEquals(0, f.getComparedRooms());
		assertNull(f.delta(0));
	}

	@Test
	public void aWipeIsNeverABestButItsRoomsCountForLaterGolds()
	{
		Run wipe = StandingTestRuns.run(1_000, 3, true, 60, 200);
		Run clear = StandingTestRuns.run(2_000, 3, false, 70, 260, 500, 700, 1000);
		List<Run> runs = Arrays.asList(wipe, clear);

		Standing w = Standing.of(runs, wipe);
		assertFalse(w.isNewBest());
		assertEquals(0, w.getClearNumber());
		assertNull(w.totalDelta());

		Standing c = Standing.of(runs, clear);
		// The first clear, but the wipe timed both rooms quicker (Guardian 60, Bork 140 against 70 and 190): no golds.
		assertTrue(c.isFirstClear());
		assertFalse(c.isGold(0));
		assertFalse(c.isGold(1));
		assertEquals(2, c.getComparedRooms());
	}
}

package com.codex.archive.core;

/** Runs for the standing and run card tests, built through the real tracker. */
public final class StandingTestRuns
{
	private StandingTestRuns()
	{
	}

	/** A run started at a moment, with each boss falling at the given ticks; fewer falls and wiped, a wipe. */
	public static Run run(long at, int team, boolean wiped, int... falls)
	{
		return via(new Encounter[]{Encounter.GUARDIAN, Encounter.BORK, Encounter.DREADNOTH, Encounter.XARTH, Encounter.HOODED_FIGURE}, at, team, wiped, falls);
	}

	/** As {@link #run}, through the doors given. */
	public static Run via(Encounter[] route, long at, int team, boolean wiped, int... falls)
	{
		RunTracker t = new RunTracker();
		t.begin(at, 0, team, null);
		int prev = 0;
		for (int i = 0; i < falls.length; i++)
		{
			t.engage(route[i], prev + 5);
			t.fell(route[i], falls[i], false);
			for (int k = falls[i]; k <= falls[i] + RunTracker.FINAL_CONFIRM_TICKS; k++)
			{
				t.tick(k);
			}
			prev = falls[i];
		}
		if (wiped)
		{
			t.engage(route[falls.length], prev + 5);
			t.died();
		}
		return t.finish(prev + 50, wiped);
	}

	/** The run with these others in its party. */
	public static Run withCrew(Run run, String... names)
	{
		for (String name : names)
		{
			run.addCrew(name);
		}
		return run;
	}

	/** The run with a purple. */
	public static Run withPurple(Run run, String unique)
	{
		run.setPurple(unique);
		return run;
	}
}

package com.codex.archive.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.codex.archive.core.Archive;
import com.codex.archive.core.Encounter;
import com.codex.archive.core.Run;
import com.codex.archive.core.RunTracker;
import com.codex.archive.core.Sessions;
import com.codex.archive.core.StandingTestRuns;
import com.codex.archive.core.Supply;
import com.codex.archive.overlay.PackPlaque;
import com.codex.archive.overlay.SplitsPlaque;
import com.google.gson.Gson;
import java.awt.Component;
import java.awt.Container;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * The one saved key, "archive", read back damaged every way a save can be: empty, cut short,
 * the wrong shape, figures too big or below zero, a later version's, or not JSON at all. None
 * may throw, freeze the panel or the cards, or lose the runs that still read.
 */
public class DamagedSaveTest
{
	private static final Gson GSON = new Gson();
	private static final long MIN = 60_000L;

	private static Archive good(int runs)
	{
		Archive a = new Archive();
		for (int i = 0; i < runs; i++)
		{
			boolean wipe = i % 7 == 3;
			Run r = wipe ? StandingTestRuns.run(i * 20 * MIN, 1 + i % 5, true, 90, 310)
				: StandingTestRuns.run(i * 20 * MIN, 1 + i % 5, false, 90, 310, 480, 690, 950 + i % 40);
			a.record(r, i % 9 == 4 ? java.util.Collections.singletonList("Zorya's tome") : null, i * 20 * MIN + 1);
		}
		a.setGoal(2, 900);
		return a;
	}

	private static List<String> damaged(String save)
	{
		List<String> out = new ArrayList<>();
		out.add("");
		out.add("   ");
		out.add("null");
		out.add("{");
		out.add("}");
		out.add("[]");
		out.add("5");
		out.add("\"an archive\"");
		out.add("true");
		out.add("{\"runs\":5}");
		out.add("{\"runs\":\"many\",\"drops\":{}}");
		out.add("{\"runs\":[5,null,\"x\",[1,2],{}],\"kc\":\"lots\"}");
		out.add("{\"kc\":1e30,\"dry\":-40,\"clears\":[-1,-2],\"wipes\":\"no\",\"goals\":[99999999999]}");
		out.add("{\"kc\":-5,\"dry\":2147483647,\"clears\":[2147483647,2147483647,2147483647,2147483647,2147483647]}");
		out.add("{\"runs\":[{\"startedAt\":-1,\"teamSize\":-3,\"outcome\":\"EXPLODED\",\"ticks\":-90,\"splits\":[{\"encounter\":\"NOBODY\"},null,{\"encounter\":\"BORK\",\"startTick\":-5,\"endTick\":-9}],\"used\":{\"FOOD\":null,\"BREWS\":-3},\"crew\":[null,\"\",\"A\",\"B\",\"C\",\"D\",\"E\",\"F\",\"G\",\"H\",\"I\",\"J\"]}]}");
		out.add("{\"runs\":[{\"startedAt\":9223372036854775807,\"teamSize\":2147483647,\"outcome\":\"COMPLETED\",\"ticks\":2147483647}]}");
		out.add("{\"runs\":[{\"startedAt\":1,\"teamSize\":3,\"outcome\":\"COMPLETED\",\"ticks\":1e40}]}");
		out.add("{\u0000￿}{][");
		out.add("﻿" + save);
		out.add(save.replace("{\"runs\":", "{\"version\":99,\"shelf\":{\"a\":[1,{\"b\":2}]},\"runs\":"));
		out.add(save.replaceFirst("\"ticks\":\\d+", "\"ticks\":\"slow\""));
		out.add(save.replaceFirst("\"teamSize\":\\d+", "\"teamSize\":{}"));
		// Every number in turn too big, below zero, a fraction, a word or nothing; every string a number or nonsense; every list and object the wrong shape.
		for (String n : new String[]{"99999999999999999999", "-5", "-9223372036854775808", "9223372036854775807", "2147483648", "1e308", "0.5", "\"many\"", "null", "{}", "[]"})
		{
			out.add(save.replaceAll("(?<=[:\\[,])-?\\d+(\\.\\d+)?(?=[,\\]}])", n));
			out.add(save.replaceFirst("(?<=[:\\[,])-?\\d+(\\.\\d+)?(?=[,\\]}])", n));
		}
		out.add(save.replaceAll("(?<=:)\"[^\"]*\"", "7"));
		out.add(save.replaceAll("(?<=:)\"[^\"]*\"", "\"\""));
		out.add(save.replaceAll("(?<=:)\"[^\"]*\"", "\"NOT_A_THING\""));
		out.add(save.replaceAll("\\[", "{").replaceAll("]", "}"));
		out.add(save.replaceAll("(?<=:)\\{", "[").replaceAll("}(?=[,}])", "]"));
		for (int cut = 1; cut < 20; cut++)
		{
			out.add(save.substring(0, save.length() * cut / 20));
		}
		return out;
	}

	@Test
	public void everyDamagedSaveReadsWithoutThrowingAndDrawsEverywhere()
	{
		String save = GSON.toJson(good(30));
		for (String bad : damaged(save))
		{
			Archive.Loaded read = Archive.read(GSON, bad);
			assertNotNull(bad, read);
			Archive a = read.archive != null ? read.archive : new Archive();
			draw(a, bad);
			// What was read saves and reads back whole.
			Archive.Loaded again = Archive.read(GSON, GSON.toJson(a));
			assertFalse(bad, again.damaged);
			assertEquals(bad, a.getRuns().size(), again.archive.getRuns().size());
		}
	}

	@Test
	public void oneDamagedRunNeverCostsTheRest()
	{
		Archive a = good(30);
		String save = GSON.toJson(a);
		// The third run's time is no longer a number.
		int at = nth(save, "\"ticks\":", 3);
		String bad = save.substring(0, at) + "\"ticks\":\"slow\"" + save.substring(save.indexOf(',', at));
		Archive.Loaded read = Archive.read(GSON, bad);
		assertTrue(read.damaged);
		assertEquals(29, read.archive.getRuns().size());
		assertEquals(a.getDrops().size(), read.archive.getDrops().size());
		assertEquals(a.getKc(), read.archive.getKc());
		assertEquals(900, read.archive.goal(2));

		// A save cut off in its runs keeps every run before the cut.
		String cut = save.substring(0, nth(save, "\"startedAt\":", 21));
		Archive.Loaded part = Archive.read(GSON, cut);
		assertTrue(part.damaged);
		assertEquals(20, part.archive.getRuns().size());

		// Nothing that reads at all is no archive, so the plugin starts afresh and keeps the save aside.
		assertNull(Archive.read(GSON, "[1,2,3]").archive);
		assertTrue(Archive.read(GSON, "[1,2,3]").damaged);
		assertFalse(Archive.read(GSON, "").damaged);
		assertFalse(Archive.read(GSON, save).damaged);
	}

	@Test
	public void aLaterVersionsSaveIsSetAsideNotQuietlyDropped()
	{
		String save = GSON.toJson(good(30));
		assertFalse(Archive.read(GSON, save).damaged);
		// Each reads without an error, but the next save would drop what this version does not know.
		String[] later = {
			save.replaceFirst("^\\{", "{\"version\":2,\"shelf\":{\"a\":[1,{\"b\":2}]},"),
			save.replaceFirst("\"runs\":\\[\\{", "\"runs\":[{\"mood\":\"glad\","),
			save.replaceFirst("\"encounter\":\"[A-Z_]+\"", "\"encounter\":\"FIFTH_BOSS\""),
			save.replaceFirst("\"clears\":\\[", "\"clears\":[4,"),
		};
		for (String s : later)
		{
			Archive.Loaded read = Archive.read(GSON, s);
			assertTrue(s.substring(0, 80), read.damaged);
			assertEquals(30, read.archive.getRuns().size());
			assertFalse(Archive.read(GSON, GSON.toJson(read.archive)).damaged);
		}
	}

	@Test
	public void figuresBelowZeroOrTooBigAreSetRight()
	{
		Archive a = Archive.read(GSON, "{\"kc\":-5,\"dry\":-1,\"clears\":[-4,1,2,3,4],\"wipes\":[0,0,0,0,-2],\"goals\":[-60,0,0,0,0],"
			+ "\"runs\":[{\"startedAt\":1000,\"teamSize\":3,\"outcome\":\"COMPLETED\",\"ticks\":-90,\"kc\":-3,\"deaths\":-1,\"used\":{\"FOOD\":-2,\"BREWS\":4}}]}").archive;
		assertEquals(0, a.getKc());
		assertEquals(0, a.getDry());
		assertEquals(0, a.clears(0));
		assertEquals(0, a.wipes(4));
		assertEquals(0, a.goal(0));
		Run r = a.getRuns().get(0);
		assertEquals(0, r.getTicks());
		assertEquals(0, r.getKc());
		assertEquals(0, r.getDeaths());
		assertEquals(1, r.getUsed().size());
	}

	@Test
	public void aFullArchiveIsQuickOnTheClientThread()
	{
		Archive a = good(Archive.MAX_RUNS);
		String save = GSON.toJson(a);
		RunTracker t = new RunTracker();
		t.begin(System.currentTimeMillis(), 0, 3, null);
		t.engage(Encounter.GUARDIAN, 20);
		Run live = t.view(200);
		Map<Supply, Integer> pack = new EnumMap<>(Supply.class);
		// Warm up, then time what runs on the client thread: the load, the copy handed to the
		// panel after a change, and the view made every tick of a run.
		for (int i = 0; i < 5; i++)
		{
			Archive.read(GSON, save);
			new View("Gilded Owl", true, a, live, false, pack, pack, 0);
		}
		long load = time(() -> Archive.read(GSON, save));
		long copy = time(a::copy);
		// The copy is the archive whole: it saves the very same.
		assertEquals(save, GSON.toJson(a.copy()));
		long tick = time(() -> new View("Gilded Owl", true, a, live, false, pack, pack, 0));
		System.out.println("Full archive: load " + load / 1000 + "us, copy " + copy / 1000 + "us, tick " + tick / 1000 + "us");
		assertTrue("load " + load / 1000 + "us", load < 60_000_000L);
		assertTrue("copy " + copy / 1000 + "us", copy < 3_000_000L);
		assertTrue("tick " + tick / 1000 + "us", tick < 3_000_000L);
	}

	private static long time(Runnable r)
	{
		long best = Long.MAX_VALUE;
		for (int i = 0; i < 5; i++)
		{
			long t0 = System.nanoTime();
			r.run();
			best = Math.min(best, System.nanoTime() - t0);
		}
		return best;
	}

	private static int nth(String s, String what, int n)
	{
		int at = -1;
		for (int i = 0; i < n; i++)
		{
			at = s.indexOf(what, at + 1);
		}
		return at;
	}

	/** Every page of the panel, both plaques and every card, from this archive. */
	private static void draw(Archive a, String why)
	{
		Map<Supply, Integer> targets = new EnumMap<>(Supply.class);
		targets.put(Supply.FOOD, 10);
		Map<Supply, Integer> pack = new EnumMap<>(Supply.class);
		RunTracker t = new RunTracker();
		t.begin(System.currentTimeMillis(), 0, 3, pack);
		t.engage(Encounter.GUARDIAN, 20);
		Run live = t.view(300);
		long now = System.currentTimeMillis();
		for (Run shownRun : new Run[]{null, live})
		{
			View v = new View("Gilded Owl", true, a, shownRun, shownRun == null, pack, targets, now);
			ArchivePanel p = new ArchivePanel();
			p.update(v);
			p.onActivate();
			for (int tab = 0; tab < 3; tab++)
			{
				p.showTab(tab);
				paint(p);
			}
			SplitsPlaque sp = new SplitsPlaque();
			sp.setEnabled(true);
			sp.show(v);
			PackPlaque pp = new PackPlaque();
			pp.setEnabled(true);
			pp.show(v);
			BufferedImage img = new BufferedImage(300, 300, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = img.createGraphics();
			sp.render(g);
			pp.render(g);
			g.dispose();
		}
		List<Run> all = a.getRuns();
		for (Run r : all)
		{
			assertNotNull(why, RunCard.render(com.codex.archive.core.Standing.of(all, r), "Gilded Owl", ZoneOffset.UTC));
		}
		for (Sessions.Session s : Sessions.of(all))
		{
			assertNotNull(why, SessionCard.render(s, all, null, ZoneOffset.UTC));
		}
	}

	private static void paint(Component c)
	{
		c.setSize(225, 2400);
		layout(c);
		BufferedImage img = new BufferedImage(225, 2400, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		c.paint(g);
		g.dispose();
	}

	private static void layout(Component c)
	{
		c.doLayout();
		if (c instanceof Container)
		{
			for (Component k : ((Container) c).getComponents())
			{
				layout(k);
			}
		}
	}
}

package com.codex.archive.ui;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.codex.archive.core.Run;
import com.codex.archive.core.Standing;
import com.codex.archive.core.StandingTestRuns;
import java.awt.image.BufferedImage;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class RunCardTest
{
	@Test
	public void saysWhatTheRunWas()
	{
		Run first = StandingTestRuns.run(1_000, 3, false, 100, 300, 500, 700, 1000);
		Run best = StandingTestRuns.run(2_000, 3, false, 90, 310, 480, 690, 948);
		Run slower = StandingTestRuns.run(3_000, 3, false, 90, 310, 480, 690, 1018);
		Run level = StandingTestRuns.run(4_000, 3, false, 90, 310, 480, 690, 948);
		Run wipe = StandingTestRuns.run(5_000, 3, true, 90, 310);
		List<Run> runs = Arrays.asList(first, best, slower, level, wipe);
		assertEquals("First trio clear", RunCard.verdict(Standing.of(runs, first)));
		assertEquals("New personal best, 31.2s off", RunCard.verdict(Standing.of(runs, best)));
		assertEquals("42.0s behind your best", RunCard.verdict(Standing.of(runs, slower)));
		assertEquals("Level with your best", RunCard.verdict(Standing.of(runs, level)));
		assertEquals("Wiped at Dreadnoth", RunCard.verdict(Standing.of(runs, wipe)));

		// Drawn at twice the panel's scale, the full width of a card, for any of them.
		for (Run r : runs)
		{
			BufferedImage card = RunCard.render(Standing.of(runs, r), "Gilded Owl", ZoneOffset.UTC);
			assertEquals(RunCard.WIDTH * RunCard.SCALE, card.getWidth());
			assertTrue(card.getHeight() > 300);
		}
	}

	@Test
	public void leavesEveryNameOffWhenAskedTo()
	{
		Run r = StandingTestRuns.withCrew(StandingTestRuns.run(1_000, 3, false, 100, 300, 500, 700, 1000), "Ashen Reed", "Quill Wright");
		Standing st = Standing.of(java.util.Collections.emptyList(), r);
		ArchivePanel panel = new ArchivePanel();
		panel.update(new View("Gilded Owl", true, null, null, false, null, null, 2_000));
		BufferedImage nameless = RunCard.render(st, null, false, ZoneId.systemDefault());
		assertFalse(Arrays.equals(pixels(nameless), pixels(panel.runCard(r))));
		// The party's names go too, not only the player's: they are other people's.
		assertFalse(Arrays.equals(pixels(nameless), pixels(RunCard.render(st, null, ZoneId.systemDefault()))));
		panel.setNameOnCard(false);
		assertArrayEquals(pixels(nameless), pixels(panel.runCard(r)));
	}

	private static int[] pixels(BufferedImage image)
	{
		return image.getRGB(0, 0, image.getWidth(), image.getHeight(), null, 0, image.getWidth());
	}
}

package com.codex.archive.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.codex.archive.core.Run;
import com.codex.archive.core.Sessions;
import com.codex.archive.core.StandingTestRuns;
import java.awt.image.BufferedImage;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class SessionCardTest
{
	private static final long MIN = 60_000L;

	private static Sessions.Session only(List<Run> runs)
	{
		List<Sessions.Session> all = Sessions.of(runs);
		assertEquals(1, all.size());
		return all.get(0);
	}

	@Test
	public void saysWhatTheNightBrought()
	{
		// An earlier night sets the best, so this one is measured against it.
		Run before = StandingTestRuns.run(0, 3, false, 90, 310, 480, 690, 948);
		Run a = StandingTestRuns.run(10 * 60 * MIN, 3, false, 90, 310, 480, 690, 1018);
		Run b = StandingTestRuns.run(10 * 60 * MIN + 15 * MIN, 3, false, 90, 310, 480, 690, 990);
		List<Run> all = Arrays.asList(before, a, b);
		Sessions.Session night = only(Arrays.asList(a, b));
		assertEquals("Within 25.2s of your best", SessionCard.verdict(night, all));
		assertEquals("2 clears, no wipes", SessionCard.tally(night));
		assertEquals("Trio", SessionCard.party(night));

		// A purple is told before anything else.
		StandingTestRuns.withPurple(b, "Zorya's tome");
		assertEquals("A purple: Zorya's tome", SessionCard.verdict(night, all));
		assertEquals("Zorya's tome", SessionCard.rows(night, all).get(1).end);
	}

	@Test
	public void tellsANewBestApartFromAFirstClear()
	{
		Run first = StandingTestRuns.run(0, 4, false, 100, 300, 500, 700, 1000);
		Run faster = StandingTestRuns.run(15 * MIN, 4, false, 90, 300, 480, 690, 950);
		List<Run> all = Arrays.asList(first, faster);
		Sessions.Session night = only(all);
		assertEquals("A new personal best", SessionCard.verdict(night, all));
		assertEquals("FIRST", SessionCard.rows(night, all).get(0).tag);
		assertEquals("PB", SessionCard.rows(night, all).get(1).tag);

		// A party of four is no "4 clear".
		Sessions.Session alone = only(Arrays.asList(first));
		assertEquals("A first 4-raider clear", SessionCard.verdict(alone, Arrays.asList(first)));
		assertEquals("6+ raider clear", Format.clear("6+"));
		assertEquals("trio clear", Format.clear("Trio"));
	}

	@Test
	public void aNightOfWipesSaysHowFarItGot()
	{
		Run w1 = StandingTestRuns.run(0, 2, true, 90);
		Run w2 = StandingTestRuns.run(15 * MIN, 2, true, 90, 310);
		List<Run> all = Arrays.asList(w1, w2);
		Sessions.Session night = only(all);
		assertEquals("Furthest: Dreadnoth the Jellied", SessionCard.verdict(night, all));
		// The clears are not counted when there are none.
		assertEquals("2 wipes", SessionCard.tally(night));
		assertNull(SessionCard.bestRun(night));
		BufferedImage card = SessionCard.render(night, all, null, ZoneOffset.UTC);
		assertEquals(RunCard.WIDTH * RunCard.SCALE, card.getWidth());
	}

	@Test
	public void aLongNightShowsItsLatestRuns()
	{
		List<Run> runs = new ArrayList<>();
		for (int i = 0; i < SessionCard.RUNS + 3; i++)
		{
			runs.add(StandingTestRuns.run(i * 20 * MIN, i % 2 == 0 ? 3 : 4, false, 90, 310, 480, 690, 1000 + i));
		}
		Sessions.Session night = only(runs);
		assertEquals("Mixed parties", SessionCard.party(night));
		BufferedImage longer = SessionCard.render(night, runs, "Gilded Owl", ZoneOffset.UTC);
		BufferedImage shorter = SessionCard.render(only(runs.subList(0, SessionCard.RUNS)), runs, "Gilded Owl", ZoneOffset.UTC);
		// Only the latest twelve are drawn, with one line saying the rest are not.
		assertTrue(longer.getHeight() - shorter.getHeight() < 40);
	}

	@Test
	public void aLongSittingKeepsItsBestInSightAndScalesToWhatIsShown()
	{
		// The sitting's best is its very first run, and the slowest is the second: both would be hidden.
		List<Run> runs = new ArrayList<>();
		for (int i = 0; i < SessionCard.RUNS + 3; i++)
		{
			int end = i == 0 ? 900 : i == 1 ? 1400 : 1000 + i;
			runs.add(StandingTestRuns.run(i * 20 * MIN, 3, false, 90, 310, 480, 690, end));
		}
		Sessions.Session night = only(runs);
		List<SessionCard.Row> rows = SessionCard.rows(night, runs);
		Run best = SessionCard.bestRun(night);
		List<Integer> shown = SessionCard.shown(rows, best);
		assertEquals(SessionCard.RUNS, shown.size());
		assertTrue("the best clear is drawn", shown.contains(0));
		assertTrue("the latest run is drawn", shown.contains(rows.size() - 1));
		assertTrue("the slowest hidden run is not", !shown.contains(1));
		// Bars end at the slowest run drawn, not at one left off the card.
		assertEquals(rows.get(rows.size() - 1).run.getTicks(), SessionCard.slowest(rows, shown));

		// A sitting that fits shows every run in order.
		List<SessionCard.Row> few = rows.subList(0, 5);
		assertEquals(Arrays.asList(0, 1, 2, 3, 4), SessionCard.shown(few, best));
	}

	@Test
	public void aSittingWithoutAClearSaysSoOnce()
	{
		Run w1 = StandingTestRuns.run(0, 2, true, 90, 310, 480);
		Run w2 = StandingTestRuns.run(15 * MIN, 2, true, 90, 310, 480, 690);
		List<Run> all = Arrays.asList(w1, w2);
		Sessions.Session night = only(all);
		// The big figure says No clear; nothing beneath it says it again.
		for (String[] tile : SessionCard.tiles(night))
		{
			for (String text : tile)
			{
				assertTrue(text, !text.toLowerCase().contains("clear"));
			}
		}
		String verdict = SessionCard.verdict(night, all);
		assertTrue(verdict, !verdict.toLowerCase().contains("clear"));
		// The deepest room is named in full, never only "Trio", which reads as a party size.
		assertEquals("Furthest: Ocellus", verdict);
		// What the runs did get done instead: three bosses then four.
		assertEquals(Arrays.asList("7", "Bosses", "felled"), Arrays.asList(SessionCard.tiles(night)[0]));

		// A duo stopped by the Dagon'hai is never "at Trio".
		Run duo = StandingTestRuns.via(new com.codex.archive.core.Encounter[]{com.codex.archive.core.Encounter.GUARDIAN,
			com.codex.archive.core.Encounter.EZEKIEL, com.codex.archive.core.Encounter.NECROMANCER, com.codex.archive.core.Encounter.TRIO},
			40 * MIN, 2, true, 90, 310, 480);
		assertEquals("Wiped at the Trio", RunCard.verdict(com.codex.archive.core.Standing.of(Arrays.asList(duo), duo)));
		assertEquals("Furthest: Dagon'hai Trio", SessionCard.verdict(only(Arrays.asList(duo)), Arrays.asList(duo)));
	}

	@Test
	public void timeAtTheArchiveAgreesWithTheClockLine()
	{
		// 15:04:50 to 16:15:10 reads "15:04 to 16:15" on the card: 71 minutes by the clock line.
		long start = (15 * 60 + 4) * MIN + 50_000;
		long end = (16 * 60 + 15) * MIN + 10_000;
		assertEquals("1h 11m", SessionCard.span(start, end));
		assertEquals("1m", SessionCard.span(start, start + 5_000));
		assertEquals("48m", SessionCard.span(0, 48 * MIN + 59_000));
	}
}

package com.codex.archive.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.codex.archive.core.Comparison;
import com.codex.archive.core.Encounter;
import com.codex.archive.core.Run;
import com.codex.archive.core.RunTracker;
import java.util.Arrays;
import org.junit.Test;

public class ShareTest
{
	private static Run run(long at, int... falls)
	{
		Encounter[] route = {Encounter.GUARDIAN, Encounter.BORK, Encounter.DREADNOTH, Encounter.XARTH, Encounter.HOODED_FIGURE};
		RunTracker t = new RunTracker();
		t.begin(at, 0, 3, null);
		int prev = 0;
		for (int i = 0; i < falls.length; i++)
		{
			t.engage(route[i], prev + 5);
			t.fell(route[i], falls[i], false);
			for (int k = falls[i]; k <= falls[i] + RunTracker.FINAL_CONFIRM_TICKS; k++)
			{
				t.tick(k);
			}
			prev = falls[i];
		}
		return t.finish(prev + 50, false);
	}

	@Test
	public void splitsLineUpWithTheirDeltas()
	{
		Run best = run(1, 100, 200, 300, 400, 500);
		Run now = run(2, 95, 210, 300, 390, 480);
		String text = Share.splits(now, Comparison.of(Arrays.asList(best, now), 2, Comparison.Mode.PERSONAL_BEST, now));
		String[] lines = text.split("\n");
		assertEquals(7, lines.length);
		assertEquals("Guardian   0:57.0   room 0:57.0   -3.0", lines[1]);
		assertEquals("Bork       2:06.0   room 1:09.0   +6.0", lines[2]);
		assertEquals("Cleared in 4:48.0, a new best by 12.0s", lines[6]);
		assertTrue(text.endsWith("\n"));
	}

	@Test
	public void versusNamesTheMark()
	{
		assertEquals("4.2s ahead of your best rooms", Format.versus(-7, "your best rooms"));
		assertEquals("level with your typical run", Format.versus(0, "your typical run"));
		assertEquals("1.2s behind your best", Format.versus(2));
	}

	@Test
	public void aTiedClearIsLevelWithTheBest()
	{
		Run best = run(1, 100, 200, 300, 400, 500);
		Run again = run(2, 100, 200, 300, 400, 500);
		String text = Share.splits(again, Comparison.of(Arrays.asList(best, again), 2, Comparison.Mode.PERSONAL_BEST, again));
		assertTrue(text, text.contains("Cleared in 5:00.0, level with the best\n"));
	}
}

package com.codex.archive.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;

public class TightTest
{
	@Test
	public void setsAColonCloseAndEvenBetweenItsFigures()
	{
		Graphics2D g = new BufferedImage(10, 10, BufferedImage.TYPE_INT_ARGB).createGraphics();
		g.setFont(Theme.title().deriveFont(Theme.title().getSize2D() * 3.5f));
		Tight.Layout set = Tight.layout(g, "6:54.0");
		float before = gapBefore(g, set, 1);
		float after = gapBefore(g, set, 2);
		assertEquals(before, after, 0.01);
		// Narrower than the font sets it on its own, which opened a gap at the colon.
		assertTrue(set.width < g.getFontMetrics().stringWidth("6:54.0"));
		g.dispose();
	}

	@Test
	public void setsEveryFigureTheSameDistanceFromTheNext()
	{
		Graphics2D g = new BufferedImage(10, 10, BufferedImage.TYPE_INT_ARGB).createGraphics();
		g.setFont(Theme.title().deriveFont(Theme.title().getSize2D() * 3.5f));
		// The font gives a 1 a digit's room and a 9 a wide left side, which opened "1 0:0 9.0".
		for (String time : new String[]{"10:09.0", "11:43.8", "12:03.6"})
		{
			Tight.Layout set = Tight.layout(g, time);
			float first = gapBefore(g, set, 1);
			for (int i = 2; i < time.length(); i++)
			{
				assertEquals(time + " at " + i, first, gapBefore(g, set, i), 0.01);
			}
		}
		g.dispose();
	}

	/** The space between the ink of glyph i - 1 and glyph i. */
	private static float gapBefore(Graphics2D g, Tight.Layout set, int i)
	{
		java.awt.geom.Rectangle2D prev = g.getFont().createGlyphVector(g.getFontRenderContext(), set.text.substring(i - 1, i)).getVisualBounds();
		java.awt.geom.Rectangle2D next = g.getFont().createGlyphVector(g.getFontRenderContext(), set.text.substring(i, i + 1)).getVisualBounds();
		return (float) ((set.pens[i] + next.getX()) - (set.pens[i - 1] + prev.getX() + prev.getWidth()));
	}
}
